window.STORY = {"title":"명화로 읽는 성경","acts":[{"n":1,"title":"태초에","summary":"창세기의 첫 마당은 창조와 타락, 홍수 심판과 바벨탑, 네 사건으로 모든 것의 시작을 들려줍니다.","range":"창세기 1~11장","cover":"img/genesis-cole.webp","audio":"audio/6b67a4f5bd65.mp3","times":[0.3,3.222],"dur":12.186},{"n":2,"title":"약속을 받은 사람들","summary":"흩어진 사람들 가운데 하나님이 아브라함을 부르시고, 그 약속은 이삭과 야곱을 거쳐 이집트로 내려간 요셉에게까지 이어집니다.","range":"창세기 12~50장","cover":"img/genesis-molnar.webp","audio":"audio/9743a17732eb.mp3","times":[0.3,4.134],"dur":14.25},{"n":3,"title":"이집트를 나와 광야로","summary":"이집트에서 불러내신 백성에게 하나님은 시내산에서 언약을 주시고, 광야 40년 동안 그 말씀대로 사는 법을 훈련시키셨습니다.","range":"출애굽기 ~ 신명기","cover":"img/exodus-roberts.webp","audio":"audio/539b95b86120.mp3","times":[0.3,4.254],"dur":15.066},{"n":4,"title":"약속의 땅","summary":"요단을 건너 약속의 땅을 얻은 백성은 곧 하나님을 왕으로 모시지 않는 어둠에 빠지지만, 그 한가운데 보리밭의 빛줄기가 비칩니다.","range":"여호수아 ~ 룻기","cover":"img/joshua-ark.webp","audio":"audio/17ba484d688e.mp3","times":[0.3,3.678],"dur":14.346},{"n":5,"title":"왕을 세우다","summary":"사사 시대의 끝에서 백성은 왕을 구하고, 사울과 다윗과 솔로몬을 지나 나라는 둘로 갈라집니다.","range":"사무엘상 ~ 열왕기상","cover":"img/samuel1-eeckhout.webp","audio":"audio/261619ddb7cf.mp3","times":[0.3,3.678],"dur":11.994},{"n":6,"title":"갈라진 나라, 외치는 선지자","summary":"엘리야가 하늘로 올라간 뒤, 남과 북 두 나라가 번갈아 무너져 가는 동안 하나님은 선지자들을 잇달아 보내 돌아오라고 외치십니다.","range":"열왕기하 1~17장과 선지서","cover":"img/kings2-1-angeli.webp","audio":"audio/c7518480e03d.mp3","times":[0.3,5.142],"dur":15.042},{"n":7,"title":"무너지는 예루살렘","summary":"북이스라엘이 앗수르에 무너진 뒤, 남유다도 선지자들의 외침을 끝내 듣지 않다가 바벨론에 예루살렘을 잃습니다.","range":"열왕기하 17~25장과 예레미야","cover":"img/kings2-17-sebaste.webp","audio":"audio/4824838d493c.mp3","times":[0.3,4.158],"dur":13.29},{"n":8,"title":"포로와 귀환","summary":"바벨론으로 끌려간 백성은 그곳에서 이방신을 버리는 법을 배우고, 70년 만에 돌아와 성전을 다시 세웁니다.","range":"다니엘 ~ 에스더","cover":"img/daniel-hauslab.webp","audio":"audio/b934e7b13f94.mp3","times":[0.3,3.87],"dur":13.002},{"n":9,"title":"지혜의 노래, 그리고 침묵","summary":"의인의 고난을 묻는 욥기와 지혜의 노래들을 지나, 에스라와 느헤미야가 다시 세운 신앙마저 무너지자 하나님은 말라기를 끝으로 400년 동안 침묵하십니다.","range":"욥기 ~ 말라기","cover":"img/job-tanner.webp","audio":"audio/8651bc430fc9.mp3","times":[0.3,4.878],"dur":16.722},{"n":10,"title":"오신 왕","summary":"400년의 침묵 끝에 예수님이 오시고, 네 권의 복음서는 저마다 다른 눈으로 그분이 누구신가를 들려줍니다.","range":"마태복음 ~ 요한복음","cover":"img/matthew-jordaens.webp","audio":"audio/4890fb0e6a25.mp3","times":[0.3,3.486],"dur":12.474},{"n":11,"title":"땅끝까지","summary":"오순절에 임한 성령은 예루살렘에서 시작한 복음을 바울의 발걸음에 실어 로마까지 보내십니다.","range":"사도행전과 바울 서신","cover":"img/acts-1-elgreco.webp","audio":"audio/0efd6f7d525b.mp3","times":[0.3,3.846],"dur":11.538},{"n":12,"title":"끝까지 지키라","summary":"바울과 사도들은 마지막 편지들에서, 부탁받은 것을 지키며 믿음과 소망과 사랑으로 주님 오실 날을 기다리라고 당부합니다.","range":"디모데전서 ~ 유다서","cover":"img/timothy1-drost.webp","audio":"audio/3fd224e15f0f.mp3","times":[0.3,3.894],"dur":13.938},{"n":13,"title":"새 하늘과 새 땅","summary":"두려워하는 교회에게 주신 마지막 책은, 일곱 인과 나팔과 대접을 지나 새 하늘과 새 땅, 생명수 강가까지 보여 줍니다.","range":"요한계시록","cover":"img/revelation-caroto.webp","audio":"audio/ab67d75313b9.mp3","times":[0.3,4.374],"dur":14.466}],"slides":[{"act":1,"id":"genesis-cole","img":"img/genesis-cole.webp","size":[1600,1178],"title":"에덴 동산","artist":"토머스 콜","year":"1828","museum":"","credit":"Thomas Cole, The Garden of Eden","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Thomas_Cole_-_The_Garden_of_Eden_(1828).jpg","verse":"창세기 1:1","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["태초에 하나님이 천지를 창조하시니라, 성경은 이 한 문장으로 문을 엽니다.","창세기는 기원의 책이어서, 하나님의 기원만 빼고 모든 것의 시작이 이 책에 담겨 있습니다.","창조 이야기는 다른 어떤 책에도 없고, 어떤 종교도 창세기를 가르치지 않습니다.","콜이 그린 동산은 빛과 물과 나무로 가득하고, 그 한가운데에 첫 사람이 아주 작게 서 있습니다."],"audio":"audio/4c90ae2c7d38.mp3","times":[0.3,7.11,15.144,22.578],"dur":30.87},{"act":1,"id":"genesis-carus","img":"img/genesis-carus.webp","size":[1600,1150],"title":"발트해의 추억","artist":"카를 구스타프 카루스","year":"1834–1835","museum":"","credit":"Carl Gustav Carus, Memory of a Wooded Island in the Baltic Sea","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Carl_Gustav_Carus_-_Memory_of_a_Wooded_Island_in_the_Baltic_Sea(Oak_trees_by_the_Sea)_-_Google_Art_Project.jpg","verse":"창세기 1장","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["그런데 창조를 지켜본 사람이 없고 창조보다 진화론을 먼저 배우기에, 많은 사람이 이 말씀을 믿지 못합니다.","여기, 사람이 살지 않는 섬이 하나 있습니다.","그림 속 섬에는 바다와 바위, 바람을 맞은 오래된 나무들뿐입니다."],"audio":"audio/d9ed1e98569d.mp3","times":[0.3,9.318,14.088],"dur":20.556},{"act":1,"id":"genesis-plum","img":"img/genesis-plum.webp","size":[1600,1342],"title":"꽃 핀 과수원","artist":"빈센트 반 고흐","year":"1888","museum":"","credit":"Vincent van Gogh, Orchard in Blossom (Plum Trees)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Vincent_van_Gogh_-_Orchard_in_Blossom_(Plum_Trees)_-_Google_Art_Project.jpg","verse":"창세기 1장","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["그런데 그 섬에서 이런 과수원을 보았다면, 여기를 무인도라고 할 수 있을까요?","아닙니다, 가지런히 자란 나무와 꽃에서 질서를 보았기 때문입니다.","우리 세포 속 DNA는 사람의 설계도이고, 설계도가 있다는 것은 설계자가 있다는 뜻입니다.","아직 사람의 생명에 대해 아는 것은 거의 없지만, 생명이 신비롭다는 것만은 분명합니다."],"audio":"audio/4123168bb6b2.mp3","times":[0.3,7.062,13.632,21.594],"dur":29.07},{"act":1,"id":"genesis-expulsion","img":"img/genesis-expulsion.webp","size":[1600,1156],"title":"에덴 추방","artist":"토머스 콜","year":"1828","museum":"","credit":"Thomas Cole, Expulsion from the Garden of Eden","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Thomas_Cole_-_Expulsion_from_the_Garden_of_Eden_-_Google_Art_Project.jpg","verse":"창세기 3장","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["두 번째 사건은, 생명나무와 선악을 알게 하는 나무가 서 있던 에덴동산 한가운데에서 일어난 타락입니다.","하나님은 사람을 기계로 만들지 않으시고 고를 자유를 주셨기에, 뱀이 꾀었어도 억지로 먹인 것은 아닙니다.","죄의식이 들어와 사람은 두려워 숨었지만, 하나님은 여자의 후손이 뱀을 상하게 하리라는 비밀을 알려 주십니다.","빛이 쏟아지는 문을 등지고, 두 사람이 거친 바위 길로 걸어 나갑니다."],"audio":"audio/3e2ccba72af4.mp3","times":[0.3,9.366,18.576,27.642],"dur":33.942},{"act":1,"id":"genesis-harvest","img":"img/genesis-harvest.webp","size":[1600,1165],"title":"수확하는 사람들","artist":"피터르 브뤼헐 1세","year":"1565","museum":"","credit":"Pieter Bruegel the Elder, The Harvesters","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Pieter_Bruegel_the_Elder-_The_Harvesters_-_Google_Art_Project.jpg","verse":"창세기 1:28","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["다시 1장으로 돌아가면, 하나님이 제일 먼저 하신 명령은 생육하고 번성하라, 복이면서 명령인 말씀입니다.","1장 28절이 밝히는 창조의 목적은, 복을 주시고 정복하고 다스리게 하시려는 것입니다.","다스린다는 것은 힘으로 누르고 군림하는 것이 아니라, 지키고 가꾸고 기리는 것입니다.","누렇게 익은 밀밭에서 사람들이 곡식을 거두고, 나무 그늘에 둘러앉아 함께 먹습니다."],"audio":"audio/5c9cb17e07f6.mp3","times":[0.3,9.63,17.832,25.146],"dur":32.598},{"act":1,"id":"genesis-bassano","img":"img/genesis-bassano.webp","size":[1600,1242],"title":"방주에 오르는 동물","artist":"야코포 바사노","year":"1570","museum":"","credit":"Jacopo Bassano, The Animals Entering Noah's Ark","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:The_Animals_Entering_Noah%27s_Ark_1570s_Jacopo_Bassano.jpg","verse":"창세기 6장","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["세 번째 사건은 심판으로, 땅에 죄가 가득해져 더는 두고 볼 수 없게 되자 하나님은 물로 세상을 심판하십니다.","이 대홍수는 지금으로부터 약 4,300년 전에 일어났습니다.","그때 하나님은, 성경이 당대의 의로운 자라고 부르는 노아를 택하십니다.","그림 속 노아는 붉은 옷을 입고 하늘을 올려다보고, 사자와 소와 새들이 방주로 몰려듭니다."],"audio":"audio/fb147400f03b.mp3","times":[0.3,9.75,16.08,22.77],"dur":30.702},{"act":1,"id":"genesis-aivazovsky","img":"img/genesis-aivazovsky.webp","size":[1600,1240],"title":"대홍수","artist":"이반 아이바좁스키","year":"1864","museum":"","credit":"Ivan Aivazovsky, The Deluge","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Aivazovsky_-_Deluge.jpg","verse":"창세기 7:11","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["홍수 한 주 전, 노아와 가족들은 방주에 들어갑니다.","노아가 600세 되던 해 2월 17일, 큰비가 쏟아지고 깊은 샘들이 터지면서 홍수가 시작됩니다.","40일은 비가 내린 기간이고, 땅이 물에 잠겼다가 물이 다 빠지기까지 홍수는 1년이 걸렸습니다.","사람들은 바위 꼭대기로 몰려 올라가지만, 물은 그 바위마저 삼키고 있습니다."],"audio":"audio/33eba433af82.mp3","times":[0.3,5.718,14.064,22.626],"dur":29.718},{"act":1,"id":"genesis-moran","img":"img/genesis-moran.webp","size":[1600,993],"title":"콜로라도 협곡","artist":"토머스 모런","year":"1873–1874","museum":"","credit":"Thomas Moran, The Chasm of the Colorado","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Smithsonian-Moran-The_Chasm_of_the_Colorado-2287.jpg","verse":"창세기 7장","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["온 땅을 덮은 물에 높은 산들은 대부분 깎여 나가고, 얕고 좁은 곳의 흙이 깊고 넓은 곳에 쌓였을 것입니다.","그렇게 해서 지구 전체에 걸친 퇴적층이 생긴 것이라고 볼 수 있습니다.","그림 속 협곡이 그 유명한 그랜드캐니언으로, 높이가 1~2km, 길이는 400km가 넘는 어마어마한 협곡입니다.","층층이 깎인 붉은 절벽 사이로 구름과 빛이 피어오릅니다."],"audio":"audio/f86b8f43def2.mp3","times":[0.3,9.846,16.248,26.754],"dur":32.502},{"act":1,"id":"genesis-hicks","img":"img/genesis-hicks.webp","size":[1600,1396],"title":"노아의 방주","artist":"에드워드 힉스","year":"1846","museum":"","credit":"Edward Hicks, Noah's Ark","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Edward_Hicks,_American_-_Noah%27s_Ark_-_Google_Art_Project.jpg","verse":"창세기 6:15","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["방주의 크기는 길이 300규빗, 넓이 50규빗, 높이 30규빗이고, 1규빗은 50cm쯤입니다.","실제로 실험해 보니, 이 비율이 높은 파도를 견디기에 가장 좋은 비율이었다고 합니다.","지금 지구에 사는 모든 동물을 다 싣고도 남는 공간입니다.","검은 비구름 아래에서, 짐승들이 줄지어 방주로 오르고 있습니다."],"audio":"audio/a5cab3c02c30.mp3","times":[0.3,9.774,17.424,23.154],"dur":29.166},{"act":1,"id":"genesis-church","img":"img/genesis-church.webp","size":[1600,1061],"title":"열대의 우기","artist":"프레더릭 에드윈 처치","year":"1866","museum":"","credit":"Frederic Edwin Church, Rainy Season in the Tropics","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Frederic_Edwin_Church_-_Rainy_Season_in_the_Tropics_-_Google_Art_Project.jpg","verse":"창세기 9장","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["홍수 뒤에 기후는 완전히 달라졌고, 살 수 있는 땅도 많이 줄었습니다.","하나님은 노아에게 다시 생육하고 번성하여 땅에 충만하라고 하시니, 홍수 전에도 뒤에도 한결같은 명령입니다.","그리고 다시는 홍수로 심판하지 않겠다는 무지개 언약을 주십니다.","그림 속 골짜기 위로, 비구름이 걷히며 무지개가 크게 걸려 있습니다."],"audio":"audio/80cbc8c358fe.mp3","times":[0.3,7.014,16.536,22.506],"dur":28.926},{"act":1,"id":"genesis-bruegel","img":"img/genesis-bruegel.webp","size":[1600,1171],"title":"바벨탑","artist":"피터르 브뤼헐 1세","year":"1563","museum":"","credit":"Pieter Bruegel the Elder, The Tower of Babel","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Pieter_Bruegel_the_Elder_-_The_Tower_of_Babel_(Vienna)_-_Google_Art_Project_-_edited.jpg","verse":"창세기 11장","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["네 번째 사건은 바벨탑으로, 이때까지만 해도 언어가 하나여서 서로 말이 통했습니다.","하나님의 뜻은 온 땅에 두루 퍼지는 것이었는데, 그들은 탑을 쌓고 흩어지지 않으려 했습니다.","다시는 홍수로 심판하지 않겠다는 약속을 믿지 못하고 세운 대책이 바벨탑이고, 그 주동자는 니므롯입니다.","탑은 구름에 닿을 듯 솟아 있지만, 결국 언어가 뒤섞이고 사람들은 흩어집니다."],"audio":"audio/4f13b4e50ced.mp3","times":[0.3,7.95,15.96,25.386],"dur":32.334},{"act":2,"id":"genesis-molnar","img":"img/genesis-molnar.webp","size":[1200,1043],"title":"아브라함의 떠남","artist":"몰나르 요제프","year":"1850","museum":"","credit":"József Molnár, The Departure of Abraham","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Moln%C3%A1r_%C3%81brah%C3%A1m_kik%C3%B6lt%C3%B6z%C3%A9se_1850.jpg","verse":"창세기 12:1","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["바벨에서 흩어진 사람들 가운데, 하나님이 하란에 살던 아브라함을 부르십니다.","75세의 아브라함은 어디로 보내실지도 모른 채, 믿음으로 단번에 따랐습니다.","가족과 낙타와 양 떼가, 아브라함을 따라 먼 길을 걸어갑니다.","이제 아브라함, 이삭, 야곱, 요셉, 네 족장의 이야기가 시작됩니다."],"audio":"audio/ea95f07d3b10.mp3","times":[0.3,7.302,14.76,20.874],"dur":28.086},{"act":2,"id":"genesis-isaacsac","img":"img/genesis-isaacsac.webp","size":[1078,1600],"title":"이삭의 희생","artist":"렘브란트 판레인과 공방","year":"1636","museum":"","credit":"Rembrandt and workshop, The Sacrifice of Isaac","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Ofiara_Abrahama1.jpg","verse":"창세기 22장","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["아브라함은 믿음과 함께 순종도 대단했습니다.","100세에 얻은 독생자 이삭을 하나님께 바칠 수 있는 사람이었습니다.","그림 속 천사가 아브라함의 손목을 붙잡자, 칼이 공중에서 떨어집니다.","하나님도 감동하셔서, 나도 내 독생자를 내놓겠다고 약속하십니다."],"audio":"audio/9273a613ae89.mp3","times":[0.3,5.19,11.592,18.306],"dur":24.726},{"act":2,"id":"genesis-melchi","img":"img/genesis-melchi.webp","size":[1600,1277],"title":"아브라함과 멜기세덱","artist":"페테르 파울 루벤스","year":"1626년경","museum":"","credit":"Peter Paul Rubens, The Meeting of Abraham and Melchizedek","license":"CC0","page":"https://commons.wikimedia.org/wiki/File:Sir_Peter_Paul_Rubens,_The_Meeting_of_Abraham_and_Melchizedek,_c._1626,_NGA_45640.jpg","verse":"창세기 14장","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["조카 롯이 왕들의 전쟁에 잡혀가자, 아브라함은 집에서 기른 318명을 데리고 쫓아가 모두 되찾아 왔습니다.","율법이 있기 전에, 살렘 왕 멜기세덱에게 처음으로 십일조를 드린 사람도 아브라함입니다.","갑옷 차림의 아브라함이, 멜기세덱이 건네는 빵을 받고 있습니다."],"audio":"audio/a2e80841cb7b.mp3","times":[0.3,9.966,17.928],"dur":23.94},{"act":2,"id":"genesis-sodom","img":"img/genesis-sodom.webp","size":[1600,1020],"title":"소돔과 고모라","artist":"존 마틴","year":"1852","museum":"","credit":"John Martin, Sodom and Gomorrah","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:John_Martin_-_Sodom_and_Gomorrah.jpg","verse":"창세기 19장","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["아브라함은 자기 문제로 매달린 적은 없지만, 소돔과 고모라를 위해서는 낯이 뜨거울 만큼 매달렸습니다.","50명, 45명, 40명, 30명, 20명, 10명까지, 중보기도의 시작입니다.","하나님은 소돔과 고모라를 엎으시는 중에도 아브라함을 생각하셔서 롯을 구하셨습니다.","그림 오른쪽에는 불길에 휩싸인 성을 등지고 달아나는 사람들이 보입니다."],"audio":"audio/7cfd18fd61fc.mp3","times":[0.3,8.982,18.432,26.154],"dur":32.574},{"act":2,"id":"genesis-hagar","img":"img/genesis-hagar.webp","size":[1600,1179],"title":"광야의 하갈","artist":"장바티스트 카미유 코로","year":"1835","museum":"","credit":"Jean-Baptiste Camille Corot, Hagar in the Wilderness","license":"CC0","page":"https://commons.wikimedia.org/wiki/File:Hagar_in_the_Wilderness_MET_DT2013.jpg","verse":"창세기 21장","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["자손을 약속하시고도 주지 않으시자, 아브라함의 믿음도 흔들렸습니다.","결국 사라의 말을 듣고, 하갈을 통해 이스마엘을 낳습니다.","그림 속 광야에는 하늘을 우러르는 하갈과 지쳐 누운 아이가 있고, 그 위로 천사가 날아옵니다.","내년에 아들을 낳으리라는 말씀에 사라가 웃었고, 그래서 약속의 아들 이름은 '웃었다'라는 뜻의 이삭입니다."],"audio":"audio/a5e7af0f22d8.mp3","times":[0.3,6.75,12.48,20.562],"dur":29.118},{"act":2,"id":"genesis-pottage","img":"img/genesis-pottage.webp","size":[1600,1317],"title":"에서와 팥죽","artist":"헨드릭 테르브뤼헌","year":"1626","museum":"","credit":"Hendrick ter Brugghen, Esau Selling His Birthright","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Hendrick_ter_Brugghen_(1588_-_1.11.1629)_-_Esau_Sells_his_Birthright_-_1982_-_Gem%C3%A4ldegalerie.jpg","verse":"창세기 25장","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["아버지를 닮아 복되게 산 이삭과 달리, 야곱은 험악한 삶을 살았습니다.","그런데 그 험한 삶은 야곱이 스스로 고른 것이었습니다.","에서는 장난으로 여겼던 것 같지만, 야곱은 팥죽 한 그릇으로 정말 장자의 명분을 샀습니다.","촛불 아래에서, 두 형제가 팥죽 한 그릇을 사이에 두고 마주합니다."],"audio":"audio/e21440c20b00.mp3","times":[0.3,6.99,12.504,20.61],"dur":26.622},{"act":2,"id":"genesis-flinck","img":"img/genesis-flinck.webp","size":[1600,1320],"title":"이삭의 축복","artist":"호베르트 플링크","year":"1638","museum":"","credit":"Govert Flinck, Isaac Blessing Jacob","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Isaak_zegent_Jakob_Rijksmuseum_SK-A-110.jpeg","verse":"창세기 27장","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["야곱은 눈이 보이지 않는 아버지를 리브가와 짜고 속여, 장자의 축복까지 가로챘습니다.","그림 속 침대의 이삭이 야곱의 얼굴을 더듬고, 뒤에서 리브가가 지켜봅니다.","장자의 명분은 축복권이자 재산을 나눌 권리였기에, 에서는 죽여 버리겠다고 할 만큼 화가 났습니다."],"audio":"audio/b58519cb1331.mp3","times":[0.3,7.95,15.072],"dur":23.652},{"act":2,"id":"genesis-ribera","img":"img/genesis-ribera.webp","size":[1600,1210],"title":"야곱의 꿈","artist":"후세페 데 리베라","year":"1639","museum":"","credit":"Jusepe de Ribera, Jacob's Dream","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:El_sue%C3%B1o_de_Jacob,_by_Jos%C3%A9_de_Ribera,_from_Prado_in_Google_Earth.jpg","verse":"창세기 28장","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["리브가는 서둘러, 70세쯤 된 야곱을 외가인 밧단아람으로 도망 보냅니다.","나무 곁 맨땅에 누워 잠든 야곱 위로, 하늘에서 빛이 비칩니다.","하나님은 벧엘 언약으로 야곱을 끝까지 지키겠다고 약속하셨습니다.","그런데 야곱은 그때에도, 평안히 아버지 집으로 돌아오게 하시면 내 하나님이 되실 것이라며 조건을 답니다."],"audio":"audio/ceddc8fe964d.mp3","times":[0.3,7.254,13.488,19.89],"dur":28.734},{"act":2,"id":"genesis-lemoyne","img":"img/genesis-lemoyne.webp","size":[1273,1600],"title":"야곱과 라헬","artist":"프랑수아 르무안","year":"","museum":"","credit":"François Lemoyne, Jacob and Rachel at the Well","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Collection_Motais_de_Narbonne_-_Jacob_et_Rachel_au_puits_(1720)_-_Fran%C3%A7ois_Lemoyne_(71).jpg","verse":"창세기 29장","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["외가에 이른 야곱은 지팡이를 짚고 양 떼 곁에서 라헬을 만납니다.","그러나 외삼촌 라반은 라헬을 주기로 해 놓고 레아를 몰래 들여보내고, 품삯도 열 번이나 속입니다.","아내 둘을 얻는 데만 14년이 걸렸습니다.","그래도 하나님은 벧엘 언약을 기억하셔서, 가족을 이루게 하시고 양 떼를 불려 주십니다."],"audio":"audio/c8c25ca6ad42.mp3","times":[0.3,6.678,15.192,19.722],"dur":27.318},{"act":2,"id":"genesis-hayez","img":"img/genesis-hayez.webp","size":[1600,1160],"title":"야곱과 에서의 만남","artist":"프란체스코 아예츠","year":"1844","museum":"","credit":"Francesco Hayez, The Meeting of Jacob and Esau","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Francesco_Hayez_061.jpg","verse":"창세기 33장","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["얍복강가에서 천사와 씨름한 야곱은, 하나님을 이긴 자라는 뜻의 이스라엘이라는 새 이름을 얻습니다.","에서가 400명을 데리고 온다는 말에, 야곱은 선물을 먼저 보내고 자기는 맨 나중에 갑니다.","그림 속 두 형제는 서로 끌어안고, 뒤에서는 낙타 위의 가족이 그 모습을 지켜봅니다."],"audio":"audio/b629d043bfbc.mp3","times":[0.3,8.454,16.248],"dur":23.676},{"act":2,"id":"genesis-sold","img":"img/genesis-sold.webp","size":[1600,1147],"title":"팔려 가는 요셉","artist":"라파엘리노 보탈라","year":"1636–1642","museum":"","credit":"Raffaellino Bottalla, Joseph Sold by His Brothers","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Raffaellino_Bottalla_-_Joseph_sold_by_his_brothers_-_Google_Art_Project.jpg","verse":"창세기 37장","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["요셉은 아버지에게는 사랑을, 형들에게는 미움을 받았습니다.","아버지가 지어 준 채색옷을 자랑하고, 짚단과 해와 달과 별의 꿈 이야기를 눈치 없이 했기 때문입니다.","도단에서 형들은 요셉을 구덩이에 던졌고, 유다가 나서서 애굽 상인들에게 팔아 버립니다.","그림 한가운데, 초록 옷의 요셉이 형들 사이에서 끌려가고 있습니다."],"audio":"audio/2360f34fd867.mp3","times":[0.3,6.126,14.88,22.842],"dur":29.022},{"act":2,"id":"genesis-velazquez","img":"img/genesis-velazquez.webp","size":[1600,1224],"title":"요셉의 옷","artist":"디에고 벨라스케스","year":"1630","museum":"","credit":"Diego Velázquez, Joseph's Bloody Coat Brought to Jacob","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Diego_Vel%C3%A1zquez_065.jpg","verse":"창세기 37장","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["형들이 요셉의 옷을 펼쳐 들자, 늙은 야곱은 손을 들며 놀랍니다.","요셉을 팔아넘기는 데 앞장섰던 유다는, 슬퍼하는 아버지를 차마 견디지 못해 집을 나갑니다.","맏아들 엘과 동생 오난을 잃고 나서야, 유다는 아들 잃은 슬픔을 알게 됩니다.","아버지를 이해하게 된 유다는 효도하러 돌아가지만, 하필 흉년이 닥칩니다."],"audio":"audio/42d59d3a34a0.mp3","times":[0.3,6.606,14.784,21.714],"dur":28.182},{"act":2,"id":"genesis-tadema","img":"img/genesis-tadema.webp","size":[1251,925],"title":"창고지기 요셉","artist":"로렌스 알마타데마","year":"1874","museum":"","credit":"Lawrence Alma-Tadema, Joseph, Overseer of Pharaoh's Granaries","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Joseph_Overseer_of_Pharaoh%27s_Graneries_1874.jpg","verse":"창세기 41장","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["요셉은 보디발 장군의 집에 노예로 팔려 왔지만, 금세 실력을 인정받아 집사가 됩니다.","보디발의 아내가 유혹해도, '내가 어찌 하나님께 득죄하리요' 하며 뛰쳐나갑니다.","모함으로 갇힌 감옥을 거쳐, 바로의 꿈을 7년 풍년과 7년 흉년으로 풀고 총리가 됩니다.","높은 자리에 앉은 요셉 곁에서 서기가 두루마리에 기록하고, 바닥에는 곡식이 놓여 있습니다."],"audio":"audio/1f0b1904755d.mp3","times":[0.3,8.022,15.048,22.986],"dur":30.558},{"act":2,"id":"genesis-cornelius","img":"img/genesis-cornelius.webp","size":[1600,1299],"title":"요셉과 형들","artist":"페터 폰 코르넬리우스","year":"1816","museum":"","credit":"Peter von Cornelius, Joseph Reveals Himself to His Brothers","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Peter_von_Cornelius_-_Joseph_gibt_sich_seinen_Br%C3%BCdern_zu_erkennen_-_Google_Art_Project.jpg","verse":"창세기 45:5","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["양식을 구하러 온 형들을 요셉은 바로 알아보고, 간첩으로 몰아 형들이 변했는지 시험합니다.","베냐민이 잡혀가게 되자, 유다가 나서서 베냐민 대신 자신을 노예로 잡아 달라고 울부짖습니다.","그림 속 요셉은 어린 동생을 끌어안고, 형들은 무릎을 꿇거나 얼굴을 감쌉니다.","당신들이 나를 이곳에 팔았다고 근심하지 마소서, 하나님이 생명을 구원하시려고 나를 당신들 앞서 보내셨나이다."],"audio":"audio/5e66aa85e4e4.mp3","times":[0.3,8.118,16.032,23.586],"dur":33.054},{"act":2,"id":"genesis-blessing","img":"img/genesis-blessing.webp","size":[1600,1356],"title":"야곱의 축복","artist":"렘브란트 판레인","year":"","museum":"","credit":"Rembrandt, Jacob Blessing the Sons of Joseph","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Rembrandt_van_Rijn_-_Jacob_blessing_Ephraim_and_Manasseh_(Gem%C3%A4ldegalerie_Alte_Meister_Kassel).jpg","verse":"창세기 48장","lecture":"genesis","lectureTitle":"창세기","youtube":"QJWlFiJbIiY","text":["애굽으로 내려간 야곱은 바로 앞에서, 130년을 험악하게 살았다고 고백합니다.","전능하신 하나님이 야곱의 오그라진 손을 펴시고 고집을 깨뜨리시는 데 130년이 걸렸습니다.","남은 17년 동안 야곱은 바로를 축복하고 아들들의 앞날을 예언하며, 거룩하고 신령한 삶을 삽니다.","이제 그 손을 편 야곱이, 요셉의 아들 머리 위에 손을 얹고 축복합니다."],"audio":"audio/6641ebe57bd3.mp3","times":[0.3,7.59,15.864,25.002],"dur":31.398},{"act":3,"id":"exodus-roberts","img":"img/exodus-roberts.webp","size":[1600,1156],"title":"이스라엘의 출애굽","artist":"데이비드 로버츠","year":"1829","museum":"","credit":"David Roberts, The Departure of the Israelites","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:David_Roberts-IsraelitesLeavingEgypt_1828.jpg","verse":"출애굽기 12장","lecture":"exodus","lectureTitle":"출애굽기","youtube":"mRfrwso4N-g","text":["출애굽기는 한마디로 이집트 탈출기입니다.","400년 동안 종살이에 익숙해진 사람들을 하나님이 불러내셨습니다.","준비는 오래 걸렸지만, 막상 떠나는 것은 1박 2일이었습니다.","웅장한 이집트 건물들 사이로, 떠나는 사람들의 행렬이 길게 이어집니다."],"audio":"audio/a148a2fc3d27.mp3","times":[0.3,5.022,11.304,17.538],"dur":24.246},{"act":3,"id":"exodus-poynter","img":"img/exodus-poynter.webp","size":[1600,671],"title":"애굽의 이스라엘","artist":"에드워드 포인터","year":"1867","museum":"","credit":"Edward Poynter, Israel in Egypt","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:1867_Edward_Poynter_-_Israel_in_Egypt.jpg","verse":"출애굽기 1:11","lecture":"exodus","lectureTitle":"출애굽기","youtube":"mRfrwso4N-g","text":["이 탈출에는 긴 앞이야기가 있습니다.","히브리 사람들이 애굽에 들어간 지 300년쯤 지나 크게 불어나자, 요셉을 모르는 새 왕이 일어나 그들을 억누르기 시작합니다.","왕은 나라의 창고인 국고성 비돔과 라암셋을 짓게 했습니다.","그림 속 사람들은 밧줄에 매달려 거대한 사자 석상을 끌고 갑니다."],"audio":"audio/05ee49fd0543.mp3","times":[0.3,4.662,14.832,20.874],"dur":27.126},{"act":3,"id":"exodus-pharaoh","img":"img/exodus-pharaoh.webp","size":[1600,977],"title":"바로에게 말하는 모세","artist":"제임스 티소","year":"1904","museum":"","credit":"James Tissot, Moses Speaks to Pharaoh (photo: Phillip Medhurst)","license":"CC BY-SA 4.0","page":"https://commons.wikimedia.org/wiki/File:Mo%C3%AFse_parle_%C3%A0_Pharaon_(Exodus_5_1)_%E2%80%A2_invenit_James_Tissot_%E2%80%A2_pinxit_James_Tissot_%E2%80%A2_excudit_Maurice_de_Brunoff_apud_Philip_de_Vere_%E2%80%A2_praesentat_Phillip_Medhurst.jpg","verse":"출애굽기 5:2","lecture":"exodus","lectureTitle":"출애굽기","youtube":"mRfrwso4N-g","text":["부르짖음이 하나님께 닿자, 하나님은 아브라함과 이삭과 야곱에게 하신 약속을 기억하시고 모세를 보내십니다.","그러나 바로는 여호와가 누구관대 내가 그 말을 듣고 이스라엘을 보내겠느냐며 거절합니다.","의자에 비스듬히 앉은 바로가, 손을 들고 말하는 모세와 아론을 바라봅니다.","여호와를 모른다고 하니, 이제 알게 해 주실 차례입니다."],"audio":"audio/5c05ffbf1e62.mp3","times":[0.3,9.534,17.424,24.33],"dur":29.574},{"act":3,"id":"exodus-firstborn","img":"img/exodus-firstborn.webp","size":[1600,984],"title":"장자의 죽음","artist":"로렌스 알마타데마","year":"1872","museum":"","credit":"Lawrence Alma-Tadema, The Death of the Pharaoh's Firstborn Son","license":"CC0","page":"https://commons.wikimedia.org/wiki/File:De_dood_van_de_eerstgeborene_van_de_farao,_SK-A-2664.jpg","verse":"출애굽기 12:29","lecture":"exodus","lectureTitle":"출애굽기","youtube":"mRfrwso4N-g","text":["열 가지 재앙은 하나님이 어떤 분이신지 보여 주시는 과정이었습니다.","하나님은 재앙마다 이집트의 신들을 하나씩 치시다가, 마지막에는 태양신 '라'의 아들이라던 바로의 아들까지 치십니다.","그림 속 바로는 숨진 아들을 무릎에 누인 채, 굳은 얼굴로 앉아 있습니다."],"audio":"audio/f2c5a51e35b2.mp3","times":[0.3,6.414,15.936],"dur":22.668},{"act":3,"id":"exodus-sinai","img":"img/exodus-sinai.webp","size":[1600,1111],"title":"시내 산 라하 평원","artist":"데이비드 로버츠","year":"1839","museum":"","credit":"David Roberts, The Plain of El Raheh, Mount Sinai","license":"CC0","page":"https://commons.wikimedia.org/wiki/File:David_Roberts_-_The_Plain_of_El_Raheh,_Mount_Sinai_-_B1975.3.1074_-_Yale_Center_for_British_Art.jpg","verse":"출애굽기 19:5","lecture":"exodus","lectureTitle":"출애굽기","youtube":"mRfrwso4N-g","text":["광야로 나온 백성은 시내산 아래 넓은 평원에 이릅니다.","하나님이 그들을 이집트에서 꺼내신 데에는 계획이 있었습니다.","그것이 출애굽기 19장 5절에서 6절의 시내산 언약, 이스라엘을 제사장 나라로 세우시는 약속입니다.","세계 선교를 함께 하자는 부르심입니다."],"audio":"audio/4de55ace519f.mp3","times":[0.3,5.79,11.328,20.178],"dur":24.198},{"act":3,"id":"exodus-rembrandt","img":"img/exodus-rembrandt.webp","size":[1283,1600],"title":"십계명을 든 모세","artist":"렘브란트 판레인","year":"1659","museum":"","credit":"Rembrandt, Moses with the Ten Commandments","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Rembrandt_-_Moses_with_the_Ten_Commandments_-_Google_Art_Project.jpg","verse":"출애굽기 20장","lecture":"exodus","lectureTitle":"출애굽기","youtube":"mRfrwso4N-g","text":["20장은 십계명입니다.","십계명을 넓히면 율법이 되고, 훗날 예수님은 이것을 하나님 사랑과 이웃 사랑으로 줄이십니다.","모세는 하나님이 직접 새겨 주신 돌판을 머리 위로 높이 들어 올렸습니다.","그런데 산 아래에서는 백성들이 금송아지에게 절을 하고 있었습니다."],"audio":"audio/e437c12b1a84.mp3","times":[0.3,3.606,11.808,18.354],"dur":24.39},{"act":3,"id":"exodus-poussin","img":"img/exodus-poussin.webp","size":[1600,1128],"title":"금송아지 숭배","artist":"니콜라 푸생","year":"1633–1634년경","museum":"","credit":"Nicolas Poussin, The Adoration of the Golden Calf","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:The_Adoration_of_the_Golden_Calf_%E2%80%93_Nicolas_Poussin.jpg","verse":"출애굽기 32:4","lecture":"exodus","lectureTitle":"출애굽기","youtube":"mRfrwso4N-g","text":["화가 난 모세는 돌판을 깨뜨립니다.","아론은 금을 불에 던졌더니 이 송아지가 나왔다고 변명하지만, 32장 4절을 보면 그가 분명히 녹여 붓고 조각칼로 새겨 만들었습니다.","그림 속 사람들은 꽃으로 꾸민 금송아지 둘레에서 춤을 추고, 왼쪽 위 언덕에서는 돌판을 든 모세가 내려오고 있습니다."],"audio":"audio/56d370a0de6b.mp3","times":[0.3,4.422,15.744],"dur":25.404},{"act":3,"id":"leviticus-tabernacle","img":"img/leviticus-tabernacle.webp","size":[1600,1179],"title":"광야의 성막","artist":"작자 미상","year":"1890","museum":"","credit":"Holman Bible (1890), The Tabernacle in the Wilderness","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Holman_The_Tabernacle_in_the_Wilderness.jpg","verse":"레위기 1장","lecture":"leviticus","lectureTitle":"레위기","youtube":"3Yzi_jtZ-GA","text":["하나님은 돌판에 십계명을 다시 새겨 주시고, 백성은 성막을 지어 봉헌합니다.","이어지는 레위기는 딱딱하다고들 하지만, 구약의 중심이요 시내산 언약 그 자체인 책입니다.","1장부터 7장은 번제, 소제, 화목제, 속죄제, 속건제의 다섯 가지 제사입니다.","성막 둘레로 이스라엘의 장막이 끝없이 펼쳐져 있습니다."],"audio":"audio/135381f50d5b.mp3","times":[0.3,7.518,15.432,24.018],"dur":29.262},{"act":3,"id":"leviticus-wedding","img":"img/leviticus-wedding.webp","size":[1600,1106],"title":"농민의 결혼식","artist":"피터르 브뤼헐 1세","year":"1568","museum":"","credit":"Pieter Bruegel the Elder, The Peasant Wedding","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Pieter_Bruegel_the_Elder_-_Peasant_Wedding_-_Google_Art_Project.jpg","verse":"레위기 3장","lecture":"leviticus","lectureTitle":"레위기","youtube":"3Yzi_jtZ-GA","text":["제사 가운데 화목제는 속죄로 끝나지 않고, 반드시 화목까지 가야 하는 나눔의 제사입니다.","바친 사람도 함께 먹을 수 있는데, 소로 드리면 고기가 대략 천 근이라 하루나 이틀 안에 다 먹으려면 모든 사람을 불러야 합니다.","그림 속 잔칫상에는 마을 사람들이 빽빽이 둘러앉았고, 접시를 가득 얹어 나르는 사람들도 보입니다."],"audio":"audio/b5781436f69b.mp3","times":[0.3,8.19,18.528],"dur":27.3},{"act":3,"id":"leviticus-gleaners","img":"img/leviticus-gleaners.webp","size":[1600,1198],"title":"이삭 줍는 사람들","artist":"장프랑수아 밀레","year":"1857","museum":"","credit":"Jean-François Millet, The Gleaners","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Jean-Fran%C3%A7ois_Millet_-_Gleaners_-_Google_Art_Project.jpg","verse":"레위기 25장","lecture":"leviticus","lectureTitle":"레위기","youtube":"3Yzi_jtZ-GA","text":["하나님이 이스라엘과 함께 만들려고 하신 나라는, 율법이 지켜지는 곳, 곧 천국이었습니다.","25장의 안식년에는 7년에 한 번 땅을 쉬게 하고, 그해의 소산은 종과 나그네, 고아와 과부 같은 사회적 약자들의 몫입니다.","여인들은 허리를 깊이 숙여, 밭에 남은 이삭을 줍고 있습니다.","50년마다 오는 희년에는 자유를 선포하고, 땅을 원래 주인에게 돌려줍니다."],"audio":"audio/8f82eadd376f.mp3","times":[0.3,8.142,18.96,25.026],"dur":31.95},{"act":3,"id":"numbers-manna","img":"img/numbers-manna.webp","size":[1600,1170],"title":"광야의 만나","artist":"니콜라 푸생","year":"1637–1639","museum":"","credit":"Nicolas Poussin, The Israelites Gathering Manna in the Desert","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:La_Manne_-_Nicolas_Poussin_-_Mus%C3%A9e_du_Louvre_Peintures_INV_7275.jpg","verse":"민수기 11:8","lecture":"numbers","lectureTitle":"민수기","youtube":"DWSoUZ7lZQA","text":["율법을 받았으니 이제 살아 볼 차례이고, 민수기는 그래서 광야 훈련기, 선민 훈련기입니다.","200만에서 300만의 사람에 가축까지, 천만에 가까운 무리가 움직이니 먹고 마시는 문제부터 터집니다.","만나도 처음에는 꿀맛이라더니, 좀 지나자 박한 식물이라고 싫어합니다.","그림 속 사람들은 땅에 엎드려 만나를 줍고, 가운데의 모세는 하늘을 가리킵니다."],"audio":"audio/d4f489d47216.mp3","times":[0.3,8.766,17.472,23.97],"dur":31.158},{"act":3,"id":"numbers-pamplona","img":"img/numbers-pamplona.webp","size":[1113,1600],"title":"포도 정탐꾼","artist":"작자 미상","year":"1200년경","museum":"","credit":"Pamplona Bible (c. 1200), The Spies Carrying the Grapes of Canaan","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Iru%C3%B1eko_Biblia_-_Augsburg_-_Pid_6993141_66v.jpg","verse":"민수기 13:23","lecture":"numbers","lectureTitle":"민수기","youtube":"DWSoUZ7lZQA","text":["가나안 땅을 정탐하러 열두 사람이 갑니다.","두 사람이 장대에 꿰어 멘 커다란 포도송이를 지고 돌아옵니다.","그러나 여호수아와 갈렙만 이길 수 있다고 하고, 나머지는 겁을 먹어 우리는 다 죽었다고 하자, 백성들도 휩쓸려 불평합니다.","이 불평과 불신 때문에, 광야 훈련은 40년으로 길어졌습니다."],"audio":"audio/0849fb057454.mp3","times":[0.3,4.902,10.56,20.97],"dur":27.054},{"act":3,"id":"numbers-tintoretto","img":"img/numbers-tintoretto.webp","size":[1600,1067],"title":"반석을 치는 모세","artist":"야코포 틴토레토","year":"1563","museum":"","credit":"Jacopo Tintoretto, Moses Striking the Rock","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:1563_Tintoretto_Moses_Striking_the_Rock_anagoria.JPG","verse":"민수기 20:11","lecture":"numbers","lectureTitle":"민수기","youtube":"DWSoUZ7lZQA","text":["20장, 가데스에서 미리암이 죽고, 물이 없자 백성들은 또 원망합니다.","하나님은 바위에게 명령하라고 하셨는데, 화가 치민 모세는 바위를 두 번 쳤습니다.","그림 속 붉은 옷의 모세가 지팡이를 댄 바위에서 물줄기가 쏟아지고, 사람들은 그릇을 내밉니다.","그 일로 모세는 가나안에 들어가지 못하게 되지만, 그 뒤로도 자기는 들어가지 못할 땅으로 백성을 이끌고 갑니다."],"audio":"audio/482d2af5b67a.mp3","times":[0.3,7.614,15.024,23.37],"dur":32.55},{"act":3,"id":"numbers-serpent","img":"img/numbers-serpent.webp","size":[1600,1037],"title":"놋 뱀과 모세","artist":"안토니 반다이크 공방","year":"1618–1699","museum":"","credit":"Workshop of Anthony van Dyck, Moses and the Brazen Serpent","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Anthony_van_Dyck_studio_-_Moses_and_the_Brazen_Serpent_1791N08712_5LFQV.jpg","verse":"민수기 21:9","lecture":"numbers","lectureTitle":"민수기","youtube":"DWSoUZ7lZQA","text":["에돔 왕이 왕의 대로를 내주지 않자, 백성들은 또 원망하다가 불뱀에 물려 죽습니다.","모세가 기도하자, 놋뱀을 만들어 장대에 높이 매달아라, 보는 자는 산다는 말씀이 내립니다.","사람들은 뱀에 감긴 채, 장대 위의 놋뱀을 향해 손을 뻗습니다.","뱀이 중요한 것이 아니라, 보라고 한 것을 보는 것이 중요합니다."],"audio":"audio/542283f14f9d.mp3","times":[0.3,7.998,16.176,22.674],"dur":28.398},{"act":3,"id":"deuteronomy-tabernacle","img":"img/deuteronomy-tabernacle.webp","size":[1600,1362],"title":"모세와 여호수아","artist":"제임스 티소","year":"1896–1902년경","museum":"","credit":"James Tissot, Moses and Joshua in the Tabernacle","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Tissot_Moses_and_Joshua_in_the_Tabernacle.jpg","verse":"신명기 1장","lecture":"deuteronomy","lectureTitle":"신명기","youtube":"0_grTZ-3RZY","text":["이제 가나안에 들어가기 직전입니다.","신명기는 모세의 고별 설교, 율법을 되풀이해 설명하는 책입니다.","출애굽을 직접 겪은 세대는 모두 죽었기에, 모세는 젊은 세대에게 언약의 내용을 다시 간곡히 부탁합니다.","그림 속 모세와 여호수아는 언약궤 앞에 나란히 무릎을 꿇었습니다."],"audio":"audio/bad7e4d15dd3.mp3","times":[0.3,4.278,10.824,20.154],"dur":25.974},{"act":3,"id":"deuteronomy-tefillin","img":"img/deuteronomy-tefillin.webp","size":[1279,1600],"title":"아침 기도","artist":"얀키엘 크루히에르","year":"1897","museum":"","credit":"Jankiel Kruhier, Morning Prayer (1897)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Jankie%C4%BA_Kruhier_1897_Morning_Prayer.jpg","verse":"신명기 6:4","lecture":"deuteronomy","lectureTitle":"신명기","youtube":"0_grTZ-3RZY","text":["쉐마 이스라엘, 들으라 이스라엘아.","마음을 다하고 뜻을 다하고 힘을 다하여, 네 하나님 여호와를 사랑하라.","지금도 이스라엘 사람들은 이 말씀을 지키려고, 경문갑은 미간에 붙여 표로 삼고 테필린은 손목에 매어 기호로 삼습니다.","기도대에 기대어 선 노인도, 이마와 팔에 경문을 묶었습니다."],"audio":"audio/564cd1fccafc.mp3","times":[0.3,4.494,10.992,20.97],"dur":26.646},{"act":3,"id":"deuteronomy-cassatt","img":"img/deuteronomy-cassatt.webp","size":[1600,1099],"title":"엄마와 아이","artist":"메리 커샛","year":"1880","museum":"","credit":"Mary Cassatt, Mother and Child (The Goodnight Hug)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Mary_Cassatt_-_Mother_and_Child_(The_Goodnight_Hug).jpg","verse":"신명기 31:16","lecture":"deuteronomy","lectureTitle":"신명기","youtube":"0_grTZ-3RZY","text":["31장 16절에서 하나님은 이미, 이스라엘 백성이 배신할 것을 아십니다.","그런데도 다 아시면서, 여전히 기대를 하십니다.","그림 속 엄마가 아이를 꼭 끌어안듯, 당장 고쳐지지 않을 것을 알면서도 또 기대하는 것은 사랑하기 때문입니다.","이제 그 백성이 약속의 땅 가나안으로 들어갑니다."],"audio":"audio/e1e4da192007.mp3","times":[0.3,7.278,12.264,21.786],"dur":26.55},{"act":4,"id":"joshua-ark","img":"img/joshua-ark.webp","size":[1600,1239],"title":"요단을 건너는 언약궤","artist":"제임스 티소","year":"1896–1902년경","museum":"","credit":"James Tissot, The Ark Passes Over the Jordan","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:James_Jacques_Joseph_Tissot_-_The_Ark_Passes_Over_the_Jordan_-_Google_Art_Project.jpg","verse":"여호수아 3장","lecture":"joshua","lectureTitle":"여호수아","youtube":"1aDzUavtdHw","text":["여호수아 1장 1절은 모세가 죽은 후에, 라는 말로 시작합니다.","한 사람이 한 시대를 닫고, 이제 여호수아가 지도자로 서서 백성과 함께 요단강을 건넙니다.","이번에는 믿음으로 발을 먼저 담급니다.","제사장들은 높이 솟은 물결 곁으로, 언약궤를 메고 강바닥을 걸어갑니다."],"audio":"audio/e9e65bb82374.mp3","times":[0.3,6.438,14.712,19.098],"dur":25.95},{"act":4,"id":"joshua-rosselli","img":"img/joshua-rosselli.webp","size":[1600,1391],"title":"라합과 정탐꾼","artist":"마테오 로셀리","year":"1630년경","museum":"","credit":"Matteo Rosselli (attributed), Rahab and the Spies","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:N%C3%AEmes,Beaux_Arts020.jpg","verse":"여호수아 2:11","lecture":"joshua","lectureTitle":"여호수아","youtube":"1aDzUavtdHw","text":["여호수아는 모세 때 겪은 일을 살려, 정탐꾼을 딱 두 명 보냅니다.","두 사람이 들어간 기생 라합의 집에서, 라합은 그들을 숨겨 주고 그 집안이 구원을 받습니다.","너희의 하나님 여호와는 위로는 하늘에서도, 아래로는 땅에서도 하나님이시니라, 2장 11절의 고백입니다.","그림 속 라합은 손을 들어 가리키고, 정탐꾼은 서둘러 발걸음을 옮깁니다."],"audio":"audio/bbc70c32588a.mp3","times":[0.3,6.678,14.616,23.802],"dur":30.462},{"act":4,"id":"joshua-trumpets","img":"img/joshua-trumpets.webp","size":[1600,948],"title":"여리고의 일곱 나팔","artist":"제임스 티소","year":"1904","museum":"","credit":"James Tissot, The Seven Trumpets of Jericho (photo: Phillip Medhurst)","license":"CC BY-SA 4.0","page":"https://commons.wikimedia.org/wiki/File:Les_trompettes_de_J%C3%A9richo_(Joshua_6_13)_%E2%80%A2_invenit_James_Tissot_%E2%80%A2_pinxit_James_Tissot_%E2%80%A2_excudit_Maurice_de_Brunoff_apud_Philip_de_Vere_%E2%80%A2_praesentat_Phillip_Medhurst.jpg","verse":"여호수아 6장","lecture":"joshua","lectureTitle":"여호수아","youtube":"1aDzUavtdHw","text":["라합은 두 정탐꾼 가운데 살몬과 결혼하는데, 예수님이 바로 이 살몬의 후손입니다.","가나안 정복 전쟁은 중부, 남부, 북부의 세 번에 걸쳐 치러집니다.","6년에서 7년 동안 싸우면서 쓰러진 가나안 왕이 31명입니다.","나팔을 부는 제사장들이 언약궤를 메고 성벽 앞을 지나갑니다."],"audio":"audio/0be36772bc33.mp3","times":[0.3,8.118,15.048,21.114],"dur":26.862},{"act":4,"id":"joshua-martin","img":"img/joshua-martin.webp","size":[1600,1207],"title":"태양을 멈춘 여호수아","artist":"존 마틴","year":"1840년경","museum":"","credit":"John Martin, Joshua Commanding the Sun to Stand Still upon Gibeon","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:John_Martin_-_Joshua_Commanding_the_Sun_to_Stand_Still_-_Google_Art_Project.jpg","verse":"여호수아 10:12","lecture":"joshua","lectureTitle":"여호수아","youtube":"1aDzUavtdHw","text":["가나안 사람들을 전멸시키라는 하나님은, 얼핏 보면 잔인한 하나님처럼 보입니다.","그런데 레위기 20장에서 반드시 죽여야 한다는 죄들이, 이미 가나안 땅에서 하던 일들이었습니다.","하나님은 먼저 쫓아내라고 하시고, 그래도 나가지 않으면 죄악의 씨를 말리라고 하십니다.","하늘은 먹구름으로 덮였고, 구름 사이로 쏟아진 빛이 언덕 위 성을 비춥니다."],"audio":"audio/2da3b2ae4731.mp3","times":[0.3,7.446,15.624,23.106],"dur":30.006},{"act":4,"id":"joshua-shechem","img":"img/joshua-shechem.webp","size":[1600,1053],"title":"세겜 나블루스","artist":"데이비드 로버츠","year":"1839","museum":"","credit":"David Roberts, Nablus, Ancient Shechem","license":"CC0","page":"https://commons.wikimedia.org/wiki/File:David_Roberts_-_Nablus_Ancient_Shechem_-_1927.139_-_Cleveland_Museum_of_Art.tif","verse":"여호수아 24장","lecture":"joshua","lectureTitle":"여호수아","youtube":"1aDzUavtdHw","text":["여호수아는 죽기 전에 장로와 두령들을 모아 놓고, 다 하나님께서 하신 것이라고 말합니다.","너희가 섬길 신을 택하라, 나와 내 집은 여호와를 섬기겠노라, 이것이 24장의 핵심입니다.","그러나 여호와께서 하신 일을 아는 세대가 지나자, 그 후손들은 여호와를 섬기지 않았습니다.","그림 속 산자락의 마을은 고요하지만, 역사는 이제 사사기라는 종교 암흑기를 맞습니다."],"audio":"audio/cc1c5fbc3b60.mp3","times":[0.3,8.094,16.728,24.426],"dur":31.974},{"act":4,"id":"judges-deborah","img":"img/judges-deborah.webp","size":[1025,1600],"title":"종려나무 아래 드보라","artist":"제임스 티소","year":"1904","museum":"","credit":"James Tissot, Deborah beneath the Palm Tree (photo: Phillip Medhurst)","license":"CC BY-SA 4.0","page":"https://commons.wikimedia.org/wiki/File:D%C3%A9bora_sous_son_palmier_(Judges_4_4)_%E2%80%A2_invenit_James_Tissot_%E2%80%A2_pinxit_James_Tissot_%E2%80%A2_excudit_Maurice_de_Brunoff_apud_Philip_de_Vere_%E2%80%A2_praesentat_Phillip_Medhurst.jpg","verse":"사사기 4장","lecture":"judges","lectureTitle":"사사기","youtube":"Zh5iDNu3wbI","text":["사사는 히브리어로 쇼페팀, 재판하다는 뜻의 싸파트에서 온 말로, 곧 재판관들입니다.","사사기는 하나님이 직접 다스리시는 신정통치 시대의 이야기지만, 땅을 나눠 가진 뒤 힘은 흩어졌고 여호수아는 후계자를 세우지 못했습니다.","종려나무 곁에서 손을 든 여인이 여선지자 드보라이고, 드보라는 철병거 900승을 부숴 버립니다."],"audio":"audio/bbf7f35c2579.mp3","times":[0.3,8.334,19.536],"dur":27.972},{"act":4,"id":"judges-gideon","img":"img/judges-gideon.webp","size":[1600,1039],"title":"기드온의 삼백 용사","artist":"제임스 티소","year":"1904","museum":"","credit":"James Tissot, Gideon Chooses the Three Hundred (photo: Phillip Medhurst)","license":"CC BY-SA 4.0","page":"https://commons.wikimedia.org/wiki/File:G%C3%A9d%C3%A9on_choisit_les_trois_cents_(Judges_7_6)_%E2%80%A2_invenit_James_Tissot_%E2%80%A2_pinxit_James_Tissot_%E2%80%A2_excudit_Maurice_de_Brunoff_apud_Philip_de_Vere_%E2%80%A2_praesentat_Phillip_Medhurst.jpg","verse":"사사기 7장","lecture":"judges","lectureTitle":"사사기","youtube":"Zh5iDNu3wbI","text":["그 땅 거민을 쫓아내지 못한 이스라엘은 마침내 그들과 섞여, 바알과 아스다롯을 섬깁니다.","사사를 세워 구원해 놓으면 또 악을 행하고, 또 구원하면 또 악을 행하는 무한 반복입니다.","기드온은 바알의 제단을 부수고, 3만 2천 명에서 1만 명, 그리고 300명으로 군사를 줄입니다.","물가에 엎드린 사람들 사이로, 기드온이 칼을 차고 서 있습니다."],"audio":"audio/507361951dd9.mp3","times":[0.3,8.43,16.536,25.338],"dur":31.35},{"act":4,"id":"judges-samson","img":"img/judges-samson.webp","size":[1303,1600],"title":"삼손과 장인","artist":"렘브란트 판레인","year":"","museum":"","credit":"Rembrandt, Samson Threatening His Father-in-Law","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Rembrandt_-_Samson_threatened_his_father-in-law_-_Google_Art_Project.jpg","verse":"사사기 15장","lecture":"judges","lectureTitle":"사사기","youtube":"Zh5iDNu3wbI","text":["아비멜렉은 이복형제 70명을 죽이고, 입다는 제일 먼저 맞이하는 사람을 번제로 드리겠다고 서원합니다.","삼손은 나실인으로 태어났지만, 전혀 구별되게 살지 않은 제멋대로의 인생입니다.","그림 속 삼손은 주먹을 쥐고 소리치고, 창문 너머 장인은 몸을 사린 채 내다봅니다.","사사들이 이러했으니, 보통 백성들의 삶은 어땠을까요?"],"audio":"audio/a3369810ee4d.mp3","times":[0.3,9.318,16.632,24.162],"dur":29.55},{"act":4,"id":"judges-idols","img":"img/judges-idols.webp","size":[1600,1083],"title":"우상을 가져오다","artist":"제임스 티소","year":"1904","museum":"","credit":"James Tissot, The Idols Are Brought Out (photo: Phillip Medhurst)","license":"CC BY-SA 4.0","page":"https://commons.wikimedia.org/wiki/File:219.3_402_On_apporte_les_idoles_(Judges_18_18)_%E2%80%A2_invenit_James_Tissot_%E2%80%A2_pinxit_Michel_Simonidy_%E2%80%A2_excudit_Maurice_de_Brunoff_apud_Philip_de_Vere_%E2%80%A2_praesentat_Phillip_Medhurst.jpg","verse":"사사기 18장","lecture":"judges","lectureTitle":"사사기","youtube":"Zh5iDNu3wbI","text":["에브라임 산지의 미가는 어머니의 돈으로 우상을 만들고, 그것을 여호와께 바친다며 집에 신당을 차립니다.","단 지파 사람들이 그 우상을 품에 안고 나오니, 하나님의 백성이 우상 신당이 탐이 나서 빼앗은 것입니다.","그때에 이스라엘에 왕이 없으므로 사람이 각각 그 소견에 옳은 대로 행하였더라, 21장 25절의 결론입니다.","왕이 없었던 것이 아니라, 아무도 하나님을 왕으로 인정하지 않았던 것입니다."],"audio":"audio/a1fe538987f5.mp3","times":[0.3,9.438,18.072,27.378],"dur":33.966},{"act":4,"id":"ruth-calderon","img":"img/ruth-calderon.webp","size":[1600,1225],"title":"룻과 나오미","artist":"필립 허모지니스 콜더런","year":"","museum":"","credit":"Philip Hermogenes Calderon, Ruth and Naomi","license":"CC0","page":"https://commons.wikimedia.org/wiki/File:Philip_Hermogenes_Calderon_-_Ruth_and_Naomi_-_B2010.27.8_-_Yale_Center_for_British_Art.jpg","verse":"룻기 1장","lecture":"ruth","lectureTitle":"룻기","youtube":"fKiXPLqHt2I","text":["룻기는 사사기와 같은 시대, 그 땅에 흉년이 들었을 때 일어난 이야기입니다.","모압 지방으로 떠난 나오미의 집안은, 10년쯤 지나는 사이 남편도 두 아들도 잃습니다.","나오미가 재혼해서 잘 살라고 하자 오르바는 떠나고, 룻은 나오미를 따라 돌아옵니다.","그림 속 두 여인은 서로를 꼭 끌어안고 있습니다."],"audio":"audio/a189875b791a.mp3","times":[0.3,7.278,14.856,22.194],"dur":26.958},{"act":4,"id":"ruth-schnorr","img":"img/ruth-schnorr.webp","size":[1600,1351],"title":"보아스의 밭에 간 룻","artist":"율리우스 슈노어 폰 카롤스펠트","year":"1828","museum":"","credit":"Julius Schnorr von Carolsfeld, Ruth in Boaz's Field","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Julius_Schnorr_von_Carolsfeld-_Ruth_im_Feld_des_Boaz.jpg","verse":"룻기 2:3","lecture":"ruth","lectureTitle":"룻기","youtube":"fKiXPLqHt2I","text":["두 사람이 베들레헴에 온 때는, 마침 보리 추수를 시작할 무렵이었습니다.","2장 3절, 룻이 우연히 엘리멜렉의 친족 보아스의 밭에 이르렀습니다.","보아스는 다른 밭에 가지 말고 여기서 주우라며, 시어머니에게 잘한 룻을 하나님이 갚아 주시기를 빕니다.","붉은 옷의 보아스가, 이삭 단을 든 룻을 바라봅니다."],"audio":"audio/872e922f0cc4.mp3","times":[0.3,6.726,13.632,22.362],"dur":27.63},{"act":4,"id":"ruth-poussin","img":"img/ruth-poussin.webp","size":[1600,1161],"title":"여름 · 룻과 보아스","artist":"니콜라 푸생","year":"","museum":"","credit":"Nicolas Poussin, Summer (Ruth and Boaz)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Nicolas_Poussin_-_L%27%C3%89t%C3%A9_ou_Ruth_et_Booz.jpg","verse":"룻기 2장","lecture":"ruth","lectureTitle":"룻기","youtube":"fKiXPLqHt2I","text":["레위기 19장 9절은 밭 모퉁이까지 다 거두지 말고, 떨어진 이삭도 줍지 말라고 합니다.","가난한 사람이 자기 손으로 거두어 부끄럽지 않게 하는 것, 이것이 율법입니다.","보아스는 종들에게 이삭을 흘려 주라고까지 하는, 율법이 요구하는 것 이상을 하는 사람입니다.","누렇게 익은 밭 한가운데 선 그림 속 보아스는, 어두운 사사 시대에 밝게 빛나는 한 사람입니다."],"audio":"audio/1e434f8cc964.mp3","times":[0.3,8.238,15.336,23.226],"dur":31.254},{"act":4,"id":"ruth-ferri","img":"img/ruth-ferri.webp","size":[1600,1439],"title":"룻의 결혼","artist":"치로 페리","year":"","museum":"","credit":"Ciro Ferri, The Marriage of Ruth (photo: Sailko)","license":"CC BY-SA 4.0","page":"https://commons.wikimedia.org/wiki/File:Ciro_ferri,_nozze_di_ruth_01.jpg","verse":"룻기 4장","lecture":"ruth","lectureTitle":"룻기","youtube":"fKiXPLqHt2I","text":["가까운 친척이 기업 무르기를 마다하며 신발을 벗어 주자, 보아스가 룻과 결혼합니다.","보아스가 룻에게 손을 내밀고 있습니다.","두 사람의 아들 오벳은 다윗의 할아버지이니, 라합과 결혼한 살몬에서 다윗까지 족보가 이어집니다.","사사기라는 어둡고 긴 터널 한가운데, 빛줄기 같은 보리밭의 사랑 이야기였습니다."],"audio":"audio/ca7dcf699df8.mp3","times":[0.3,7.974,12.168,20.514],"dur":27.678},{"act":5,"id":"samuel1-eeckhout","img":"img/samuel1-eeckhout.webp","size":[1600,1293],"title":"사무엘과 엘리","artist":"헤르브란트 판덴에이크하우트","year":"1660–1663","museum":"","credit":"Gerbrand van den Eeckhout, The Infant Samuel Brought by Hannah to Eli","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Eeckhout,_Gerbrand_van_den_-_The_Infant_Samuel_brought_by_Hannah_to_Eli_-_Ashmolean_Museum.jpg","verse":"사무엘상 1:11","lecture":"samuel1","lectureTitle":"사무엘상","youtube":"_UXZXKzLh58","text":["사무엘상은 이스라엘에 아직 왕이 없던 사사 시대에서 시작하고, 사무엘도 그 사사 가운데 한 사람입니다.","아이를 낳지 못하던 한나는, 1장 11절에서 아이의 머리에 삭도를 대지 않겠다는 나실인 서원을 합니다.","그렇게 태어난 사무엘을, 한나는 약속대로 젖을 떼자 바로 성전에 드립니다.","한나는 무릎을 꿇고, 하얀 옷을 입은 어린 사무엘을 늙은 제사장 엘리 앞에 내어 놓습니다."],"audio":"audio/af2512f51e0c.mp3","times":[0.3,9.486,18.312,25.458],"dur":33.27},{"act":5,"id":"samuel1-field","img":"img/samuel1-field.webp","size":[1600,1282],"title":"언약궤","artist":"이래스터스 샐리스버리 필드","year":"1865–1880년경","museum":"","credit":"Erastus Salisbury Field, Ark of the Covenant","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Ark_of_the_Covenant_(Erastus_Salisbury_Field).jpg","verse":"사무엘상 6장","lecture":"samuel1","lectureTitle":"사무엘상","youtube":"_UXZXKzLh58","text":["2장 12절은 엘리의 아들들을 여호와를 알지 아니하는 불량자라고 하는데, 엘리는 그 아들들을 금하지 아니하였습니다.","그 죄 때문에 법궤를 블레셋에게 빼앗기고, 두 아들은 한 날에 죽고, 엘리도 그 소식을 듣다가 넘어져 죽습니다.","법궤를 가져간 블레셋 땅에 재앙이 내리자, 블레셋은 젖먹이 새끼를 둔 암소에게 수레를 끌게 해서 법궤를 돌려보냅니다.","그림 속 벧세메스 사람들은 밀을 베다 말고 고개를 들어, 언덕 쪽에서 오는 수레를 바라봅니다."],"audio":"audio/21450034adc7.mp3","times":[0.3,9.726,19.224,29.298],"dur":37.158},{"act":5,"id":"samuel1-moeyaert","img":"img/samuel1-moeyaert.webp","size":[1600,1033],"title":"사무엘과 사울","artist":"클라스 무예르트","year":"1618–1655","museum":"","credit":"Claes Moeyaert, Samuel and Saul","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Claes_Moeyaert_-_Samuel_and_Saul.jpg","verse":"사무엘상 15:22","lecture":"samuel1","lectureTitle":"사무엘상","youtube":"_UXZXKzLh58","text":["사무엘이 늙자 장로들이 찾아와, 열방과 같이 우리에게 왕을 세워 주소서 하고 말합니다.","하나님께 권좌에서 물러나시라는 말이었지만 하나님은 그냥 물러나 주시고, 그렇게 세운 이스라엘의 초대 왕이 사울입니다.","아말렉을 진멸하라는 명령을 듣고도 소와 양을 남겨 온 사울에게, 사무엘은 순종이 제사보다 낫고 듣는 것이 숫양의 기름보다 낫다고 말합니다.","그림 왼쪽에는 끌고 온 양과 소와 은그릇이 놓여 있고, 오른쪽에는 갑옷 입은 사울이 사무엘 앞에 서 있습니다."],"audio":"audio/7cd7127ff6ec.mp3","times":[0.3,8.094,18.12,29.538],"dur":38.718},{"act":5,"id":"samuel1-anoint","img":"img/samuel1-anoint.webp","size":[1600,1431],"title":"다윗의 기름 부음","artist":"얀 빅토르스","year":"","museum":"","credit":"Jan Victors, Samuel Anointing David (photo: Dguendel)","license":"CC BY 3.0","page":"https://commons.wikimedia.org/wiki/File:Herzog_Anton_Ulrich-Museum,_Jan_Victors,_David_wird_von_Samuel_gesalbt.jpg","verse":"사무엘상 16:13","lecture":"samuel1","lectureTitle":"사무엘상","youtube":"_UXZXKzLh58","text":["15장 35절, 하나님은 사울을 왕 삼으신 것을 후회하십니다.","사울이 저를 가만두겠습니까 하고 사무엘이 묻자, 제사 드리러 왔다고 하라는 답이 옵니다.","그렇게 사무엘이 다윗에게 기름을 붓는데, 기름을 붓는 것은 왕이나 주의 종을 세울 때 구별한다는 뜻입니다.","다윗은 무릎을 꿇었고, 흰옷의 사무엘이 그 머리에 기름을 부으며, 둘러선 사람들이 지켜봅니다."],"audio":"audio/a1bba4edd92d.mp3","times":[0.3,6.726,14.64,23.826],"dur":32.238},{"act":5,"id":"samuel1-harp","img":"img/samuel1-harp.webp","size":[1600,1263],"title":"사울과 다윗","artist":"렘브란트 판레인","year":"1651–1658년경","museum":"","credit":"Rembrandt, Saul and David","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Rembrandt_Saul_and_David.jpg","verse":"사무엘상 16:14","lecture":"samuel1","lectureTitle":"사무엘상","youtube":"_UXZXKzLh58","text":["다윗은 여호와의 신에게 크게 감동되지만, 사울에게서는 여호와의 신이 떠나고 악신이 번뇌케 합니다.","16장 14절, 그 악신을 부리시는 분도 하나님이십니다.","그림 속 사울은 어둠 속에서 창을 쥐고 앉아 있고, 그 앞에서 젊은 다윗이 하프를 탑니다."],"audio":"audio/8dd64110b699.mp3","times":[0.3,9.102,15.024],"dur":22.908},{"act":5,"id":"samuel1-spear","img":"img/samuel1-spear.webp","size":[1600,1064],"title":"창 던지는 사울","artist":"구에르치노","year":"","museum":"","credit":"Guercino, Saul Attacking David (photo: Francesco Bini)","license":"CC BY-SA 4.0","page":"https://commons.wikimedia.org/wiki/File:Guercino,_saul_cerca_di_colpire_david_con_la_lancia,_01.jpg","verse":"사무엘상 18:7","lecture":"samuel1","lectureTitle":"사무엘상","youtube":"_UXZXKzLh58","text":["17장 골리앗 이야기에서, 양 떼를 지키려고 평소에 물매를 엄청나게 연습한 다윗은 골리앗의 이마를 맞힙니다.","그런데 그 승리 때문에 다윗은 오히려, 자기보다 뛰어난 사람을 못 봐주는 사울의 미움을 받습니다.","여자들이 사울은 천천이요 다윗은 만만이라 노래하자, 사울은 시기심에 완전히 사로잡힙니다.","사울은 창을 높이 치켜들었고, 하프를 든 다윗은 손을 들어 막으며 몸을 피합니다."],"audio":"audio/34237197100b.mp3","times":[0.3,9.75,17.856,25.914],"dur":33.15},{"act":5,"id":"samuel1-cave","img":"img/samuel1-cave.webp","size":[1600,1326],"title":"엔게디 동굴","artist":"빌럼 더포르터","year":"1625–1650","museum":"","credit":"Willem de Poorter, Saul and David in the Cave of En-Gedi","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Willem_de_Poorter_-_Saul_and_David_in_the_cave_of_En-Gedi_-_M.Ob.1888_-_National_Museum_in_Warsaw.jpg","verse":"사무엘상 26:9","lecture":"samuel1","lectureTitle":"사무엘상","youtube":"_UXZXKzLh58","text":["그 길로 다윗은 기브아에서 엔게디를 지나 헤브론까지, 한 10년을 쫓겨 다닙니다.","사울이 삼천 명씩 풀어서 쫓아다녀도, 다윗 눈에는 사울이 늘 보이는데, 사울 눈에는 다윗이 보이지 않습니다.","그래도 다윗에게는 26장 9절의 원칙이 있었습니다, 누구든지 손을 들어 여호와의 기름 부음을 받은 자를 치면 죄가 없겠느냐.","어두운 동굴 속에 한 사람은 서 있고 한 사람은 무릎을 꿇고 있는데, 다윗은 끝내 사울을 죽이지 않습니다."],"audio":"audio/3289f39ebd02.mp3","times":[0.3,7.614,17.184,27.666],"dur":36.438},{"act":5,"id":"samuel1-gilboa","img":"img/samuel1-gilboa.webp","size":[1600,968],"title":"사울의 자살","artist":"피터르 브뤼헐 1세","year":"1562","museum":"","credit":"Pieter Bruegel the Elder, The Suicide of Saul","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Pieter_Bruegel_the_Elder_-_The_Suicide_of_Saul.jpg","verse":"사무엘상 31장","lecture":"samuel1","lectureTitle":"사무엘상","youtube":"_UXZXKzLh58","text":["자꾸 실수하던 사울은 31장 길보아 산에서 블레셋과 싸우다가, 요나단을 비롯한 세 아들을 잃고 활에 맞아 크게 다칩니다.","병기 든 자가 찌르지 못하자, 사울은 자기 칼 위에 엎드러집니다.","그림 속 산골짜기는 끝없는 군대로 뒤덮여 있고, 왼쪽 아래 바위 턱에서 사울이 쓰러집니다."],"audio":"audio/5cca5aefde3d.mp3","times":[0.3,11.094,17.496],"dur":25.572},{"act":5,"id":"samuel2-honthorst","img":"img/samuel2-honthorst.webp","size":[1281,1600],"title":"다윗의 하프","artist":"헤라르트 판혼트호르스트","year":"1622","museum":"","credit":"Gerard van Honthorst, King David Playing the Harp","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Gerard_van_Honthorst_-_King_David_Playing_the_Harp_-_Google_Art_Project.jpg","verse":"사무엘하 2:1","lecture":"samuel2","lectureTitle":"사무엘하","youtube":"K4ce46FhhUo","text":["사울이 죽은 뒤에도 다윗은 가볍게 움직이지 않고, 유다 한 성으로 올라가리이까 하고 하나하나 하나님께 묻습니다.","어디로 가리이까 하고 묻자 헤브론으로 가라 하시니, 다윗은 헤브론에서 유다 지파에게만 왕이 됩니다.","아브넬이 세운 이스보셋과 나뉘어 불안한 2년을 보낸 끝에, 민심은 파도처럼 다윗에게로 밀려갑니다.","하프 줄에 손을 얹은 다윗이 하늘을 올려다봅니다."],"audio":"audio/1e26ec967ac3.mp3","times":[0.3,9.702,18.216,27.234],"dur":31.95},{"act":5,"id":"samuel2-umbria","img":"img/samuel2-umbria.webp","size":[1600,730],"title":"언약궤 운반","artist":"움브리아 화파","year":"","museum":"","credit":"Umbrian school (16th century), The Transfer of the Ark of the Covenant","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:%C3%9Cberf%C3%BChrung_der_Bundeslade_(Umbrien_16_Jh).jpg","verse":"사무엘하 6장","lecture":"samuel2","lectureTitle":"사무엘하","youtube":"K4ce46FhhUo","text":["5장에서 다윗은 여부스 족속이 차지하고 있던 예루살렘을 공략하고, 6장에서 법궤를 모셔 옵니다.","처음에는 법궤를 수레에 싣고 오다가 웃사가 죽는데, 법궤는 제사장들이 어깨에 메야 했습니다.","다시 가져올 때는 제대로 알아보고, 제사장들이 어깨에 메고 오게 했습니다.","그림 속 사람들은 금빛 법궤를 채에 꿰어 어깨에 메고, 하프와 악기를 울리며 걸어갑니다."],"audio":"audio/afdf34c3fce9.mp3","times":[0.3,8.79,17.016,23.73],"dur":31.638},{"act":5,"id":"samuel2-nathan","img":"img/samuel2-nathan.webp","size":[913,1600],"title":"다윗을 꾸짖는 나단","artist":"제임스 티소","year":"1904","museum":"","credit":"James Tissot (design) and Louis de Parys, Nathan Reproaches David (photo: Phillip Medhurst)","license":"CC BY-SA 4.0","page":"https://commons.wikimedia.org/wiki/File:Nathan_fait_des_reproches_%C3%A0_David_(2_Samuel_11_9)_%E2%80%A2_invenit_James_Tissot_%E2%80%A2_pinxit_Louis_de_Parys_%E2%80%A2_excudit_Maurice_de_Brunoff_apud_Philip_de_Vere_%E2%80%A2_praesentat_Phillip_Medhurst.jpg","verse":"사무엘하 12장","lecture":"samuel2","lectureTitle":"사무엘하","youtube":"K4ce46FhhUo","text":["11장은 그 유명한 밧세바 사건으로, 음욕을 품은 다윗은 가장 충직한 부하 우리야를 죽이고 결국 그 아내를 빼앗아 버렸습니다.","12장에서 나단이 찾아와 죄를 지적하자, 다윗은 바로 엎드립니다.","나단 앞에서 다윗은 얼굴을 두 손에 묻고 있습니다.","그 후에 이 일이 있으니라, 그 뒤로 암논과 압살롬의 일이 이어지고, 압살롬의 반역으로 다윗은 큰 고생을 겪습니다."],"audio":"audio/e05b39e5ec7b.mp3","times":[0.3,11.286,18.024,22.962],"dur":32.406},{"act":5,"id":"kings1-poussin","img":"img/kings1-poussin.webp","size":[1600,1072],"title":"솔로몬의 재판","artist":"니콜라 푸생","year":"1649","museum":"","credit":"Nicolas Poussin, The Judgement of Solomon","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Le_Jugement_de_Salomon_-_1649_-_Nicolas_Poussin_-_Louvre_-_INV_7277_;_MR_2316_(2).jpg","verse":"열왕기상 3장","lecture":"kings1","lectureTitle":"열왕기상","youtube":"IkMDF2MEFi4","text":["다윗이 늙자 아도니야가 왕이 되려고 나서지만, 나단과 밧세바의 말을 들은 다윗은 솔로몬을 왕으로 세웁니다.","하나님이 무엇을 줄까 물으시자, 솔로몬은 백성을 재판할 듣는 마음을 구합니다.","칼로 잘라 주라는 말에 진짜 엄마가 그냥 저 여자에게 주라고 한 두 창녀의 재판으로, 솔로몬의 왕권이 탄탄해집니다.","높은 자리에 앉은 솔로몬 앞에서, 한 여인은 두 팔을 벌리고 다른 여인은 죽은 아이를 안고 있습니다."],"audio":"audio/24a3ae97a998.mp3","times":[0.3,9.606,16.896,27.042],"dur":35.502},{"act":5,"id":"kings1-dedication","img":"img/kings1-dedication.webp","size":[1172,1600],"title":"솔로몬의 성전 봉헌","artist":"제임스 티소","year":"1904","museum":"","credit":"James Tissot (design) and Michel Simonidy, Solomon Dedicates the Temple (photo: Phillip Medhurst)","license":"CC BY-SA 4.0","page":"https://commons.wikimedia.org/wiki/File:La_d%C3%A9dicace_par_Salomon_du_temple_(1_Kings_10_2)_%E2%80%A2_invenit_James_Tissot_%E2%80%A2_pinxit_Michel_Simonidy_%E2%80%A2_excudit_Maurice_de_Brunoff_apud_Philip_de_Vere_%E2%80%A2_praesentat_Phillip_Medhurst.jpg","verse":"열왕기상 8장","lecture":"kings1","lectureTitle":"열왕기상","youtube":"IkMDF2MEFi4","text":["솔로몬은 성전을 7년, 자기 궁을 13년 동안 짓고, 그 강제노역에 백성들이 시달립니다.","8장에서 솔로몬이 드린 기도는 레위기 26장에 근거합니다.","패할 때, 기근과 재앙 때, 포로로 끌려갔을 때, 이 성전을 향해 기도하거든 들어 달라는 것입니다.","그림 속 솔로몬은 성전 계단 위에서 두 팔을 높이 들고, 그 아래로 백성들이 빽빽이 모여 있습니다."],"audio":"audio/f671735376ed.mp3","times":[0.3,8.838,14.688,23.61],"dur":31.926},{"act":5,"id":"kings1-francken","img":"img/kings1-francken.webp","size":[1600,1135],"title":"솔로몬의 우상숭배","artist":"프란스 프랑컨 2세","year":"1622","museum":"","credit":"Frans Francken the Younger, The Idolatry of Solomon","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Frans_Francken_the_Younger_-_The_Idolatry_of_Solomon_-_71.PB.42_-_J._Paul_Getty_Museum.jpg","verse":"열왕기상 11장","lecture":"kings1","lectureTitle":"열왕기상","youtube":"IkMDF2MEFi4","text":["솔로몬은 40년을 다스렸는데, 20년은 건축하고 나머지 20년은 여인들에게 빠져 타락하는 데 보냅니다.","11장에서 솔로몬은 이방 아내들을 위해 이방신의 산당을 세워 줍니다.","예루살렘을 만국 종교 박람회장으로 만들어 버린 것입니다.","늙은 솔로몬은 왕관을 바닥에 벗어 두고, 여인들에게 둘러싸여 신상 앞에 무릎을 꿇습니다."],"audio":"audio/c4330e68279e.mp3","times":[0.3,9.51,16.008,21.594],"dur":29.79},{"act":5,"id":"kings1-fragonard","img":"img/kings1-fragonard.webp","size":[1300,1053],"title":"여로보암의 제사","artist":"장오노레 프라고나르","year":"1752","museum":"","credit":"Jean-Honoré Fragonard, Jeroboam Sacrificing to the Idols","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Jean-Honor%C3%A9_Fragonard_-_Jeroboam_Offering_Sacrifice_for_the_Idol_-_WGA08049.jpg","verse":"열왕기상 13장","lecture":"kings1","lectureTitle":"열왕기상","youtube":"IkMDF2MEFi4","text":["솔로몬이 죽자 르호보암은 멍에를 더 무겁게 하라는 어린 사람들의 말을 듣고, 10지파가 배반해 나라는 둘로 갈라집니다.","북쪽의 여로보암은 백성이 남왕국으로 내려갈까 봐 금송아지를 만들고, 보통 백성을 제사장으로 삼습니다.","벧엘 제단에 하나님의 사람이 나타나 외치자, 저자를 잡으라고 편 여로보암의 손이 그대로 말라 버립니다.","그림 위쪽 높은 단에는 금송아지가 서 있고, 오른쪽에서는 신하들이 손이 굳은 여로보암을 붙들고 있습니다."],"audio":"audio/393b7d7588b9.mp3","times":[0.3,10.182,19.464,28.29],"dur":36.942},{"act":5,"id":"kings1-fetti","img":"img/kings1-fetti.webp","size":[1500,1145],"title":"엘리야의 제사","artist":"도메니코 페티","year":"1621–1622년경","museum":"","credit":"Domenico Fetti, The Sacrifice of Elijah Before the Priests of Baal","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Domenico_Fetti_(Rome_c._1588-Venice_1623)_-_The_Sacrifice_of_Elijah_Before_the_Priests_of_Baal_-_RCIN_405466_-_Royal_Collection.jpg","verse":"열왕기상 18장","lecture":"kings1","lectureTitle":"열왕기상","youtube":"IkMDF2MEFi4","text":["북이스라엘의 아합은 그 이전 모든 왕보다 더 악해서, 이세벨을 아내로 삼고 사마리아에 바알 제단까지 쌓습니다.","그때 '여호와 그가 하나님이다'라는 뜻의 이름을 가진 엘리야가 나타납니다.","갈멜산에서 엘리야가 너희가 어느 때까지 둘 사이에서 머뭇머뭇하려느냐 하고 외치자, 하나님께서 불로 응답하십니다.","흰옷의 엘리야가 무릎을 꿇었고, 제단 위로는 하늘에서 내려온 불길이 타오릅니다."],"audio":"audio/94977d8e18f6.mp3","times":[0.3,9.87,16.104,25.842],"dur":33.174},{"act":5,"id":"kings1-leighton","img":"img/kings1-leighton.webp","size":[1146,1200],"title":"이세벨과 아합","artist":"프레더릭 레이턴","year":"1863","museum":"","credit":"Frederic Leighton, Jezebel and Ahab (Elijah meets them in Naboth's vineyard)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Frederic_Leighton_(1830-1896)_-_Jezebel_and_Ahab_-_SMG.289_-_Scarborough_Art_Gallery.jpg","verse":"열왕기상 21장","lecture":"kings1","lectureTitle":"열왕기상","youtube":"IkMDF2MEFi4","text":["21장 1절에도, 다윗 때 살펴본 그 말씀이 아합에게 나옵니다, 그 후에 이 일이 있으니라.","아합은 나봇의 포도원을 빼앗았다가, 어떤 병사가 쏜 화살이 하필 갑옷 사이를 뚫고 들어오는 바람에 결국 죽습니다.","그림 속 포도원 문간에서, 이세벨과 아합 앞에 엘리야가 막아섭니다.","여기까지가 열왕기상이고, 갈라진 두 나라의 이야기는 이제 열왕기하로 이어집니다."],"audio":"audio/33f763dc48ad.mp3","times":[0.3,8.742,18.432,24.954],"dur":32.382},{"act":6,"id":"kings2-1-angeli","img":"img/kings2-1-angeli.webp","size":[1600,1046],"title":"승천하는 엘리야","artist":"주세페 안젤리","year":"","museum":"","credit":"Giuseppe Angeli, Elijah Taken Up in a Chariot of Fire","license":"CC0","page":"https://commons.wikimedia.org/wiki/File:Giuseppe_Angeli,_Elijah_Taken_Up_in_a_Chariot_of_Fire,_c._1740-1755,_NGA_41685.jpg","verse":"열왕기하 2장","lecture":"kings2-1","lectureTitle":"열왕기하 1~14장","youtube":"tSlqtbJmq20","text":["열왕기하는 아합이 죽은 후에 라는 말로 시작하고, 그 아들 아하시야는 다락 난간에서 떨어지고도 블레셋의 파리 신 바알세붑에게 물으러 사람을 보냅니다.","이제 사명을 마친 엘리야는 승천하고, 엘리야가 받은 영감의 갑절이 엘리사에게 임합니다.","갑절이 임했다는 것은, 시대가 갑절이나 더 악해졌다는 뜻이기도 합니다.","그림 속 엘리야는 불길에 싸인 수레를 타고 오르고, 땅에 무릎 꿇은 엘리사는 두 팔을 하늘로 뻗습니다."],"audio":"audio/51c4005712be.mp3","times":[0.3,12.462,20.28,26.946],"dur":35.334},{"act":6,"id":"kings2-1-naaman","img":"img/kings2-1-naaman.webp","size":[1600,1099],"title":"나아만의 선물","artist":"람베르트 야콥스","year":"1628–1633년경","museum":"","credit":"Lambert Jacobsz, Elisha Refusing Naaman's Gifts","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Lambert_Jacobsz_-_Elisha_Refusing_Naaman%E2%80%99s_Gifts_-_LJ-100_-_Leiden_Collection.jpg","verse":"열왕기하 5장","lecture":"kings2-1","lectureTitle":"열왕기하 1~14장","youtube":"tSlqtbJmq20","text":["엘리야는 여호와 그가 하나님이시다, 엘리사는 나의 하나님은 구원이시다, 라는 뜻입니다.","엘리사는 해로운 물을 달게 고치고, 죽은 아이를 살리고, 물에 빠진 도끼를 떠오르게 하며, 하나님이 구원이심을 보여 줍니다.","5장에서는 아람의 군대장관 나아만의 나병을 낫게 합니다.","화려한 터번을 두른 나아만 앞에서, 붉은 옷의 엘리사가 한 손을 들어 올리고 있습니다."],"audio":"audio/96fa8b3ff730.mp3","times":[0.3,8.406,18.648,24.618],"dur":31.806},{"act":6,"id":"jonah-dughet","img":"img/jonah-dughet.webp","size":[1600,1152],"title":"요나와 큰 물고기","artist":"가스파르 뒤게","year":"1653–1654년경","museum":"","credit":"Gaspard Dughet, Seascape with Jonah and the Whale","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Dughet_-_Seascape_with_Jonah_and_the_Whale_c._1653-4.jpg","verse":"요나 1장","lecture":"jonah","lectureTitle":"선지서 다시 보기 · 요나","youtube":"Ngac_u89NoM","text":["북쪽 여로보암 2세 때 요나 선지자가 활동하니, 이제부터는 선지서와 역사서를 함께 읽습니다.","도무지 듣지 않는 이스라엘을 보시고 하나님은 요나를 니느웨로 보내시지만, 요나는 정반대 쪽 다시스로 가는 배를 탑니다.","풍랑 속에 제비를 뽑자 요나가 걸리고, 바다에 던져진 요나를 큰 물고기가 삼킵니다.","그림 속 바위 위 사람들은 성난 바다를 가리키고, 물결 사이로 큰 물고기가 입을 벌립니다."],"audio":"audio/f90277f70072.mp3","times":[0.3,8.382,18.264,25.866],"dur":34.086},{"act":6,"id":"jonah-persson","img":"img/jonah-persson.webp","size":[1600,1006],"title":"박넝쿨 아래의 요나","artist":"페르 페르손","year":"1819","museum":"스웨덴 국립미술관","credit":"Per Persson, Jonah beneath the Gourd (1819), Nationalmuseum","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Jonah_beneath_the_Gourd_(Per_Persson)_-_Nationalmuseum_-_25977.tif","verse":"요나 4장","lecture":"jonah","lectureTitle":"선지서 다시 보기 · 요나","youtube":"Ngac_u89NoM","text":["뭍에 토해진 요나는 사흘 길 성읍에서 하룻길만 가며 억지로 말씀을 전합니다.","그런데 왕부터 짐승까지 조복을 입고 회개하자, 요나는 차라리 내 생명을 가져가 달라고 성을 냅니다.","하룻밤에 났다가 하룻밤에 망한 박넝쿨을 네가 아꼈거든, 하물며 이 큰 성읍 니느웨를 내가 아끼는 것이 어찌 합당치 아니하냐.","요나는 성 밖 나무 그늘에 앉아, 끝내 무너지지 않은 성을 바라봅니다."],"audio":"audio/8603837d0abf.mp3","times":[0.3,7.542,16.032,26.202],"dur":32.406},{"act":6,"id":"amos-bonifacio","img":"img/amos-bonifacio.webp","size":[1600,749],"title":"부자와 나사로","artist":"보니파치오 데 피타티","year":"","museum":"베네치아 아카데미아 미술관","credit":"Bonifacio de' Pitati, The Rich Man and Lazarus (Il ricco Epulone), Gallerie dell'Accademia, Venice (photo: Didier Descouens)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Accademia_-_Il_ricco_Epulone_by_Bonifacio_De%27_Pitati_cat.291.jpg","verse":"아모스 6장","lecture":"amos","lectureTitle":"아모스","youtube":"ABCmcakaWJ4","text":["니느웨는 되는데 이스라엘은 안 되자, 하나님은 남쪽 드고아의 목자 아모스를 북쪽으로 보내십니다.","다메섹, 가사, 두로, 에돔을 차례로 꾸짖던 말씀은 서막일 뿐, 이스라엘의 서너 가지 죄로 인하여 하는 본론이 9장까지 이어집니다.","은을 받고 의인을 팔았고, 힘 있는 사람들은 상아 궁전을 지었으며, 여자들은 상아 침대에서 늦잠을 자고 대접으로 포도주를 마셨습니다.","그림 속 기둥 사이에서는 차려입은 사람들이 악기를 켜며 즐기고, 오른쪽에서는 지팡이를 짚은 사람이 손을 내밉니다."],"audio":"audio/48bf7b3b988e.mp3","times":[0.3,8.766,20.376,31.698],"dur":41.022},{"act":6,"id":"amos-niagara","img":"img/amos-niagara.webp","size":[1600,743],"title":"나이아가라","artist":"프레더릭 에드윈 처치","year":"1857","museum":"미국 국립미술관","credit":"Frederic Edwin Church, Niagara (1857), National Gallery of Art","license":"CC0","page":"https://commons.wikimedia.org/wiki/File:Frederic_Edwin_Church,_Niagara,_1857,_NGA_166436.jpg","verse":"아모스 5장","lecture":"amos","lectureTitle":"아모스","youtube":"ABCmcakaWJ4","text":["5장에서 하나님은 너희 절기를 미워하며, 번제나 소제를 드려도 받지 아니하리라고 하십니다.","오직 공법을 물같이, 정의를 하수같이 흘릴지로다.","거창한 종교 행사가 아니라, 도덕성과 정직성과 믿음을 회복하는 것을 원하신다는 말씀입니다.","이 폭포처럼 쉬지 않고 흘러야 할 정의였지만, 아모스 시대 사람들은 맞으면서도 하나님께 돌아오지 않았습니다."],"audio":"audio/96a8fe57a5b2.mp3","times":[0.3,8.286,13.8,22.242],"dur":31.278},{"act":6,"id":"hosea-wedding","img":"img/hosea-wedding.webp","size":[1600,1485],"title":"유대인의 결혼식","artist":"요제프 이스라엘스","year":"1903","museum":"레이크스미술관","credit":"Jozef Israëls, A Jewish Wedding (Rijksmuseum)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Joodse_bruiloft_Rijksmuseum_SK-A-2598.jpeg","verse":"호세아 3장","lecture":"hosea","lectureTitle":"호세아","youtube":"xeHixl1YNOc","text":["같은 시대의 호세아는, 바알과 아세라에 미쳐 있던 나라에서 음란한 아내를 취하라는 특별한 명령을 받습니다.","결혼하면 마음을 잡을까 했지만, 아내 고멜은 그새 또 다른 남자를 따라갑니다.","호세아는 비용을 치르고 아내를 찾아오는데, 내 것을 찾아오면서 대가를 지불하는 것, 이것이 구속입니다.","그림 속 신랑은 숄을 신부와 함께 머리에 덮어쓰고, 신부의 손을 잡고 있습니다."],"audio":"audio/61fcca178862.mp3","times":[0.3,9.246,16.776,25.794],"dur":33.054},{"act":6,"id":"hosea-grapes","img":"img/hosea-grapes.webp","size":[1600,1251],"title":"포도 정물","artist":"얀 다비츠존 더헤임","year":"1660","museum":"","credit":"Jan Davidsz. de Heem, Still Life with Grapes","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Jan_Davidsz_de_Heem_-_Still_Life_with_Grapes.jpg","verse":"호세아 9:10","lecture":"hosea","lectureTitle":"호세아","youtube":"xeHixl1YNOc","text":["직접 겪어 본 호세아가 목 놓아 외치는 말은, 힘써 여호와를 알자, 입니다.","옛적에 내가 이스라엘 만나기를, 광야에서 포도를 만남같이 하였거늘, 9장 10절의 고백입니다.","이 탐스러운 포도송이처럼 반가웠던 백성이, 품에 한 번 안아 보기도 전에 바알브올에 가서 우상에게 몸을 드렸습니다.","사랑을 배신하면 남이 되는 것이 아니라 원수가 되고, 결국 기원전 722년, 하나님은 앗수르의 살만에셀을 보내십니다."],"audio":"audio/d537c5f275b0.mp3","times":[0.3,7.494,15.888,25.698],"dur":36.342},{"act":6,"id":"joel-joel","img":"img/joel-joel.webp","size":[1188,1600],"title":"선지자 요엘","artist":"미켈란젤로 부오나로티","year":"1508–1512","museum":"시스티나 예배당","credit":"Michelangelo, The Prophet Joel (Sistine Chapel ceiling)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Michelangelo_Buonarroti_029.jpg","verse":"요엘 2장","lecture":"joel","lectureTitle":"요엘","youtube":"NiOMgPWWAdA","text":["요엘이라는 이름은 여호와는 하나님이시다, 라는 뜻이고, 언제 쓴 글인지는 분명하지 않습니다.","메뚜기 같은 곤충들이 과일나무 껍질까지 다 긁어 먹어, 제사드릴 제물도 나오지 않을 지경이 됩니다.","그래서 요엘은 옷만 찢는 시늉을 하지 말고, 마음을 찢어 하나님께 돌아가라고 외칩니다.","그림 속 요엘은 두루마리를 두 손에 펼쳐 들고 읽고 있습니다."],"audio":"audio/491760e26b8c.mp3","times":[0.3,8.694,17.496,24.978],"dur":30.462},{"act":6,"id":"joel-lhermitte","img":"img/joel-lhermitte.webp","size":[1312,1600],"title":"포도 수확","artist":"레옹 오귀스탱 레르미트","year":"1884","museum":"","credit":"Léon Augustin Lhermitte, The Grape Harvest (1884)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:The_Grape_Harvest_by_L%C3%A9on_Augustin_Lhermitte,_1884.jpg","verse":"요엘 2장","lecture":"joel","lectureTitle":"요엘","youtube":"NiOMgPWWAdA","text":["21절부터는 회복으로, 이른 비와 늦은 비가 돌아와 마당에는 밀이 가득하고 독에는 새 포도주와 기름이 넘칩니다.","메뚜기가 먹은 햇수대로 갚아 주리니, 빼앗긴 만큼 다시 주신다는 약속입니다.","사람들은 포도나무 사이에서 바구니 가득 포도를 거둡니다.","28절, 내가 내 신을 만민에게 부어 주리니, 이 말씀은 오순절에 성령이 오셔서 이루어졌습니다."],"audio":"audio/0ef159659c15.mp3","times":[0.3,10.062,17.28,23.034],"dur":31.878},{"act":6,"id":"kings2-15-uzziah","img":"img/kings2-15-uzziah.webp","size":[1264,1600],"title":"나병 든 웃시야","artist":"렘브란트 판레인","year":"1639년경","museum":"채츠워스 하우스","credit":"Rembrandt, King Uzziah Stricken with Leprosy (Chatsworth House)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Rembrandt_Harmensz._van_Rijn_032.jpg","verse":"열왕기하 15장","lecture":"kings2-15","lectureTitle":"열왕기하 15~16장","youtube":"Cb3lN334wDc","text":["다시 열왕기하 15장으로 돌아오면, 남과 북 두 왕조가 번갈아 나옵니다.","유다 왕 아사랴는 정직히 행했지만 산당은 없애지 못했고, 결국 나병에 걸려 죽는 날까지 별궁에서 지냅니다.","북쪽에서는 살룸, 므나헴, 베가, 호세아가 차례로 반역해서 왕이 되고, 왕마다 평가는 똑같이 여로보암의 죄입니다.","그림 속 왕은 흰 터번 아래 굳은 얼굴로, 어둠 속에서 두 손을 모으고 있습니다."],"audio":"audio/950687f8b292.mp3","times":[0.3,7.086,16.776,27.69],"dur":34.662},{"act":6,"id":"micah-haimann","img":"img/micah-haimann.webp","size":[1600,1050],"title":"베들레헴","artist":"주세페 하이만","year":"1883","museum":"","credit":"Giuseppe Haimann, Bethlehem","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Giuseppe_Haimann_-_Bethlehem.jpg","verse":"미가 5:2","lecture":"micah","lectureTitle":"미가","youtube":"JF8tbxsiMz4","text":["같은 시대의 미가는 사회를 보는 눈이 뛰어나고, 가난한 사람 편에 서는 예언자입니다.","두령은 뇌물을 위해 재판하고, 제사장은 삯을 위해 교훈하고, 선지자는 돈을 위해 점을 칩니다.","그러나 미가는 메시야가 썩은 도시가 아니라 베들레헴 시골 동네에서 나신다고 말합니다.","베들레헴 에브라다야, 너는 유다 족속 중에 작을지라도, 5장 2절의 말씀대로 베들레헴은 푸른 언덕 아래 작은 마을입니다."],"audio":"audio/6a4dd208e187.mp3","times":[0.3,7.83,16.392,23.778],"dur":34.014},{"act":6,"id":"isaiah-heemskerck","img":"img/isaiah-heemskerck.webp","size":[1175,943],"title":"이사야의 예언","artist":"마르턴 판헤임스케르크","year":"1560","museum":"프란스 할스 미술관","credit":"Maarten van Heemskerck, The Prophet Isaiah Foretells the Return of the Jews from Exile (Frans Hals Museum)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Maarten_van_Heemskerck_-_Prophet_Isaiah_predicts_the_return_of_the_Jews_from_exile_1560-1565_FHM01_OS-I-173.jpg","verse":"이사야 40:1","lecture":"isaiah","lectureTitle":"이사야","youtube":"vieUMKtiFpc","text":["이사야는 다섯 왕을 거치며 유다와 예루살렘에서 일했고, 백성의 귀를 막고 눈을 감기라는 희한한 사명을 받습니다.","1장부터 39장까지가 경고라면, 40장부터는 분위기가 완전히 달라집니다.","너희는 위로하라 내 백성을 위로하라, 40장 1절은 70년 복역의 때가 끝났다는 선언입니다.","그림 속 이사야는 손을 뻗어, 폐허가 흩어진 들판과 그 너머의 성을 가리킵니다."],"audio":"audio/70794147a7eb.mp3","times":[0.3,10.11,17.664,26.106],"dur":33.126},{"act":6,"id":"nahum-repent","img":"img/nahum-repent.webp","size":[1600,1351],"title":"니느웨의 회개","artist":"존 마틴","year":"1840","museum":"예일 대학교 미술관","credit":"John Martin, The Repentance of Nineveh (Yale University Art Gallery)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:John_Martin_-_Repentance_of_Nineveh_-_1958.66_-_Yale_University_Art_Gallery.jpg","verse":"나훔 1장","lecture":"nahum","lectureTitle":"나훔","youtube":"WKEV5TsPrSg","text":["요나의 전도로 니느웨의 멸망은 150년 정도 늦춰졌습니다.","그러나 니느웨는 다시 악을 행했고, 엘고스 사람 나훔은 니느웨가 망한다고 경고합니다.","나훔이라는 이름은 위로라는 뜻이니, 니느웨의 멸망은 유대인에게 위로가 되는 소식입니다.","번개 치는 하늘 아래 사람들이 엎드려 있지만, 그 회개는 오래가지 않았습니다."],"audio":"audio/c9f898cbb2d6.mp3","times":[0.3,6.222,13.848,21.906],"dur":28.758},{"act":6,"id":"obadiah-meeting","img":"img/obadiah-meeting.webp","size":[1600,1148],"title":"에서와 야곱의 만남","artist":"조반니 마리아 보탈라","year":"1636–1641","museum":"","credit":"Giovanni Maria Bottalla, Meeting between Esau and Jacob","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Raffaellino_Bottalla_-_Meeting_between_Esau_and_Jacob_-_Google_Art_Project.jpg","verse":"오바댜 1:15","lecture":"obadiah","lectureTitle":"오바댜","youtube":"0_WfbG5N1wQ","text":["오바댜는 에돔이 망할 것을 예언하는데, 에서의 후손인 에돔은 야곱 자손과는 쌍둥이 자손인 셈입니다.","그림 속 에서와 야곱은 서로 끌어안지만, 그 후손 에돔은 형제 나라가 고통당할 때 도와주기는커녕 오히려 좋아했습니다.","너의 행한 대로 너도 받을 것인즉, 너의 행한 것이 네 머리로 돌아갈 것이라, 15절의 말씀입니다.","역사를 잠깐 멈추고 같은 시대 선지자들의 말을 들었으니, 이제 다시 열왕기하 17장으로 역사가 흘러갑니다."],"audio":"audio/54f39f745115.mp3","times":[0.3,9.246,19.128,27.93],"dur":36.918},{"act":7,"id":"kings2-17-sebaste","img":"img/kings2-17-sebaste.webp","size":[1600,1068],"title":"멀리서 본 사마리아","artist":"데이비드 로버츠","year":"","museum":"","credit":"David Roberts, Distant View of Sebaste, Ancient Samaria","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:David_roberts_ra_distant_view_of_sebaste_ancient_samaria112734).jpg","verse":"열왕기하 17장","lecture":"kings2-17","lectureTitle":"열왕기하 17~23장","youtube":"3xInUVQmJ1M","text":["북왕국 이스라엘의 마지막 왕은 호세아입니다.","앗수르 왕 살만에셀 4세가 올라오자, 호세아는 조공을 바치다가 배반하고 애굽 왕 소에게 사신을 보냅니다.","살만에셀은 사마리아를 3년 동안 에워싼 끝에 북이스라엘을 무너뜨리고, 백성을 여러 나라에 흩어 버립니다.","언덕 위에 멀리 보이는 사마리아가 망한 까닭은 한마디로, 시내산 언약과 레위기를 지키지 않았기 때문입니다."],"audio":"audio/f956bdbafb85.mp3","times":[0.3,4.734,13.968,23.274],"dur":32.166},{"act":7,"id":"kings2-17-hiskia","img":"img/kings2-17-hiskia.webp","size":[1600,1201],"title":"히스기야 왕","artist":"작자 미상","year":"","museum":"힐데스하임 성 미카엘 교회","credit":"King Hezekiah, painted ceiling of St. Michael's Church, Hildesheim (photo: Qasinka)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Hildesheim_Michaelis_Hiskia.JPG","verse":"열왕기하 18:13","lecture":"kings2-17","lectureTitle":"열왕기하 17~23장","youtube":"3xInUVQmJ1M","text":["남쪽 유다에서는 18장 13절부터 히스기야 이야기가 이어지는데, 그에게는 잘한 것도 있고 잘못한 것도 있습니다.","앗수르가 예루살렘을 통째로 둘러싸고 하나님을 조롱하자, 다급해진 히스기야는 이사야에게 사람을 보냅니다.","앗수르 군대 18만 5천 명이 하루아침에 죽어 나갔지만, 히스기야는 병문안 온 바벨론 사신에게 성전 금고까지 다 보여 줍니다.","그림 속 왕은 홀과 둥근 보주를 들고 의젓하게 서 있지만, 나 사는 동안만 환난이 없으면 된다던 못난 대답도 이 왕의 것입니다."],"audio":"audio/aae61df58823.mp3","times":[0.3,10.062,19.2,29.73],"dur":40.158},{"act":7,"id":"kings2-17-manasseh","img":"img/kings2-17-manasseh.webp","size":[1600,1467],"title":"므낫세 왕","artist":"하비에르 고리바르","year":"","museum":"키토 산토도밍고 수도원","credit":"Javier Goríbar (attributed), King Manasseh, Convent of Santo Domingo, Quito (photo: Ranoutofusername)","license":"CC BY-SA 4.0","page":"https://commons.wikimedia.org/wiki/File:Manas%C3%A9s_por_Javier_Gor%C3%ADbar_(atribuido)._Convento_de_Santo_Domingo,_Quito.jpg","verse":"열왕기하 21장","lecture":"kings2-17","lectureTitle":"열왕기하 17~23장","youtube":"3xInUVQmJ1M","text":["히스기야의 아들 므낫세는 열두 살에 왕이 되어 55년을 다스립니다.","이 므낫세의 죄 때문에, 하나님께서는 예루살렘을 끝내 용서하지 못하십니다.","전해 오는 이야기로는, 웬만하면 왕의 잘못을 지적하지 않던 이사야가 한마디 하자 톱으로 켜서 죽였다고 합니다.","둥근 금빛 액자 속 므낫세는 왕관을 쓰고 두 손을 모은 채, 어둠 속에서 이쪽을 바라봅니다."],"audio":"audio/819a73b41489.mp3","times":[0.3,6.966,13.944,23.322],"dur":31.59},{"act":7,"id":"kings2-17-heiss","img":"img/kings2-17-heiss.webp","size":[1600,1325],"title":"요시야의 우상 파괴","artist":"요한 하이스","year":"","museum":"","credit":"Johann Heiss, Josiah Destroys the Pagan Idols (photo: David Monniaux)","license":"CC0","page":"https://commons.wikimedia.org/wiki/File:Johann_Heiss_Josiah_Destroys_the_Pagan_Idols_IMG_6364.jpg","verse":"열왕기하 22장","lecture":"kings2-17","lectureTitle":"열왕기하 17~23장","youtube":"3xInUVQmJ1M","text":["여덟 살에 왕이 된 요시야는, 오랜만에 다윗의 길로 가고 좌우로 치우치지 않은 왕입니다.","성전을 고치다가 율법 두루마리를 찾아내자, 스물여섯 살 왕은 옷을 찢으며 크게 울고 회개합니다.","푸른 옷의 젊은 왕이 손을 뻗어 가리키자, 사람들이 밧줄을 걸어 우상을 끌어내리고 부숩니다.","그러나 므낫세 때문에 터진 하나님의 진노는 풀리지 않았고, 요시야는 마흔을 넘기지 못하고 애굽 왕이 앗수르를 치러 올라갈 때 끼어들었다가 죽습니다."],"audio":"audio/3f4dd66e7df0.mp3","times":[0.3,8.166,16.896,24.786],"dur":36.198},{"act":7,"id":"habakkuk-tissot","img":"img/habakkuk-tissot.webp","size":[716,1600],"title":"하박국","artist":"제임스 티소","year":"1904","museum":"","credit":"James Tissot (design) and Charles Hoffbauer, Habakkuk (photo: Phillip Medhurst)","license":"CC BY-SA 4.0","page":"https://commons.wikimedia.org/wiki/File:Habacuc_(Habakkuk_1_12)_%E2%80%A2_invenit_James_Tissot_%E2%80%A2_pinxit_Charles_Hoffbauer_%E2%80%A2_excudit_Maurice_de_Brunoff_apud_Philip_de_Vere_%E2%80%A2_praesentat_Phillip_Medhurst.jpg","verse":"하박국 1장","lecture":"habakkuk","lectureTitle":"하박국","youtube":"xSN6JFmcqwo","text":["하박국은 스바냐, 예레미야와 같은 시대에, 바벨론 군대가 예루살렘을 에워싸던 때에 일한 선지자입니다.","그는 악인이 의인을 괴롭히는데 하나님은 왜 가만히 계시느냐고, 어느 때까지리이까 하며 따져 묻습니다.","하나님의 대답은 사납고 성급한 갈대아 사람을 내가 일으켰다는 것, 그리고 예루살렘에는 의인이 한 명도 남지 않았다는 것이었습니다.","두 팔을 높이 든 그림 속 하박국은, 끝내 몸을 떨며 무화과나무가 무성치 못할지라도 여호와를 인하여 즐거워하리라고 노래합니다."],"audio":"audio/24b3951f5346.mp3","times":[0.3,9.51,18.504,29.13],"dur":39.63},{"act":7,"id":"zephaniah-exile","img":"img/zephaniah-exile.webp","size":[1600,1047],"title":"애통하는 유대 포로","artist":"에두아르트 벤데만","year":"","museum":"쾰른 발라프 리하르츠 미술관","credit":"Eduard Bendemann, Jews Mourning in Exile (Wallraf-Richartz-Museum, Cologne; photo: Raimond Spekking)","license":"CC BY-SA 4.0","page":"https://commons.wikimedia.org/wiki/File:Jews_Mourning_in_Exile_-_Eduard_Bendemann_-_Wallraf-Richartz-Museum_%26_Fondation_Corboud-6071.jpg","verse":"스바냐 2:3","lecture":"zephaniah","lectureTitle":"스바냐","youtube":"QhYreltHJ9Q","text":["요시야 왕 때의 선지자 스바냐는, 첫 장부터 다 진멸하고 멸절하겠다는 말씀을 전합니다.","그런데 스바냐라는 이름은 야훼는 숨겨 주신다는 뜻이고, 2장 3절은 겸손한 자들이 분노의 날에 숨김을 얻으리라고 합니다.","바벨론이라는 호랑이가 온 천지를 물어 죽이고 다닐 때, 하나님은 그들을 호랑이 굴인 바벨론에 옮겨 숨기셨습니다.","낯선 물가 나무 아래 앉은 포로들은 슬퍼하지만, 3장 17절은 깨닫고 돌아오는 그들 때문에 하나님이 기쁨을 이기지 못하신다고 말합니다."],"audio":"audio/b751e269ad38.mp3","times":[0.3,8.454,18.576,27.618],"dur":38.718},{"act":7,"id":"jeremiah-rembrandt","img":"img/jeremiah-rembrandt.webp","size":[1259,1600],"title":"애통하는 예레미야","artist":"렘브란트 판레인","year":"1630","museum":"암스테르담 국립미술관","credit":"Rembrandt, Jeremiah Lamenting the Destruction of Jerusalem (1630, Rijksmuseum)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Rembrandt_Harmensz._van_Rijn_-_Jeremia_treurend_over_de_verwoesting_van_Jeruzalem_-_Google_Art_Project.jpg","verse":"예레미야 1장","lecture":"jeremiah","lectureTitle":"예레미야","youtube":"tMnQ-g8sQOE","text":["예레미야도 스바냐와 같은 시대의 선지자로, 베냐민 땅 아나돗의 제사장 집안 출신입니다.","70세가 넘도록, 아내도 자녀도 없이, 아무도 듣지 않는 설교를 40년 넘게 했습니다.","5장 1절, 공의를 행하는 자를 한 사람이라도 찾으면 이 성을 용서하겠다고 하셨지만, 그 한 사람이 없어 예루살렘은 멸망합니다.","그림 속 예레미야는 한 손에 머리를 기댄 채 고개를 떨구고, 뒤편 어둠 속에서는 성이 불길에 휩싸여 있습니다."],"audio":"audio/292d968f58e7.mp3","times":[0.3,8.118,16.152,26.874],"dur":36.246},{"act":7,"id":"jeremiah-manetti","img":"img/jeremiah-manetti.webp","size":[1600,1129],"title":"예레미야와 바룩","artist":"루틸리오 마네티","year":"1600–1639","museum":"","credit":"Rutilio Manetti, The Prophets Jeremiah and Baruch","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Rutilio_Manetti_-_The_prophets_Jeremiah_and_Baruch.jpg","verse":"예레미야 36장","lecture":"jeremiah","lectureTitle":"예레미야","youtube":"tMnQ-g8sQOE","text":["36장에서 하나님은 요시야 때부터 한 말을 다 기록하라고 하시고, 바룩이 받아 적습니다.","혹시 듣고 돌이키면 용서하겠다는 말씀이었지만, 여호야김 왕은 읽는 대로 칼로 베어 화로 불에 던져 다 태워 버립니다.","하나님이 다시 기록하라고 하셔서 바룩이 빠뜨린 것을 중간중간 넣다 보니, 예레미야서는 좀 뒤죽박죽입니다.","두 사람은 펼친 책 위로 몸을 숙이고, 한 사람이 손가락으로 글줄을 짚고 있습니다."],"audio":"audio/d211569867c8.mp3","times":[0.3,8.454,18.312,27.618],"dur":34.878},{"act":7,"id":"kings2-24-stallaert","img":"img/kings2-24-stallaert.webp","size":[1474,1000],"title":"시드기야에게 멸망을 예언하는 예레미야","artist":"조제프 스탈라르트","year":"","museum":"","credit":"Joseph Stallaert, The Prophet Jeremiah Foretells to King Zedekiah the Fall of Jerusalem","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Joseph_Stallaert_-_Der_Prophet_Jeremias_weissagt_dem_K%C3%B6nig_Zedekia_den_Untergang_Jerusalem.jpg","verse":"열왕기하 24장","lecture":"kings2-24","lectureTitle":"열왕기하 24~25장","youtube":"2r0qF1YJEwY","text":["열왕기하 24장과 25장은 예레미야 52장과 똑같아서, 쓴 사람이 같을 가능성이 높다고 봅니다.","시드기야처럼 무지와 고집과 오해와 편견을 가지고 있으면, 바른 진리를 말해 주는 사람이 있어도 듣지를 못합니다.","그림 속 흰 수염의 예레미야가 한 손을 높이 들고 누워 있는 왕을 가리키자, 둘러선 사람들이 놀라 몸을 움츠립니다.","왕도 백성도 끝내 그 말을 듣지 않았고, 이제 예루살렘의 마지막 날이 다가옵니다."],"audio":"audio/ac989cd971d5.mp3","times":[0.3,9.87,19.176,28.938],"dur":36.054},{"act":7,"id":"lamentations-ruins","img":"img/lamentations-ruins.webp","size":[1600,863],"title":"폐허 속의 예레미야","artist":"에두아르트 벤데만 원작","year":"1837","museum":"","credit":"After Eduard Bendemann, Jeremiah Seated in the Ruins of Jerusalem","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Eduard_Bendemann_-_Jeremia_seated_in_the_ruins_of_Jerusalem.jpg","verse":"예레미야애가 1:1","lecture":"lamentations","lectureTitle":"예레미야 애가","youtube":"rrgX_tnUq0U","text":["슬프다 이 성이여, 예레미야애가는 1장 1절을 이렇게 엽니다.","애굽에서 돌아온 예레미야는, 40년 동안 피눈물로 말씀을 전하고 기도했던 예루살렘 거리를 마지막으로 걸어 봅니다.","붉은 옷의 예레미야는 무너진 돌 위에 앉아 이마를 짚었고, 그 곁에서 여인들과 아이들이 얼굴을 묻고 있습니다.","사람의 역사에서 이렇게 애절한 애가는, 앞에도 없고 뒤에도 없습니다."],"audio":"audio/ab1f82a7d693.mp3","times":[0.3,6.486,16.056,25.338],"dur":31.974},{"act":7,"id":"lamentations-burning","img":"img/lamentations-burning.webp","size":[1600,933],"title":"불타는 예루살렘","artist":"후안 데 라 코르테 화파","year":"1630–1660","museum":"","credit":"Circle of Juan de la Corte, The Burning of Jerusalem by Nebuchadnezzar's Army","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Circle_of_Juan_de_la_Corte_-_The_Burning_of_Jerusalem_by_Nebuchadnezzar%E2%80%99s_Army_-_Google_Art_Project.jpg","verse":"열왕기하 25장","lecture":"lamentations","lectureTitle":"예레미야 애가","youtube":"rrgX_tnUq0U","text":["586년 4월, 도망가던 시드기야는 붙잡혀 눈이 뽑힌 채 바벨론으로 끌려갑니다.","예루살렘이 무너지고, 거룩한 솔로몬의 성전은 불에 타서 내려앉았습니다.","그림 속 성은 불길과 연기에 휩싸였고, 그 앞 들판에는 병거와 말들이 뒤엉켜 달려갑니다.","왕족과 귀족들은 죽거나 붙잡혀 갔고, 거리에서 놀던 어린아이들도 그렇게 되었습니다."],"audio":"audio/9aeb658abdfa.mp3","times":[0.3,8.358,15.168,23.658],"dur":31.254},{"act":7,"id":"lamentations-brazen","img":"img/lamentations-brazen.webp","size":[1600,859],"title":"놋 바다를 부수다","artist":"제임스 티소","year":"1896~1902년경","museum":"뉴욕 유대 박물관","credit":"James Tissot, The Chaldees Destroy the Brazen Sea (c. 1896-1902, Jewish Museum, New York)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Tissot,_James_%E2%80%94_The_Chaldees_Destroy_the_Brazen_Sea_%E2%80%94_c._1896-1902_%E2%80%94_Jewish_Museum,_New_York_(official_online_image)_uploaded_by_Mattes.jpg","verse":"열왕기하 25:13","lecture":"lamentations","lectureTitle":"예레미야 애가","youtube":"rrgX_tnUq0U","text":["갈대아 사람들이 성전의 커다란 놋그릇과 기둥을 망치로 내리쳐 부수고 있습니다.","어린아이가 빵을 달라고 해도 떼어 줄 사람이 없고, 눈이 짓무르도록 울어도 위로할 사람이 없었습니다.","보물은 다 빼앗기고, 사람들 마음속의 기쁨, 믿음, 소망, 사랑까지 전부 다 파괴되어 버렸습니다.","200만 명이 출애굽한 뒤로 크게 불어났을 백성이 다 죽고, 포로로 남은 사람은 모두 4600명이었습니다."],"audio":"audio/ccba03063859.mp3","times":[0.3,7.47,15.912,25.842],"dur":34.878},{"act":8,"id":"daniel-hauslab","img":"img/daniel-hauslab.webp","size":[1200,1600],"title":"다니엘의 해몽","artist":"프란츠 폰 하우슬라프","year":"1815–1883","museum":"메트로폴리탄 미술관","credit":"Franz von Hauslab the Younger, Daniel Interprets Nebuchadnezzar's Dream (Metropolitan Museum of Art)","license":"CC0","page":"https://commons.wikimedia.org/wiki/File:Daniel_interprets_Nebuchadnezzar%27s_Dream_MET_DP804327.jpg","verse":"다니엘 2:28","lecture":"daniel","lectureTitle":"다니엘","youtube":"vTLGv5hnqQc","text":["바벨론에 포로로 끌려간 유대인들이 그곳에서 무엇을 깨닫고 무엇이 달라졌는지, 다니엘서가 들려줍니다.","다니엘과 세 친구는 왕의 부정한 음식을 거부하고 채식만 했는데도, 얼굴이 더 좋아 왕궁에 뽑혔습니다.","느부갓네살이 꾼 꿈을 아무도 맞히지 못할 때, 다니엘은 은밀한 일을 나타내실 분은 오직 하늘의 하나님뿐이라고 말합니다.","그림 속 붉은 옷의 왕은 휘장 아래 앉아 있고, 흰 옷을 입은 젊은이가 왕을 가리키며 꿈을 풀어 줍니다."],"audio":"audio/36e129517021.mp3","times":[0.3,9.726,18.888,28.602],"dur":37.086},{"act":8,"id":"daniel-giordano","img":"img/daniel-giordano.webp","size":[1277,1600],"title":"풀무불의 세 사람","artist":"루카 조르다노","year":"","museum":"","credit":"Luca Giordano, Shadrach, Meshach and Abednego in the Furnace","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Shadrach,_Meshach,_and_Abednego_in_the_Furnace).jpeg","verse":"다니엘 3:17","lecture":"daniel","lectureTitle":"다니엘","youtube":"vTLGv5hnqQc","text":["그런데 느부갓네살은 높이 60규빗의 금 신상을 세우고, 절하지 않으면 풀무불에 던지겠다고 합니다.","세 친구는 하나님이 능히 건져 내시겠고, 그리 아니하실지라도 절하지 않겠다고 대답합니다.","일곱 배나 뜨겁게 한 불에 세 사람을 던졌는데, 네 사람의 그림자가 보이고 세 사람은 머리카락도 그슬리지 않은 채 살아 나옵니다.","불길 한가운데에 세 사람이 있고, 위에서는 빛이 쏟아지며, 불을 지피던 사람들은 바닥에 쓰러져 있습니다."],"audio":"audio/de9b65d9e336.mp3","times":[0.3,9.078,17.328,27.858],"dur":36.966},{"act":8,"id":"daniel-rembrandt","img":"img/daniel-rembrandt.webp","size":[1600,1274],"title":"벨사살의 연회","artist":"렘브란트 판레인","year":"1636~1638년경","museum":"런던 내셔널 갤러리","credit":"Rembrandt, Belshazzar's Feast (c. 1636-38, National Gallery, London)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Rembrandt-Belsazar.jpg","verse":"다니엘 5:25","lecture":"daniel","lectureTitle":"다니엘","youtube":"vTLGv5hnqQc","text":["5장에서 왕이 바뀌어 벨사살이 되고, 그는 예루살렘 성전에서 빼앗아 온 금그릇으로 술을 마십니다.","그러자 갑자기 벽에 손이 나타나 글씨를 쓰고, 왕은 무릎이 서로 부딪칠 만큼 떱니다.","다니엘이 읽은 글은 메네 메네 데겔 우바르신, 세어 보고 세어 보고 달아 보고 나눈다는 뜻입니다.","그림 속 벨사살은 벽에 빛나는 글씨를 돌아보며 몸을 젖히고, 곁의 여인이 든 잔에서는 술이 쏟아집니다."],"audio":"audio/e1458d89ceb8.mp3","times":[0.3,9.006,16.752,25.17],"dur":34.014},{"act":8,"id":"daniel-riviere","img":"img/daniel-riviere.webp","size":[1600,1030],"title":"사자 굴의 다니엘","artist":"브리턴 리비에르","year":"1890","museum":"맨체스터 미술관","credit":"Briton Rivière, Daniel's Answer to the King (1890, Manchester Art Gallery)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Briton_Riviere_-_Daniel%27s_Answer_to_the_King_(Manchester_Art_Gallery).jpg","verse":"다니엘 6:28","lecture":"daniel","lectureTitle":"다니엘","youtube":"vTLGv5hnqQc","text":["그날 밤 벨사살은 죽고, 그 어마어마한 바벨론은 86년 만에 역사 속에서 사라집니다.","6장에서 왕이 된 다리오는 기도를 금했지만, 다니엘은 기도했고 사자 굴에 던져졌다가 살아 나옵니다.","다니엘은 나라가 바뀌어도 총리였고, 다리오 왕과 고레스 왕의 시대에 형통했습니다.","다니엘은 두 손을 뒤로 한 채 사자들에게 등을 돌리고, 위에서 드는 빛을 올려다봅니다."],"audio":"audio/bb698264a82f.mp3","times":[0.3,8.598,17.616,25.074],"dur":32.622},{"act":8,"id":"ezekiel-icon","img":"img/ezekiel-icon.webp","size":[999,1600],"title":"에스겔","artist":"작자 미상","year":"17세기","museum":"개인 소장","credit":"The Prophet Ezekiel, icon (17th century, North Russia, private collection)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Icon_of_Ezekiel_(17th_c.,_North_Russia,_priv._coll.).jpg","verse":"에스겔 3:3","lecture":"ezekiel","lectureTitle":"에스겔","youtube":"jujjstNeIUQ","text":["예레미야는 왜 끌려가야 하는지를, 다니엘은 끌려가서 무엇을 배웠는지를, 에스겔은 왜 끌려왔는지를 설명합니다.","갈대아 땅 그발 강 가에서 하늘이 열리고, 포로로 잡혀간 에스겔은 하나님이 보여 주시는 이상을 봅니다.","하나님은 애곡과 재앙의 말이 적힌 두루마리를 먹으라 하셨고, 에스겔이 먹어 보니 꿀처럼 달았습니다.","그림 속 에스겔은 큰 글씨가 적힌 두루마리를 펼쳐 들고 있습니다."],"audio":"audio/ea103532ae31.mp3","times":[0.3,10.134,18.384,26.826],"dur":32.718},{"act":8,"id":"ezekiel-shepherd","img":"img/ezekiel-shepherd.webp","size":[1600,1091],"title":"저녁 빛 속의 목동","artist":"아우구스트 핑크","year":"","museum":"","credit":"August Fink, Shepherd with His Flock in the Evening Light","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:August_Fink_-_Shepherd_with_his_Flock_in_the_Evening_Light.jpg","verse":"에스겔 37장","lecture":"ezekiel","lectureTitle":"에스겔","youtube":"jujjstNeIUQ","text":["바벨론의 칼과 불타 버린 예루살렘으로 심판은 그대로 이루어졌지만, 하나님은 회복도 약속하십니다.","34장에서 하나님은 자기 배만 채우는 목자들 대신, 진실한 한 목자를 세우겠다고 하십니다.","37장 골짜기 환상에서는 흩어진 뼈들이 다시 모여 큰 군대가 되니, 흩어진 백성을 살려 본토로 돌아오게 하신다는 뜻입니다.","저녁 빛이 비스듬히 드는 풀밭에서, 양 떼가 조용히 풀을 뜯고 있습니다."],"audio":"audio/eac12590cd7d.mp3","times":[0.3,9.006,17.424,27.858],"dur":34.206},{"act":8,"id":"chronicles-david","img":"img/chronicles-david.webp","size":[1600,1274],"title":"하프 타는 다윗","artist":"헨드릭 테르브뤼헌","year":"1628","museum":"바르샤바 국립박물관","credit":"Hendrick ter Brugghen, King David Playing the Harp among Angels (National Museum in Warsaw)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Hendrick_ter_Brugghen_-_King_David_playing_the_harp_among_angels_-_M.Ob.529_MNW_-_National_Museum_in_Warsaw.jpg","verse":"역대상 1:1","lecture":"chronicles","lectureTitle":"역대상 · 하","youtube":"_ujBYexmPmA","text":["바벨론 포로에서 70년 만에 돌아와 보니, 나라는 완전히 무너진 황무지 같았습니다.","역대기는 아담까지 거슬러 올라가 지난 역사를 돌아보며, 새로 세울 나라의 본보기를 찾습니다.","그래서 다윗과 솔로몬 시대는 의례와 제도까지 자세히 적고, 본받을 것이 없는 부분은 이름만 줄줄이 넘깁니다.","그림 속 다윗은 천사들에게 둘러싸여 하프를 타며 고개를 들고 있습니다."],"audio":"audio/7fd883da7640.mp3","times":[0.3,7.902,16.104,25.602],"dur":32.238},{"act":8,"id":"ezra-1-keyser","img":"img/ezra-1-keyser.webp","size":[1235,1600],"title":"성전 기물 반환","artist":"토마스 더케이저","year":"1660","museum":"","credit":"Thomas de Keyser (after Pieter Lastman), Cyrus Restores the Treasures of the Temple","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Keyser,_Thomas_de_-_after_Pieter_Lastman_-_Cyrus_restores_the_treasures_of_the_temple.jpg","verse":"에스라 1:2","lecture":"ezra-1","lectureTitle":"에스라 1~4장","youtube":"PYE3sKlN7Ek","text":["역대기의 마지막과 에스라서의 첫머리에는 고레스 칙령이 토씨 하나 틀리지 않고 똑같이 실려 있습니다.","유다 예루살렘으로 올라가 여호와의 전을 건축하라는 칙령에, 1차 포로 때부터 딱 70년 만에 백성이 돌아옵니다.","성전 지대가 놓이자 첫 성전을 보았던 노인들은 대성통곡하고, 여러 사람은 기뻐서 즐거이 불렀습니다.","붉은 옷의 고레스가 손을 뻗어 가리키고, 사람들은 금 그릇들을 받쳐 들고 무릎을 꿇습니다."],"audio":"audio/226b1a47e253.mp3","times":[0.3,9.102,18.504,27.546],"dur":35.91},{"act":8,"id":"haggai-pesellino","img":"img/haggai-pesellino.webp","size":[1190,1024],"title":"성전 건축","artist":"프란체스코 페셀리노","year":"1445","museum":"하버드 미술관","credit":"Pesellino, The Construction of the Temple of Jerusalem (Harvard Art Museums / Fogg Museum)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Pesellino_(Francesco_di_Stefano)_-_The_Construction_of_the_Temple_of_Jerusalem_-_1916.495_-_Fogg_Museum.jpg","verse":"학개 1:4","lecture":"haggai","lectureTitle":"학개","youtube":"_Oea4Zw2o-o","text":["그러나 주변의 방해로 성전 공사는 15년 동안 멈추고, 사람들은 성전 자재로 자기 집을 지어 버립니다.","그때 학개가 외칩니다, 이 전이 황무한데 너희는 판벽한 집에 사는 것이 옳으냐.","예전에는 선지자를 때리고 죽이던 백성이, 이번에는 학개의 말을 듣고 일어나 하나님의 전 일을 합니다.","그림 속 일꾼들은 긴 목재를 어깨에 메고 날라, 올라가는 벽 위에 걸치고 있습니다."],"audio":"audio/2c422fd30617.mp3","times":[0.3,9.414,16.536,24.978],"dur":32.334},{"act":8,"id":"zechariah-getty","img":"img/zechariah-getty.webp","size":[1600,680],"title":"스가랴의 환상","artist":"작자 미상","year":"1300년경","museum":"J. 폴 게티 미술관","credit":"The Vision of Zechariah, Sicily, about 1300 (J. Paul Getty Museum, Ms. 35)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:The_Vision_of_Zechariah_-_Google_Art_Project.jpg","verse":"스가랴 1:8","lecture":"zechariah","lectureTitle":"스가랴","youtube":"CLKDaVk1f04","text":["학개와 같은 때에 젊은 선지자 스가랴도, 성전이 다시 건축된다고 말합니다.","스가랴가 밤에 보니, 한 사람이 홍마를 타고 화석류나무 사이에 서 있고, 그 뒤에 홍마와 자마와 백마가 있었습니다.","이들은 여호와께서 땅에 두루 다니라고 보내신 자들로, 하나님은 날마다 천사를 보내 이 땅을 지켜보십니다.","날개 달린 천사와 스가랴가 나란히 서서, 붉은 말과 흰 말들을 바라봅니다."],"audio":"audio/24da9803b6ab.mp3","times":[0.3,7.326,17.064,26.13],"dur":32.958},{"act":8,"id":"ezra-5-diano","img":"img/ezra-5-diano.webp","size":[1600,850],"title":"성전 봉헌","artist":"자친토 디아노","year":"","museum":"","credit":"Giacinto Diano, The Dedication of the Temple at Jerusalem","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:The_Dedication_of_the_Temple_at_Jerusalem_P5645.jpg","verse":"에스라 6:16","lecture":"ezra-5","lectureTitle":"에스라 5~6장","youtube":"vJhK-aboq58","text":["다시 시작된 공사는 다리오 왕이 찾아낸 고레스의 허가서 덕분에 일사천리로 진행됩니다.","기원전 516년에 완공했으니, 성전이 무너진 뒤 딱 70년 만에 정확히 회복된 것입니다.","이스라엘 자손은 기쁘게 봉헌식을 하고, 정월 14일에 유월절을 지킵니다.","그림 속 사람들은 연기가 오르는 제단 앞 계단에 엎드리고, 구름 사이에서는 아기 천사들이 내려다봅니다."],"audio":"audio/5e3f113812fd.mp3","times":[0.3,8.334,17.04,24.21],"dur":33.078},{"act":8,"id":"esther-witz","img":"img/esther-witz.webp","size":[1495,1600],"title":"왕 앞의 에스더","artist":"콘라트 비츠","year":"1435","museum":"","credit":"Konrad Witz, Esther before Ahasuerus","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Konrad_Witz_-_Esther_before_Ahasuerus_(c._1435).jpg","verse":"에스더 4:16","lecture":"esther","lectureTitle":"에스더","youtube":"2V0Bbs1hVos","text":["그 무렵 페르시아에서는 유대인들이 몰살당할 뻔한 일이 일어납니다.","모든 대신 위에 오른 아각 사람 하만은, 자기에게 절하지 않는 모르드개 때문에 유다인을 다 진멸하자는 조서를 받아 냅니다.","부름 없이 왕에게 나아가면 죽는 법이었지만, 왕후 에스더는 죽으면 죽으리이다 하고 나아갑니다.","왕이 내민 금규가 에스더에게 닿고, 에스더는 두 손을 들어 올립니다."],"audio":"audio/7e42b5ca841f.mp3","times":[0.3,6.534,16.56,24.498],"dur":30.87},{"act":8,"id":"esther-rembrandt","img":"img/esther-rembrandt.webp","size":[1600,1218],"title":"에스더의 잔치","artist":"렘브란트 판레인","year":"1660","museum":"","credit":"Rembrandt, Ahasuerus and Haman at the Feast of Esther","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Rembrandt_Harmensz_van_Rijn_-_Ahasuerus,_Haman_and_Esther_-_Google_Art_Project.jpg","verse":"에스더 5:8","lecture":"esther","lectureTitle":"에스더","youtube":"2V0Bbs1hVos","text":["왕은 나라의 절반이라도 주겠다고 하지만, 에스더는 바로 말하지 않습니다.","꼼꼼한 에스더는 왕과 하만을 잔치에 청하고, 내일 또 오시라고 하루를 더 보내게 합니다.","기분 좋게 나오던 하만은 일어나지도 않는 모르드개를 보고, 그를 달려고 오십 규빗 높이의 나무를 세웁니다.","그림 속 왕과 에스더는 금빛 속에 앉아 있고, 하만은 왼쪽 어둠 속에 앉아 있습니다."],"audio":"audio/5c6f6b659709.mp3","times":[0.3,7.422,15.744,24.45],"dur":31.806},{"act":8,"id":"esther-triumph","img":"img/esther-triumph.webp","size":[1600,717],"title":"모르드개의 개선","artist":"장프랑수아 드트루아","year":"1736년경","museum":"메트로폴리탄 미술관","credit":"Jean-François de Troy, The Triumph of Mordecai (The Metropolitan Museum of Art)","license":"CC0","page":"https://commons.wikimedia.org/wiki/File:The_Triumph_of_Mordecai_MET_DP-14284-001.jpg","verse":"에스더 6:11","lecture":"esther","lectureTitle":"에스더","youtube":"2V0Bbs1hVos","text":["그날 밤 잠을 설친 왕은 궁중 일기를 읽다가, 모르드개가 자기를 살렸는데 아무것도 해 준 것이 없음을 알게 됩니다.","왕이 존귀케 하기를 기뻐하는 사람에게 어떻게 하면 좋겠느냐고 묻자, 하만은 당연히 자기라고 믿고 왕복과 말과 왕관을 말합니다.","그런데 왕은 그대로 모르드개에게 하라고 합니다.","흰 말을 탄 모르드개가 거리를 지나고, 사람들은 길가에 엎드려 그를 맞습니다."],"audio":"audio/6982aebcf5f6.mp3","times":[0.3,10.062,20.544,25.386],"dur":32.502},{"act":8,"id":"esther-lastman","img":"img/esther-lastman.webp","size":[1600,1132],"title":"하만의 애원","artist":"피터르 라스트만","year":"","museum":"바르샤바 국립박물관","credit":"Pieter Lastman, Haman Begging the Mercy of Esther (National Museum in Warsaw)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Pieter_Lastman_-_Haman_begging_the_mercy_of_Esther_(Esther_7-6-7)_-_M.Ob.558_MNW_-_National_Museum_in_Warsaw.jpg","verse":"에스더 7:6","lecture":"esther","lectureTitle":"에스더","youtube":"2V0Bbs1hVos","text":["둘째 날 잔치에서 에스더가 말합니다, 대적과 원수는 이 악한 하만이니이다.","하만은 자기가 세운 오십 규빗 나무에 달리고, 제비를 뜻하는 부르의 이름을 따서 이날을 부림이라 부릅니다.","에스더서는 모르드개가 왕 다음 자리에 올라 존귀함을 받고, 백성의 유익을 꾀했다는 이야기로 끝납니다.","그림 속 하만은 에스더의 옷자락에 매달려 애원하고, 에스더는 몸을 젖혀 그를 뿌리칩니다."],"audio":"audio/2dab8c50640d.mp3","times":[0.3,7.35,16.32,24.954],"dur":32.622},{"act":9,"id":"job-tanner","img":"img/job-tanner.webp","size":[1251,1024],"title":"욥과 세 친구","artist":"헨리 오사와 태너","year":"1904","museum":"","credit":"Henry Ossawa Tanner, Job and His Three Friends","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Job_and_his_Three_Friends,_by_Henry_Ossawa_Tanner.jpg","verse":"욥기 2장","lecture":"job","lectureTitle":"욥기","youtube":"JQFUwZVPUmw","text":["역사의 흐름을 잠시 벗어나 펼치는 욥기는, 의인의 고난을 주제로 한 연극 대본입니다.","하나님께서 욥을 자랑하시자 사단은 몸을 쳐 보라 했고, 욥은 살가죽이 다 없어질 만큼 무서운 병에 걸립니다.","그림 속 욥은 어두운 바닥에 쓰러져 있고, 곁에 앉은 친구는 고개를 숙인 채 말이 없습니다.","일주일 동안 말을 잃었던 친구들은 입을 열자, 네게 무슨 죄가 있으니 이런 불행을 당한 것이라고 몰아붙입니다."],"audio":"audio/e9590d5849cd.mp3","times":[0.3,8.046,17.352,25.338],"dur":34.35},{"act":9,"id":"job-restored","img":"img/job-restored.webp","size":[1600,1520],"title":"회복된 욥","artist":"제임스 티소","year":"1904","museum":"","credit":"After James Tissot (painted by Michel Simonidy), Job Restored to Prosperity (photo: Phillip Medhurst)","license":"CC BY-SA 4.0","page":"https://commons.wikimedia.org/wiki/File:359.3_402_Job_r%C3%A9tabli_dans_sa_prosp%C3%A9rit%C3%A9_(Job_42_12)_%E2%80%A2_invenit_James_Tissot_%E2%80%A2_pinxit_Michel_Simonidy_%E2%80%A2_excudit_Maurice_de_Brunoff_apud_Philip_de_Vere_%E2%80%A2_praesentat_Phillip_Medhurst.jpg","verse":"욥기 42장","lecture":"job","lectureTitle":"욥기","youtube":"JQFUwZVPUmw","text":["38장에서 여호와께서 폭풍 가운데 말씀하시자, 욥은 손으로 입을 가리고 티끌과 재 가운데서 회개합니다.","그 후에 하나님께서 욥에게 처음보다 갑절이나 복을 주시고, 자녀는 원래 수대로 열 명을 채워 주셨습니다.","흰 수염의 욥 곁으로, 젊은 자녀들이 모여 기대어 있습니다.","지난번에 당한 일은 결론이 아니라, 과정이었습니다."],"audio":"audio/007a93d0a3aa.mp3","times":[0.3,9.702,18.576,24.234],"dur":29.334},{"act":9,"id":"psalms-singing","img":"img/psalms-singing.webp","size":[1061,1600],"title":"노래하는 다윗","artist":"제임스 티소","year":"1904","museum":"","credit":"After James Tissot (painted by Michel Simonidy), David Singing (photo: Phillip Medhurst)","license":"CC BY-SA 4.0","page":"https://commons.wikimedia.org/wiki/File:David_chantant_(Psalm_57_7)_%E2%80%A2_invenit_James_Tissot_%E2%80%A2_pinxit_Michel_Simonidy_%E2%80%A2_excudit_Maurice_de_Brunoff_apud_Philip_de_Vere_%E2%80%A2_praesentat_Phillip_Medhurst.jpg","verse":"시편 57편","lecture":"psalms","lectureTitle":"시편","youtube":"6gZD6eKepUM","text":["시편은 이스라엘 사람들이 스룹바벨 성전 시대에 부른 찬양을 모은, 히브리 사람들의 찬송가집입니다.","모세부터 아삽 자손까지 천 년쯤 걸려 다섯 권으로 엮였고, 그 가운데 거의 절반인 73편 정도가 다윗의 시편입니다.","다윗이 이렇게 많은 시편을 남길 수 있었던 것은, 기도를 생각하고 정리해서 늘 원고를 써 두었기 때문입니다.","그림 속 다윗이 하프를 타며 하늘을 우러르는 발치에서, 한 사람이 엎드려 그 노래를 받아 적고 있습니다."],"audio":"audio/bf38ce64c2d9.mp3","times":[0.3,8.814,18.936,28.17],"dur":36.942},{"act":9,"id":"proverbs-parabole","img":"img/proverbs-parabole.webp","size":[955,737],"title":"솔로몬의 잠언","artist":"작자 미상","year":"","museum":"영국 도서관","credit":"Solomon Writing the Proverbs, initial from the Arnstein Bible (British Library, Harley MS 2799)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Salom%C3%B3n_escribiendo_%E2%80%98Parabole_Salomonis%E2%80%99_-_Harley_MS_2799,_f._57v_(%27The_Arnstein_Bible%27)_-_detalle.jpg","verse":"잠언 1장","lecture":"proverbs","lectureTitle":"잠언","youtube":"4OX2DL4R3xs","text":["잠언은 솔로몬이 지혜와 명철이 가장 뛰어났을 때 쓴 책으로, 히브리어로는 마샬, 곧 솔로몬의 금언입니다.","솔로몬은 잠언을 삼천 개 넘게 썼는데, 히스기야의 신하들이 골라 뽑고 엮은 것이 지금의 잠언입니다.","1장은 이 책을 쓴 까닭을, 지혜와 훈계를 알게 하고 어리석은 자를 슬기롭게 하려는 것이라고 밝힙니다.","화려한 첫 글자 안에 앉은 솔로몬이, 펼친 책에 글을 쓰고 있습니다."],"audio":"audio/6679a3e54701.mp3","times":[0.3,9.63,18.672,28.05],"dur":34.302},{"act":9,"id":"ecclesiastes-steenwijck","img":"img/ecclesiastes-steenwijck.webp","size":[1600,1257],"title":"인생의 헛됨","artist":"하르먼 스테인베이크","year":"1640년경","museum":"","credit":"Harmen Steenwijck, An Allegory of the Vanities of Human Life","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Harmen_Steenwijck_-_Vanitas_Still-Life_-_WGA21768.jpg","verse":"전도서 12:13","lecture":"ecclesiastes","lectureTitle":"전도서","youtube":"5YmjfcEiF7Q","text":["그 솔로몬이 깊이 타락했다가 맨 마지막에 정신이 돌아와서 쓴 간증이, 솔로몬의 인생론 전도서입니다.","헛되고 헛되며 헛되니, 부귀와 명예와 쾌락까지 다 해 본 솔로몬에게 세상 것은 행복을 주지 않았습니다.","그림 속 해골과 낡은 책들 위로, 한 줄기 빛이 비스듬히 들어옵니다.","그러나 헛된 것이 결론이 아니며, 12장은 하나님을 경외하고 그 명령을 지키는 것이 사람의 본분이라고 맺습니다."],"audio":"audio/05e4cf1964b5.mp3","times":[0.3,9.27,18.144,24.546],"dur":33.822},{"act":9,"id":"song-lovesong","img":"img/song-lovesong.webp","size":[1600,1186],"title":"사랑의 노래","artist":"에드워드 번존스","year":"1868–1877","museum":"메트로폴리탄 미술관","credit":"Edward Burne-Jones, The Love Song (Le Chant d'Amour) (Metropolitan Museum of Art)","license":"CC0","page":"https://commons.wikimedia.org/wiki/File:The_Love_Song_MET_DP323394.jpg","verse":"아가 1장","lecture":"song","lectureTitle":"아가","youtube":"2Ez7JvJXIOc","text":["아가는 히브리어로 쉬르 하시림, 노래 중의 노래라는 뜻입니다.","솔로몬이 지은 1005곡 가운데 가장 아름다운 노래로, 남자와 여자 사이의 때 묻지 않은 사랑을 노래합니다.","갑옷 입은 기사가 땅에 앉아, 악기를 연주하는 여인을 바라봅니다.","그 사랑이 하나님의 사랑과 닮은 데가 있다고 보아, 아가는 정경으로 들어오게 되었습니다."],"audio":"audio/cd17684bab66.mp3","times":[0.3,6.03,14.928,20.994],"dur":28.23},{"act":9,"id":"ezra-7-codex","img":"img/ezra-7-codex.webp","size":[1157,1600],"title":"학사 에스라","artist":"작자 미상","year":"","museum":"피렌체 메디치 라우렌치아나 도서관","credit":"Ezra the Scribe, Codex Amiatinus, fol. 5r (Biblioteca Medicea Laurenziana, Florence; photo: Gennadii Saus i Segura)","license":"CC BY-SA 4.0","page":"https://commons.wikimedia.org/wiki/File:Codex_Amiantinus._Firenze,_Biblioteca_Medicea_Laurenziana,_Amiat.1,_fol._5r.jpg","verse":"에스라 7:10","lecture":"ezra-7","lectureTitle":"에스라 7~10장","youtube":"v75xgj9Y9nY","text":["에스라 7장부터는, 에스라가 중심인 2차 귀환 이야기입니다.","에스라는 자신을 모세의 율법에 익숙한 학사라고 소개하고, 7장 10절에서 율법을 연구하여 준행하며 가르치기로 결심합니다.","그림 속 에스라는 책이 가득한 장 앞에 앉아, 무릎 위의 책에 글을 쓰고 있습니다.","그러나 지도자들까지 이방 여인을 아내로 맞은 일을 바로잡자, 그 친척들이 몰려와 성을 무너뜨리고 성문을 불태웁니다."],"audio":"audio/ca1697687151.mp3","times":[0.3,6.462,16.944,24.09],"dur":33.846},{"act":9,"id":"nehemiah-tissot","img":"img/nehemiah-tissot.webp","size":[1600,1541],"title":"아닥사스다 왕 앞의 느헤미야","artist":"제임스 티소","year":"1904","museum":"","credit":"After James Tissot (painted by Michel Simonidy), Nehemiah before the King (Esdras et son Roi; photo: Phillip Medhurst)","license":"CC BY-SA 4.0","page":"https://commons.wikimedia.org/wiki/File:Esdras_et_son_Roi_(Nehemiah_2_2)_%E2%80%A2_invenit_James_Tissot_%E2%80%A2_pinxit_Michel_Simonidy_%E2%80%A2_excudit_Maurice_de_Brunoff_apud_Philip_de_Vere_%E2%80%A2_praesentat_Phillip_Medhurst.jpg","verse":"느헤미야 2장","lecture":"nehemiah","lectureTitle":"느헤미야","youtube":"1zccD52liyA","text":["예루살렘 성이 무너지고 성문들이 불탔다는 소식에, 느헤미야는 가 본 적도 없는 그 성을 위해 울며 금식하고 기도합니다.","느헤미야는 페르시아 황제가 가장 믿는 최측근, 술 맡은 관원장이었습니다.","왕이 얼굴에 수색이 있다고 묻자, 느헤미야는 하늘의 하나님께 묵도하고 성을 다시 쌓게 보내 달라고 청합니다.","왕과 왕후가 기댄 상 앞에, 느헤미야가 그릇을 받쳐 들고 서 있습니다."],"audio":"audio/a1b731703ca5.mp3","times":[0.3,10.494,17.424,26.634],"dur":33.078},{"act":9,"id":"nehemiah-ruins","img":"img/nehemiah-ruins.webp","size":[1248,1600],"title":"폐허를 보는 느헤미야","artist":"제임스 티소","year":"1904","museum":"","credit":"After James Tissot (painted by Michel Simonidy), Nehemiah Sees the Ruins of Jerusalem (photo: Phillip Medhurst)","license":"CC BY-SA 4.0","page":"https://commons.wikimedia.org/wiki/File:345.3_402_N%C3%A9h%C3%A9mie_voit_les_ruines_de_J%C3%A9rusalem_(Nehemiah_2_17)_%E2%80%A2_invenit_James_Tissot_%E2%80%A2_pinxit_Michel_Simonidy_%E2%80%A2_excudit_Maurice_de_Brunoff_apud_Philip_de_Vere_%E2%80%A2_praesentat_Phillip_Medhurst.jpg","verse":"느헤미야 2장","lecture":"nehemiah","lectureTitle":"느헤미야","youtube":"1zccD52liyA","text":["느헤미야는 여행의 피로가 풀리기도 전에, 한 번도 본 적 없는 현장을 밤에 답사합니다.","그림 속 느헤미야는 말 위에서, 무너진 성의 잔해를 내려다보고 있습니다.","산발랏과 도비야의 살해 위협 속에서도, 느헤미야는 꿋꿋하게 일을 해 나갑니다.","8장에서는 에스라가 수문 앞 광장에서 새벽부터 정오까지 율법책을 읽고, 백성들은 죄를 깨닫고 회개합니다."],"audio":"audio/e1887881fba4.mp3","times":[0.3,7.854,14.352,21.642],"dur":30.966},{"act":9,"id":"malachi-cole","img":"img/malachi-cole.webp","size":[1600,995],"title":"제국의 행로 · 황폐","artist":"토머스 콜","year":"1836","museum":"","credit":"Thomas Cole, The Course of Empire: Desolation","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Cole_Thomas_The_Course_of_Empire_Desolation_1836.jpg","verse":"말라기 1장","lecture":"malachi","lectureTitle":"말라기","youtube":"3T3748PYXNE","text":["그러나 에스라와 느헤미야가 죽고 나니, 이스라엘 사람들의 신앙은 형식주의로 빠져 엉망이 되어 버렸습니다.","말라기의 역사적 배경은, 한마디로 하나님께서 완전히 지쳐 버리셨다는 것입니다.","모세부터 말라기까지, 천 년의 사랑이 물거품이 되어 버린 것입니다.","무너진 도시에는 기둥 하나만 우뚝 남았고, 달빛 아래 물은 고요합니다."],"audio":"audio/3bff1aa823c8.mp3","times":[0.3,9.27,16.68,22.89],"dur":29.622},{"act":9,"id":"malachi-debray","img":"img/malachi-debray.webp","size":[1600,1424],"title":"다윗과 레위인들","artist":"얀 더브라이","year":"","museum":"헤르초크 안톤 울리히 미술관","credit":"Jan de Bray, David Playing the Harp with Priests and Levites (Herzog Anton Ulrich-Museum; photo: Dguendel)","license":"CC BY 3.0","page":"https://commons.wikimedia.org/wiki/File:Herzog_Anton_Ulrich-Museum,_Jan_de_Bray,_David_Harfe_spielend_mit_Priester_und_Leviten.jpg","verse":"말라기 1장","lecture":"malachi","lectureTitle":"말라기","youtube":"3T3748PYXNE","text":["내가 너희를 사랑하였노라 하시자, 백성들은 주께서 어떻게 우리를 사랑하셨나이까 하고 되묻습니다.","제사장들은 눈먼 것, 저는 것, 병든 것을 제물로 드리고도, 우리가 어떻게 주를 더럽혔나이까 하고 꼬박꼬박 말대꾸합니다.","그림 속 하프를 타는 다윗 곁에, 가슴에 흉패를 단 제사장과 레위인들이 모여 있습니다.","원래 제사장들의 입에는 진리의 법이 있었는데, 타락하더니 많은 사람을 율법에서 떠나게 합니다."],"audio":"audio/d4dcf2d3b0fc.mp3","times":[0.3,8.694,19.632,27.042],"dur":34.998},{"act":9,"id":"malachi-sunrise","img":"img/malachi-sunrise.webp","size":[1600,1014],"title":"스쿠딕 반도의 일출","artist":"프레더릭 에드윈 처치","year":"1850–1855","museum":"","credit":"Frederic Edwin Church, Schoodic Peninsula from Mount Desert at Sunrise","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Frederic_Edwin_Church_-_Schoodic_Peninsula_from_Mount_Desert_at_Sunrise_-_Google_Art_Project.jpg","verse":"말라기 4장","lecture":"malachi","lectureTitle":"말라기","youtube":"3T3748PYXNE","text":["4장, 심판 날에 용광로 같은 불이 오지만, 경외하는 사람에게는 치료하는 광선이 비칩니다.","여호와의 크고 두려운 날이 이르기 전에 선지 엘리야를 보내리니, 이 말씀으로 구약이 끝나 버립니다.","붉은 구름 아래, 어두운 바다 너머로 해가 떠오르고 있습니다.","세례 요한이 나타나 회개하라고 할 때까지, 하나님께서는 400년을 침묵하십니다."],"audio":"audio/b2c4091bc06b.mp3","times":[0.3,8.622,16.92,22.674],"dur":29.646},{"act":10,"id":"matthew-jordaens","img":"img/matthew-jordaens.webp","size":[1396,1600],"title":"네 복음서 기자","artist":"야코프 요르단스","year":"1620년경","museum":"","credit":"Jacob Jordaens, The Four Evangelists","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Jakob_Jordaens_002.jpg","verse":"마태복음 1:1","lecture":"matthew","lectureTitle":"신약 파노라마 · 마태복음","youtube":"39g6DZ63Tl0","text":["말라기 뒤 400년의 침묵이 끝나고, 신약 성경은 마태, 마가, 누가, 요한, 4복음서로 문을 엽니다.","네 권의 복음서는 모두 한 가지, 예수님이 누구신가를 다룹니다.","그림 속 네 사람은 머리를 맞대고 함께 책을 들여다봅니다."],"audio":"audio/d02a238a94ad.mp3","times":[0.3,10.35,16.68],"dur":22.164},{"act":10,"id":"matthew-magi","img":"img/matthew-magi.webp","size":[1600,1114],"title":"동방박사들의 여행","artist":"제임스 티소","year":"1894년경","museum":"","credit":"James Tissot, The Journey of the Magi","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:James_Tissot_-_Journey_of_the_Magi_-_70.21_-_Minneapolis_Institute_of_Arts.jpg","verse":"마태복음 2장","lecture":"matthew","lectureTitle":"신약 파노라마 · 마태복음","youtube":"39g6DZ63Tl0","text":["마태복음은 유대인을 향한 복음이어서, 아브라함과 다윗의 자손이라는 족보로 1장이 시작합니다.","다윗의 동네 베들레헴에서 다윗의 자손으로 나신, 유대인의 왕으로 오신 메시아입니다.","동방박사들이 낙타를 타고 메마른 골짜기를 지나 그 왕을 찾아갑니다."],"audio":"audio/2b6d728fa653.mp3","times":[0.3,8.91,16.56],"dur":23.124},{"act":10,"id":"matthew-calling","img":"img/matthew-calling.webp","size":[1557,1600],"title":"성 마태의 부르심","artist":"카라바조","year":"1599–1600년경","museum":"","credit":"Caravaggio, The Calling of Saint Matthew","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:The_Calling_of_Saint_Matthew-Caravaggo_(1599-1600).jpg","verse":"마태복음 9장","lecture":"matthew","lectureTitle":"신약 파노라마 · 마태복음","youtube":"39g6DZ63Tl0","text":["나는 죄인을 부르러 왔다, 의원은 환자에게나 필요한 것이다, 죄인을 불러 회개하게 하시는 메시아의 말씀입니다.","그림 속 세리들의 탁자로 빛이 비스듬히 들어오고, 오른쪽에 선 예수님이 손을 뻗어 가리키십니다.","마태는 자기 이야기를 하나도 쓰지 않았지만, 제자들을 소개할 때 자기 이름 앞에만 세리 마태라고 적었습니다."],"audio":"audio/31ad60346bca.mp3","times":[0.3,9.726,18.096],"dur":26.964},{"act":10,"id":"matthew-sermon","img":"img/matthew-sermon.webp","size":[1600,1175],"title":"산상 설교","artist":"얀 브뤼헐 1세","year":"1598","museum":"","credit":"Jan Brueghel the Elder, The Sermon on the Mount","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Jan_Brueghel_the_Elder_-_The_Sermon_on_the_Mount_-_Google_Art_Project.jpg","verse":"마태복음 5장","lecture":"matthew","lectureTitle":"신약 파노라마 · 마태복음","youtube":"39g6DZ63Tl0","text":["예수님은 바리새인들처럼 교훈에 교훈을, 해석에 해석을 덧붙이지 않고, 진리 그 자체를 말씀하셨습니다.","유대인들은 강대국의 손아귀에서 건져 줄 메시아를 기다렸지만, 마태가 본 예수님은 죄에서 구원하시는 메시아였습니다.","큰 나무들 아래로 수많은 사람이 모여 말씀을 듣습니다."],"audio":"audio/8e3df6749ae1.mp3","times":[0.3,9.486,19.104],"dur":24.06},{"act":10,"id":"matthew-entry","img":"img/matthew-entry.webp","size":[1600,1423],"title":"예루살렘 입성","artist":"조토 디본도네","year":"1305","museum":"스크로베니 예배당","credit":"Giotto, Entry into Jerusalem (Scrovegni Chapel)","license":"CC0","page":"https://commons.wikimedia.org/wiki/File:Hristov_ulazak_u_jerusalim.png","verse":"마태복음 21장","lecture":"matthew","lectureTitle":"신약 파노라마 · 마태복음","youtube":"39g6DZ63Tl0","text":["변화산에서 참모습을 한 번 보여 주신 예수님은, 스가랴 9장 9절 말씀대로 나귀를 타고 유대인의 왕으로 들어가십니다.","그림 속 사람들은 나귀 앞 길에 겉옷을 펴고, 나무 위에 오른 사람들은 가지를 꺾습니다.","그리고 성전을 숙청하시고, 최후의 만찬과 십자가와 부활을 지나 마지막 유언인 지상명령을 맡기십니다."],"audio":"audio/deac88d896d7.mp3","times":[0.3,9.966,17.928],"dur":26.844},{"act":10,"id":"mark-baptist","img":"img/mark-baptist.webp","size":[1600,951],"title":"세례 요한의 설교","artist":"피터르 브뤼헐 1세","year":"1566","museum":"","credit":"Pieter Bruegel the Elder, The Sermon of Saint John the Baptist","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Pieter_Bruegel_the_Elder_-_The_Sermon_of_Saint_John_the_Baptist_-_Google_Art_Project.jpg","verse":"마가복음 1장","lecture":"mark","lectureTitle":"마가복음","youtube":"4z9JBR6PE-w","text":["마가복음은 마태복음과 내용이 90퍼센트 넘게 같고, 4복음서 가운데 가장 먼저 쓰였다고 보는 복음서입니다.","헬라인에게 사역한 마가가 써서 족보는 빠지고, 세례 요한이 그리스도를 준비하는 이야기부터 나옵니다.","숲속에 빽빽이 모인 사람들은, 400년의 침묵을 깨고 들려온 회개하라는 외침을 듣고 있습니다."],"audio":"audio/05f14d8d6553.mp3","times":[0.3,9.942,18.216],"dur":25.86},{"act":10,"id":"mark-keys","img":"img/mark-keys.webp","size":[1600,991],"title":"베드로에게 열쇠를 주심","artist":"피에트로 페루지노","year":"1481–1482","museum":"시스티나 예배당","credit":"Pietro Perugino, Christ Giving the Keys to Saint Peter (Sistine Chapel)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Perugino_-_Entrega_de_las_llaves_a_San_Pedro_(Capilla_Sixtina,_1481-82).jpg","verse":"마가복음 8:29","lecture":"mark","lectureTitle":"마가복음","youtube":"4z9JBR6PE-w","text":["병든 사람과 귀신 들린 사람을 고치시고 칠병이어로 4천 명을 먹이신 뒤, 베드로의 신앙고백이 나옵니다.","주는 그리스도시요, 살아 계신 하나님의 아들이시니이다.","그림 속 넓은 광장 한가운데서, 무릎 꿇은 베드로가 예수님께 열쇠를 받습니다."],"audio":"audio/4efd4d832172.mp3","times":[0.3,9.678,15.288],"dur":22.356},{"act":10,"id":"mark-bartimaeus","img":"img/mark-bartimaeus.webp","size":[1130,1600],"title":"눈먼 바디메오를 고치심","artist":"페르난도 갈레고 공방","year":"","museum":"애리조나 대학교 미술관","credit":"Workshop of Fernando Gallego, The Healing of Blind Bartimaeus (University of Arizona Museum of Art)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:The_Healing_of_Blind_Bartimaeus_by_Fernando_Gallego_workshop,_1480-1488,_oil_on_panel_-_University_of_Arizona_Museum_of_Art_-_University_of_Arizona_-_Tucson,_AZ_-_DSC08346.jpg","verse":"마가복음 10장","lecture":"mark","lectureTitle":"마가복음","youtube":"4z9JBR6PE-w","text":["예루살렘으로 올라가시는 길에, 예수님은 바디메오를 만나십니다.","예수님이 바디메오의 눈에 손을 대시고, 제자들이 둘러서서 지켜봅니다.","그리고 수난을 여러 번 미리 예고하시는데, 아무 말씀 없이 당하시면 불의의 사고로 오해할 수 있기 때문입니다."],"audio":"audio/8161af21caf5.mp3","times":[0.3,6.486,12.912],"dur":21.66},{"act":10,"id":"mark-supper","img":"img/mark-supper.webp","size":[1600,1132],"title":"최후의 만찬","artist":"바스쿠 페르난드스","year":"1535","museum":"","credit":"Vasco Fernandes (Grão Vasco), The Last Supper","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Last_supper_-_Vasco_Fernandes.jpg","verse":"마가복음 14장","lecture":"mark","lectureTitle":"마가복음","youtube":"4z9JBR6PE-w","text":["예루살렘에 들어가 성전을 숙청하신 뒤, 마지막 한 주간의 가르침이 이어집니다.","크고 첫째 가는 계명은 하나님 사랑, 이웃 사랑입니다.","그림 속 예수님은 한가운데서 빵을 들어 축복하시고, 한 제자는 그 곁에 기대어 고개를 묻었습니다."],"audio":"audio/bc274b14443e.mp3","times":[0.3,7.23,12.816],"dur":21.18},{"act":10,"id":"mark-tomb","img":"img/mark-tomb.webp","size":[1600,1328],"title":"그리스도의 무덤을 찾은 여인들","artist":"안니발레 카라치","year":"","museum":"에르미타주 미술관","credit":"Annibale Carracci, The Holy Women at Christ's Tomb (Hermitage Museum)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Annibale_Carracci_-_Holy_Women_at_Christ%27_s_Tomb_-_WGA4454.jpg","verse":"마가복음 16장","lecture":"mark","lectureTitle":"마가복음","youtube":"4z9JBR6PE-w","text":["최후의 만찬, 그리고 그리스도의 수난과 부활, 승천으로 마가복음이 끝납니다.","무덤을 찾아온 여인들 앞에서, 돌 위에 앉은 천사가 무덤 안을 가리킵니다."],"audio":"audio/f73ad68b60d7.mp3","times":[0.3,8.19],"dur":15.138},{"act":10,"id":"luke-shepherds","img":"img/luke-shepherds.webp","size":[1600,1315],"title":"목자들의 경배","artist":"헤라르트 판혼트호르스트","year":"1622","museum":"","credit":"Gerard van Honthorst, Adoration of the Shepherds","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Gerard_van_Honthorst_-_Adoration_of_the_Shepherds_(1622).jpg","verse":"누가복음 2장","lecture":"luke","lectureTitle":"누가복음","youtube":"misPj99kL_w","text":["의사이자 역사가였다고 전해지는 이방인 누가는, 모든 일을 근원부터 자세히 살펴 차례대로 썼습니다.","마태복음에는 동방박사들만 경배한 것으로 나오는데, 누가가 알아보니 목자들도 경배했습니다.","그림 속 구유의 아기에게서 나온 빛이, 둘러선 목자들의 얼굴을 환하게 비춥니다."],"audio":"audio/86f470f7a0d4.mp3","times":[0.3,9.15,17.448],"dur":24.564},{"act":10,"id":"luke-synagogue","img":"img/luke-synagogue.webp","size":[564,768],"title":"회당에서 두루마리를 펴신 예수","artist":"제임스 티소","year":"1886–1894","museum":"브루클린 미술관","credit":"James Tissot, Jesus Unrolls the Book in the Synagogue (Brooklyn Museum)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Brooklyn_Museum_-_Jesus_Unrolls_the_Book_in_the_Synagogue_(J%C3%A9sus_dans_la_synagogue_d%C3%A9roule_le_livre)_-_James_Tissot_-_overall.jpg","verse":"누가복음 4장","lecture":"luke","lectureTitle":"누가복음","youtube":"misPj99kL_w","text":["예수님의 첫 설교는 산상수훈이 아니라, 나사렛 회당에서 이사야서 61장을 본문으로 한 은혜의 해였습니다.","흰 겉옷을 두른 회당 사람들 앞에서, 예수님이 두루마리를 펴십니다.","사람들 비위를 맞추지 않은 그 설교로, 예수님은 성난 사람들에게 죽을 뻔하셨습니다."],"audio":"audio/8f8d449c0b29.mp3","times":[0.3,9.582,16.032],"dur":23.676},{"act":10,"id":"luke-prodigal","img":"img/luke-prodigal.webp","size":[1226,1600],"title":"탕자의 귀향","artist":"렘브란트 판레인","year":"1668년경","museum":"에르미타주 미술관","credit":"Rembrandt, The Return of the Prodigal Son (Hermitage Museum)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Rembrandt_Harmensz_van_Rijn_-_Return_of_the_Prodigal_Son_-_Google_Art_Project.jpg","verse":"누가복음 15장","lecture":"luke","lectureTitle":"누가복음","youtube":"misPj99kL_w","text":["누가는 사마리아인, 세리, 창녀, 가난한 사람, 병든 사람에게 관심이 많습니다.","탕자의 비유에서 진짜 탕자는 돌아온 아들이 아니라, 집 안에 있으면서 돌아온 아들을 질투하는 아들입니다.","그림 속 아버지는 무릎 꿇은 아들을 감싸 안고, 오른쪽의 큰아들은 꼿꼿이 서서 내려다봅니다."],"audio":"audio/d7ab88f3e91e.mp3","times":[0.3,8.982,17.568],"dur":25.572},{"act":10,"id":"luke-ascension","img":"img/luke-ascension.webp","size":[1431,1600],"title":"승천","artist":"존 싱글턴 코플리","year":"1775","museum":"","credit":"John Singleton Copley, The Ascension","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Jesus_ascending_to_heaven.jpg","verse":"누가복음 24장","lecture":"luke","lectureTitle":"누가복음","youtube":"misPj99kL_w","text":["엠마오로 가는 두 제자, 그리고 부활하신 주님이 하늘로 올라가시는 이야기는 누가만 쓰고 있습니다.","제자들은 구름 속으로 오르시는 주님을 올려다보며 손을 듭니다.","서른 가지가 넘는 이야기를 보탰는데도, 누가복음은 24장으로 오히려 마태복음보다 짧습니다."],"audio":"audio/64c8f96064bf.mp3","times":[0.3,8.334,14.112],"dur":22.212},{"act":10,"id":"john-sinai","img":"img/john-sinai.webp","size":[886,1600],"title":"그리스도 판토크라토르","artist":"작자 미상","year":"6세기","museum":"시나이 성 카타리나 수도원","credit":"Christ Pantocrator, icon, 6th century (Saint Catherine's Monastery, Sinai)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:CHRIST_PANTOCRATOR-SINAI(6th_Century).jpg","verse":"요한복음 1:14","lecture":"john","lectureTitle":"요한복음","youtube":"fP2eZUkrdQs","text":["요한복음은 사도들이 모두 순교하고 요한만 남아 있던 기원후 90년쯤, 신약 가운데 가장 마지막에 쓰인 문서들 가운데 하나입니다.","태초에 말씀이 계시니라, 그리고 1장 14절, 말씀이 육신이 되어 우리 가운데 거하시매.","그림 속 예수님은 한 손에 책을 들고, 정면에서 보는 이를 똑바로 바라보십니다."],"audio":"audio/abcc60a9a144.mp3","times":[0.3,11.214,19.56],"dur":26.652},{"act":10,"id":"john-thomas","img":"img/john-thomas.webp","size":[1382,1500],"title":"도마의 의심","artist":"두초 디부오닌세냐","year":"1308–1311","museum":"시에나","credit":"Duccio di Buoninsegna, The Incredulity of Saint Thomas, Maestà (Siena)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:The-Maesta-Altarpiece-The-Incredulity-of-Saint-Thomas-1461_Duccio.jpg","verse":"요한복음 20:28","lecture":"john","lectureTitle":"요한복음","youtube":"fP2eZUkrdQs","text":["요한은 예수님이 그저 능력 많은 예언자가 아니라, 하나님의 신성이 통째로 계신 분이라고 말합니다.","도마가 제자들 사이에서 손을 뻗어, 예수님 옆구리의 상처에 손가락을 댑니다.","믿음 없는 자가 되지 말고 믿는 자가 되라는 말씀에, 도마는 바로 고백합니다, 나의 주 나의 하나님이십니다."],"audio":"audio/b49e2daacdff.mp3","times":[0.3,8.598,15.624],"dur":24.924},{"act":10,"id":"john-lazarus","img":"img/john-lazarus.webp","size":[1600,1485],"title":"나사로를 살리심","artist":"조토 디본도네","year":"1304–1306","museum":"파도바 스크로베니 예배당","credit":"Giotto, The Raising of Lazarus (Scrovegni Chapel, Padua)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Giotto_di_Bondone_021.jpg","verse":"요한복음 11장","lecture":"john","lectureTitle":"요한복음","youtube":"fP2eZUkrdQs","text":["요한이 기록한 일곱 가지 이적은 질과 양, 공간과 시간, 자연 법칙과 운명을 넘어섭니다.","그 마지막이 죽은 나사로를 살리신 일로, 그림 속 나사로는 수의에 싸인 채 무덤 앞에 서 있습니다.","이 모든 것을 초월하시는 분이라면, 우리는 이분을 어떤 분으로 믿어야 할까요?"],"audio":"audio/13460a0feb0f.mp3","times":[0.3,9.078,17.28],"dur":23.94},{"act":10,"id":"john-evangelists","img":"img/john-evangelists.webp","size":[1212,1600],"title":"켈스의 서 · 네 복음서 기자의 상징","artist":"작자 미상","year":"","museum":"더블린 트리니티 칼리지","credit":"Book of Kells, folio 27v, symbols of the four evangelists (Trinity College Dublin)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:KellsFol027v4Evang.jpg","verse":"요한복음 21:25","lecture":"john","lectureTitle":"요한복음","youtube":"fP2eZUkrdQs","text":["예수님의 일을 낱낱이 기록하면 이 세상이라도 그 책을 두기에 부족하다, 21장 25절입니다.","그래도 복음서 네 권이면 예수님이 누구신지 다 알 수 있다고 보신 것입니다.","네 칸에는 네 복음서 기자를 나타내는 상징이 하나씩 그려져 있습니다."],"audio":"audio/9ba546b9d937.mp3","times":[0.3,8.982,15.648],"dur":21.804},{"act":11,"id":"acts-1-elgreco","img":"img/acts-1-elgreco.webp","size":[737,1600],"title":"오순절","artist":"엘 그레코","year":"1600년경","museum":"프라도 미술관","credit":"El Greco, Pentecost (Museo del Prado)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Pentecost%C3%A9s_(El_Greco,_c._1600)_Prado.jpg","verse":"사도행전 2장","lecture":"acts-1","lectureTitle":"사도행전 1~12장","youtube":"i4JH792iako","text":["승천하시며 예수님이 남기신 말씀이 있습니다.","성령이 너희에게 임하시면, 예루살렘과 온 유대와 사마리아와 땅 끝까지 내 증인이 되리라.","오순절 날, 급하고 강한 바람 같은 소리와 함께 불의 혀같이 갈라진 것이 사람들 위에 하나씩 내려앉습니다.","그림 속 사람들의 머리 위마다 작은 불꽃이 타오르고, 맨 위에서는 비둘기가 빛을 내립니다."],"audio":"audio/0aec4c219e10.mp3","times":[0.3,4.95,13.104,22.722],"dur":30.966},{"act":11,"id":"acts-1-stoning","img":"img/acts-1-stoning.webp","size":[1000,1103],"title":"스데반의 순교","artist":"프라 안젤리코","year":"1447–1449","museum":"바티칸 니콜리나 예배당","credit":"Fra Angelico, The Stoning of Saint Stephen, Niccoline Chapel (Vatican)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Angelico,_niccolina_24.jpg","verse":"사도행전 7장","lecture":"acts-1","lectureTitle":"사도행전 1~12장","youtube":"i4JH792iako","text":["일곱 집사 가운데 한 사람인 스데반은, 공회 앞에서 7장 전체에 걸친 역사 설교를 합니다.","말로는 이길 수 없던 사람들은 귀를 막고 달려들어, 그를 돌로 쳐 죽입니다.","무릎을 꿇은 스데반은, 죽어 가면서도 예수님처럼 이 사람들의 죄를 용서해 달라고 기도합니다."],"audio":"audio/b8035fa7a3ff.mp3","times":[0.3,8.286,15.624],"dur":23.532},{"act":11,"id":"acts-1-damascus","img":"img/acts-1-damascus.webp","size":[1218,1600],"title":"다메섹으로 가는 길의 회심","artist":"카라바조","year":"1600–1601년경","museum":"로마 산타 마리아 델 포폴로 성당","credit":"Caravaggio, The Conversion on the Way to Damascus (Santa Maria del Popolo, Rome)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Conversion_on_the_Way_to_Damascus-Caravaggio_(c.1600-1).jpg","verse":"사도행전 9장","lecture":"acts-1","lectureTitle":"사도행전 1~12장","youtube":"i4JH792iako","text":["인류 역사에서 가장 영향력이 컸던 회심이 9장에서 일어납니다.","교회를 핍박하러 다메섹으로 가던 사울은, 환한 빛에 눈이 멀어 땅에 쓰러집니다.","그림 속 사울은 말 아래 두 팔을 벌리고 누워, 쏟아지는 빛을 온몸으로 받고 있습니다."],"audio":"audio/c6d64e5cb79d.mp3","times":[0.3,6.414,13.488],"dur":21.06},{"act":11,"id":"acts-1-centurion","img":"img/acts-1-centurion.webp","size":[1600,1028],"title":"베드로와 고넬료","artist":"토머스 찰스 바필드","year":"1917","museum":"","credit":"Thomas Charles Barfield, Saint Peter and the Centurion (1917)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Thomas_Charles_Barfield.St._Peter_%26_Centurion.Watercolour_on_card,59.7cm_x_40cm.1917.jpg","verse":"사도행전 10장","lecture":"acts-1","lectureTitle":"사도행전 1~12장","youtube":"i4JH792iako","text":["10장, 하나님은 베드로에게 환상을 보여 주셔서, 이방인을 짐승처럼 보던 유대인의 눈을 고쳐 주십니다.","고넬료에게도 환상을 보여 주셔서 베드로를 초대하게 하시고, 베드로가 설교하는 도중에 그 이방인들에게 성령이 내려오십니다.","갑옷 입은 고넬료가 무릎을 꿇고 베드로의 손을 잡습니다."],"audio":"audio/394666b983ff.mp3","times":[0.3,9.39,19.488],"dur":25.068},{"act":11,"id":"acts-13-francken","img":"img/acts-13-francken.webp","size":[740,1600],"title":"성령이 따로 세우신 바울과 바나바","artist":"암브로시우스 프랑컨 1세","year":"1573–1618","museum":"안트베르펜 왕립미술관","credit":"Ambrosius Francken I, Paul and Barnabas Chosen as Apostles by the Holy Spirit (Royal Museum of Fine Arts Antwerp)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Ambrosius_Francken_I_-_Paulus_en_Barnabas_van_Cyprus_door_de_heilige_Geest_tot_apostelen_uitverkoren_-_139_-_Royal_Museum_of_Fine_Arts_Antwerp.tiff","verse":"사도행전 13:2","lecture":"acts-13","lectureTitle":"사도행전 13장~18:11","youtube":"Ev6KjJhrbfc","text":["13장, 안디옥 교회가 주를 섬겨 금식할 때 성령께서 말씀하십니다.","바나바와 사울을 따로 세우라.","그림 속 사람들은 한 줄기 빛이 내려오는 쪽을 올려다보고, 두 사람은 성령이 보내셔서 길을 떠납니다."],"audio":"audio/6adb84638a8e.mp3","times":[0.3,7.47,11.064],"dur":19.548},{"act":11,"id":"acts-13-lydia","img":"img/acts-13-lydia.webp","size":[1600,1173],"title":"루디아의 세례","artist":"마리 엘렌리더","year":"1861","museum":"","credit":"Marie Ellenrieder, The Baptism of Lydia (1861)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:1861_Ellenrieder_Die_Taufe_der_Lydia_anagoria.JPG","verse":"사도행전 16장","lecture":"acts-13","lectureTitle":"사도행전 13장~18:11","youtube":"Ev6KjJhrbfc","text":["드로아에서 마게도냐 사람의 환상을 본 바울은 바다를 건너고, 복음이 유럽으로 전해집니다.","빌립보에서 만난 자색 옷감 장사 루디아는, 나중에 바울 선교팀의 든든한 재정 후원자가 됩니다.","붉은 옷의 루디아가 무릎을 꿇고 세례를 받습니다."],"audio":"audio/0a68c8724271.mp3","times":[0.3,8.214,16.56],"dur":21.636},{"act":11,"id":"acts-13-valentin","img":"img/acts-13-valentin.webp","size":[1600,1177],"title":"서신을 쓰는 사도 바울","artist":"발랑탱 드 불로뉴","year":"1618–1620년경","museum":"휴스턴 미술관","credit":"Valentin de Boulogne, Saint Paul Writing His Epistles (Museum of Fine Arts, Houston)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Valentin_de_Boulogne_-_Saint_Paul_Writing_His_Epistles_-_BF.1991.4_-_Museum_of_Fine_Arts.jpg","verse":"사도행전 18:9","lecture":"acts-13","lectureTitle":"사도행전 13장~18:11","youtube":"Ev6KjJhrbfc","text":["고린도에서 조금 위축된 바울에게, 밤에 주께서 말씀하십니다.","두려워하지 말며 잠잠하지 말고 말하라, 내가 너와 함께 있으매.","그렇게 고린도에서 일 년 육 개월을 보내며, 그림 속 바울처럼 펜을 들어 데살로니가전후서와 갈라디아서를 써 보냅니다."],"audio":"audio/38cefed3d6de.mp3","times":[0.3,6.51,12.408],"dur":21.972},{"act":11,"id":"galatians-reni","img":"img/galatians-reni.webp","size":[1097,1600],"title":"베드로와 바울","artist":"귀도 레니","year":"1605년경","museum":"밀라노 브레라 미술관","credit":"Guido Reni, Saints Peter and Paul (Pinacoteca di Brera, Milan)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Guido_Reni_044.jpg","verse":"갈라디아서 2장","lecture":"galatians","lectureTitle":"갈라디아서","youtube":"HyuKFz1cs98","text":["갈라디아 교회들에는 할례를 받아 유대인이 되어야 구원을 받는다는 그릇된 복음이 들어왔습니다.","화가 난 바울은, 할례당이 들어오자 이방인과 먹던 자리를 피한 베드로의 외식을 꾸짖은 적도 있다고 씁니다.","바울은 손을 들어 말하고, 베드로는 턱을 괸 채 생각에 잠겨 있습니다."],"audio":"audio/0db6d1f8cb16.mp3","times":[0.3,7.998,16.92],"dur":23.316},{"act":11,"id":"acts-18-lesueur","img":"img/acts-18-lesueur.webp","size":[1000,1186],"title":"에베소에서 설교하는 바울","artist":"외스타슈 르쉬외르","year":"1649","museum":"루브르 박물관","credit":"Eustache Le Sueur, The Preaching of Saint Paul at Ephesus (Musée du Louvre)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Eustache_Le_Sueur_-_The_Preaching_of_St_Paul_at_Ephesus_-_WGA12613.jpg","verse":"사도행전 19장","lecture":"acts-18","lectureTitle":"사도행전 18:12~19:20","youtube":"HtmPenHCNvo","text":["삼차 전도여행에서 에베소에 온 바울은, 두란노 서원을 빌려 이 년 동안 가르칩니다.","아시아에 사는 사람들이 다 주의 말씀을 들었고, 사람들은 죄를 고백하며 마술 책을 가져다 불태웁니다.","그림 속 계단 아래에서도 책 더미가 타오르고, 결론은 하나님의 말씀이 흥왕하여 세력을 얻었다는 것입니다."],"audio":"audio/3917e846ce9e.mp3","times":[0.3,7.782,16.752],"dur":25.5},{"act":11,"id":"cor1-cymbals","img":"img/cor1-cymbals.webp","size":[818,1600],"title":"심벌즈를 든 천사","artist":"프라 안젤리코","year":"","museum":"","credit":"Fra Angelico, Angel with Cymbals, from the Linaioli Tabernacle, photo: Francesco Bini","license":"CC BY-SA 4.0","page":"https://commons.wikimedia.org/wiki/File:Beato_angelico,_tabernacolo_dei_linaioli,_1433-36,_07_angeli_musicanti_dx_2_cembali.jpg","verse":"고린도전서 13:1","lecture":"cor1","lectureTitle":"고린도전서","youtube":"TnzIav0s4GM","text":["그 에베소에서 바울은, 방언을 내세우며 다투는 고린도 교회에 편지를 씁니다.","사람의 방언과 천사의 말을 해도, 사랑이 없으면 꽹과리 소리라는 13장입니다.","천사가 든 이 심벌즈처럼 아름다운 소리라도, 이 사랑장은 너희에게 이런 사랑이 없다고 꾸짖는 말입니다."],"audio":"audio/49d4ac6f93d2.mp3","times":[0.3,7.302,14.664],"dur":23.532},{"act":11,"id":"romans-twilight","img":"img/romans-twilight.webp","size":[1600,997],"title":"황야의 황혼","artist":"프레더릭 에드윈 처치","year":"1860","museum":"클리블랜드 미술관","credit":"Frederic Edwin Church, Twilight in the Wilderness (Cleveland Museum of Art)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Frederic_Edwin_Church_-_Twilight_in_the_Wilderness.jpg","verse":"로마서 8:38-39","lecture":"romans","lectureTitle":"로마서","youtube":"eHw4rwE7_vQ","text":["헬라에서 석 달을 머물며 쓴 로마서는, 겐그레아 교회의 집사 뵈뵈의 손에 들려 로마로 갑니다.","내가 못 가더라도 복음은 가야 한다는 마음으로 쓴 편지입니다.","붉게 타는 저녁 하늘 아래, 8장은 어떤 피조물도 그리스도 예수 안에 있는 하나님의 사랑에서 우리를 끊을 수 없다고 고백합니다."],"audio":"audio/c501403e5d2f.mp3","times":[0.3,8.358,14.136],"dur":24.228},{"act":11,"id":"acts-20-cherondetail","img":"img/acts-20-cherondetail.webp","size":[1200,1600],"title":"바울의 고난을 예언하는 아가보 (부분)","artist":"루이 셰롱","year":"","museum":"","credit":"Louis Chéron, The Prophet Agabus Foretelling Saint Paul's Sufferings in Jerusalem (detail), photo: GO69","license":"CC BY 4.0","page":"https://commons.wikimedia.org/wiki/File:Louis_Ch%C3%A9ron_-_Le_proph%C3%A8te_Agabus_pr%C3%A9disant_%C3%A0_saint_Paul_ses_souffrances_%C3%A0_J%C3%A9rusalem_-_02.jpg","verse":"사도행전 21:13","lecture":"acts-20","lectureTitle":"사도행전 20:4~28장","youtube":"DMNonQD3EWg","text":["연보를 들고 예루살렘으로 가는 길에, 선지자 아가보가 바울의 띠로 자기 손발을 묶고 이 띠의 주인이 결박될 것이라고 말합니다.","두 손에 얼굴을 묻은 젊은이 곁에서, 제자들은 울며 바울이 예루살렘에 가는 것을 말립니다.","그러나 바울은 대답합니다, 어찌하여 울어서 내 마음을 상하게 하느냐, 나는 주 예수의 이름을 위하여 결박당할 뿐 아니라 예루살렘에서 죽을 것도 각오했다."],"audio":"audio/4ff4832665fc.mp3","times":[0.3,10.326,18.24],"dur":30.684},{"act":11,"id":"acts-20-bloemaert","img":"img/acts-20-bloemaert.webp","size":[1600,1223],"title":"바울과 아그립바 왕","artist":"헨드릭 블루마르트","year":"1635","museum":"위트레흐트 중앙박물관","credit":"Hendrick Bloemaert, Paul and King Agrippa (Centraal Museum, Utrecht)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Paul_and_King_Agrippa_by_Hendrick_Bloemaert_Centraal_Museum_2570.jpg","verse":"사도행전 26장","lecture":"acts-20","lectureTitle":"사도행전 20:4~28장","youtube":"DMNonQD3EWg","text":["예루살렘 성전에서 붙잡혀 가이사랴 감옥에서 이 년을 보낸 바울은, 가이사에게 상소하겠다며 로마로 보내 달라고 합니다.","그림 속 바울은 아그립바 왕과 버니게 앞에 서서, 손을 들어 다시 한번 연설합니다.","왕은 네가 나를 전도하려는 것이냐고 묻지만, 바울의 목적은 로마에 가는 것이었습니다."],"audio":"audio/dfe20050d32b.mp3","times":[0.3,10.134,17.616],"dur":25.14},{"act":11,"id":"acts-20-ninthwave","img":"img/acts-20-ninthwave.webp","size":[1600,1057],"title":"아홉 번째 파도","artist":"이반 아이바좁스키","year":"1850","museum":"상트페테르부르크 러시아 국립미술관","credit":"Ivan Aivazovsky, The Ninth Wave (State Russian Museum, Saint Petersburg)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Aivazovsky,_Ivan_-_The_Ninth_Wave.jpg","verse":"사도행전 27장","lecture":"acts-20","lectureTitle":"사도행전 20:4~28장","youtube":"DMNonQD3EWg","text":["죄수 바울을 태운 배는 유라굴로라는 미친 듯한 바람을 만나 바다로 밀려 나가고, 276명 모두가 기진맥진합니다.","부서진 돛대에 매달린 이 사람들 같은 처지였지만, 가이사 앞에 서리라는 약속을 받은 바울은 담대했습니다."],"audio":"audio/7a6f77aa25ae.mp3","times":[0.3,10.254],"dur":18.978},{"act":11,"id":"acts-20-catel","img":"img/acts-20-catel.webp","size":[1600,1154],"title":"아피아 가도","artist":"프란츠 루트비히 카텔","year":"1833","museum":"","credit":"Franz Ludwig Catel, Via Appia","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Franz_Ludwig_Catel_-_Via_Appia_(1833).jpg","verse":"사도행전 28장","lecture":"acts-20","lectureTitle":"사도행전 20:4~28장","youtube":"DMNonQD3EWg","text":["배는 깨졌지만 사람들은 모두 멜리데 섬에 닿아 살았고, 석 달 뒤 바울은 마침내 로마로 갑니다.","로마의 그리스도인들이 압비오 광장과 세 여관까지 마중을 나오고, 바울은 하나님께 감사하며 담대한 마음을 얻습니다.","그림 속 옛길이 들판을 가로질러 멀리 뻗어 있듯, 예루살렘에서 시작한 복음이 로마에 이르렀습니다."],"audio":"audio/fa5c295a07e9.mp3","times":[0.3,8.814,18.6],"dur":26.772},{"act":11,"id":"philemon-strozzi","img":"img/philemon-strozzi.webp","size":[1277,1600],"title":"사도 바울","artist":"베르나르도 스트로치","year":"1625년경","museum":"","credit":"Bernardo Strozzi, Saint Paul","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Bernardo_Strozzi_-_Saint_Paul.jpg","verse":"빌레몬서 1:16","lecture":"philemon","lectureTitle":"빌레몬서","youtube":"cQn2rhVrEH4","text":["로마의 셋집에 갇혀 지낸 이 년 동안, 바울은 에베소서, 골로새서, 빌레몬서, 빌립보서를 씁니다.","주인의 돈을 빼내 로마로 도망쳤다가 바울을 만나 거듭난 노예 오네시모를, 바울은 주인 빌레몬에게 돌려보냅니다.","하늘을 올려다보는 바울은, 편지에 이제부터 종이 아니라 사랑받는 형제로 대하라고 씁니다."],"audio":"audio/2ff21927208c.mp3","times":[0.3,9.894,19.512],"dur":27.18},{"act":11,"id":"last-journey-rembrandt","img":"img/last-journey-rembrandt.webp","size":[1315,1600],"title":"감옥의 사도 바울","artist":"렘브란트 판레인","year":"1627","museum":"슈투트가르트 국립미술관","credit":"Rembrandt, Saint Paul in Prison (Staatsgalerie Stuttgart)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Rembrandt_St._Paul_in_Prison.jpg","verse":"디모데후서 4장","lecture":"last-journey","lectureTitle":"바울의 마지막 전도여행","youtube":"z6NoGgMNrLU","text":["풀려난 바울은 그레데와 에베소와 빌립보를 돌며, 교회마다 장로를 세우는 마지막 여행을 합니다.","그러나 다시 로마 감옥에 갇히는데, 이번에는 가택연금이 아니라 사형수 감옥인 마메틴 감옥입니다.","그림 속 바울은 감옥 창으로 드는 빛 아래 앉아, 턱을 괸 채 생각에 잠겨 있습니다.","이때 디모데후서를 쓰고, 바울은 순교합니다."],"audio":"audio/2e7f7713d349.mp3","times":[0.3,8.814,17.52,25.29],"dur":30.126},{"act":12,"id":"timothy1-drost","img":"img/timothy1-drost.webp","size":[1270,1600],"title":"디모데와 로이스","artist":"빌럼 드로스트","year":"","museum":"에르미타주 미술관","credit":"Willem Drost, Timothy and Lois (also called Anna the Prophetess and a Child) (Hermitage Museum)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Timothy-and-Lois.jpg","verse":"디모데전서 1:3","lecture":"timothy1","lectureTitle":"디모데전서","youtube":"paMyv5f7QGw","text":["바울이 남긴 마지막 편지들 가운데 디모데전서에서, 바울은 마게도냐로 가면서 디모데에게 에베소에 머물라고 합니다.","다른 교훈을 가르치지 못하게, 신화와 끝없는 족보에 마음 쓰지 못하게 하려는 것입니다.","그리고 편지 끝에 이렇게 당부합니다, 디모데야, 네게 부탁한 것을 지키라.","그림 속 어린 디모데는 나이 든 여인의 품에 가만히 기대어 있습니다."],"audio":"audio/a1875119be0c.mp3","times":[0.3,10.014,17.64,24.714],"dur":30.654},{"act":12,"id":"timothy1-bakhuizen","img":"img/timothy1-bakhuizen.webp","size":[1600,1088],"title":"바위 해안에서 조난한 배들","artist":"루돌프 바크하위젠","year":"1667","museum":"미국 국립미술관","credit":"Ludolf Backhuysen, Ships in Distress off a Rocky Coast (National Gallery of Art, Washington)","license":"CC0","page":"https://commons.wikimedia.org/wiki/File:Ludolf_Backhuysen,_Ships_in_Distress_off_a_Rocky_Coast,_1667,_NGA_65898.jpg","verse":"디모데전서 1:19","lecture":"timothy1","lectureTitle":"디모데전서","youtube":"paMyv5f7QGw","text":["바울은 디모데에게, 선한 싸움을 싸우며 믿음과 착한 양심을 가지라고 합니다.","그런데 이 양심을 버리고 믿음에 파선한 사람들이 있었습니다.","먹구름 아래 바위에 부딪힌 이 배들처럼, 믿음이 부서져 버린 것입니다."],"audio":"audio/1b52a2d85bfe.mp3","times":[0.3,7.446,13.224],"dur":19.596},{"act":12,"id":"titus-fresco","img":"img/titus-fresco.webp","size":[1133,1200],"title":"고르티나의 성 키릴로스와 성 디도","artist":"작자 미상","year":"13~15세기","museum":"","credit":"Fresco of Saints Kyrillos and Titus of Gortyna (13th–15th century), unknown painter","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Fresco_of_Saints_Titos_and_Kyrillos_of_Gortyna.jpg","verse":"디도서 1:5","lecture":"titus","lectureTitle":"디도서","youtube":"vcVP55jX3y4","text":["바울은 디도를 그레데에 남겨 두어, 부족한 일을 바로잡고 성마다 장로들을 세우게 합니다.","장로는 책망할 것이 없고, 미쁜 말씀의 가르침을 그대로 지키는 사람이어야 합니다.","고린도교회 문제를 해결했던 디도는, 악하고 게으르다는 그레데 같은 어려운 곳에 가서 일을 잘하는 사람이었습니다.","그림 속 오른쪽, 붉은 옷을 입고 금빛으로 꾸민 책을 든 감독이 디도입니다."],"audio":"audio/51a285b58248.mp3","times":[0.3,8.382,15.864,25.17],"dur":32.382},{"act":12,"id":"timothy2-friedrich","img":"img/timothy2-friedrich.webp","size":[1600,1283],"title":"해 질 녘 (형제들)","artist":"카스파르 다비트 프리드리히","year":"1837","museum":"에르미타주 미술관","credit":"Caspar David Friedrich, Sunset (Brothers) (Hermitage Museum)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Sunset_by_Caspar_David_Friedrich.jpg","verse":"디모데후서 4:2","lecture":"timothy2","lectureTitle":"디모데후서","youtube":"7Yk1TY2YL1o","text":["니고볼리를 지나 다시 갇힌 바울은, 사형수 감옥인 마메틴 감옥에서 디모데후서를 씁니다.","나갈 희망은 보이지 않고 디모데가 몹시도 보고 싶어서 쓴, 마지막 유언 같은 편지입니다.","너는 말씀을 전파하라, 때를 얻든지 못 얻든지 항상 힘쓰라고 당부한 뒤, 이제 순교할 때가 된 것 같다고 말합니다.","언덕에 나란히 선 두 사람이, 저물어 가는 해를 바라봅니다."],"audio":"audio/bd4868a9d528.mp3","times":[0.3,8.19,16.296,26.226],"dur":31.566},{"act":12,"id":"hebrews-highpriest","img":"img/hebrews-highpriest.webp","size":[1025,1600],"title":"위대한 대제사장 그리스도","artist":"미하일 다마스키노스","year":"1550–1593","museum":"","credit":"Michael Damaskinos, Christ the Great High Priest","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Christ_High_Priest_Michael_Damaskinos.png","verse":"히브리서 7장","lecture":"hebrews","lectureTitle":"히브리서","youtube":"nM--xhrZHU0","text":["히브리서는 누가 썼는지 아직 잘 모르는 편지입니다.","예수를 믿고 나왔다가 박해가 일어나자 다시 유대교로 돌아가 버린 사람들에게, 모든 면에서 그리스도가 낫다고 하나하나 비교해 보입니다.","계속 죽고 바뀌는 아론의 제사장들과 달리, 예수님은 멜기세덱의 반차를 좇는 영원한 대제사장이십니다.","그림 속 그리스도는 보석 박힌 관을 쓰고 제사장의 옷을 입은 채, 펼친 책을 들고 계십니다."],"audio":"audio/23ef18733e61.mp3","times":[0.3,5.646,16.344,25.458],"dur":33.75},{"act":12,"id":"hebrews-ruisdael","img":"img/hebrews-ruisdael.webp","size":[1600,1239],"title":"밀밭","artist":"야코프 판라위스달","year":"1670년경","museum":"메트로폴리탄 미술관","credit":"Jacob van Ruisdael, Wheat Fields (Metropolitan Museum of Art)","license":"CC0","page":"https://commons.wikimedia.org/wiki/File:Wheat_Fields_MET_DP145911.jpg","verse":"히브리서 10:37","lecture":"hebrews","lectureTitle":"히브리서","youtube":"nM--xhrZHU0","text":["히브리서가 꼽는 또 하나의 비교는, 그리스도께서 반드시 오신다는 것입니다.","재림이 늦어지자 낙심하고 돌아가는 사람들에게, 잠시 잠깐 후면 오실 이가 오시고 지체하지 않으시리라고 말합니다.","우리는 뒤로 물러나 침륜에 빠질 자가 아니니, 모이기를 폐하지 말고 그리스도께 돌아오라는 것이 결론입니다.","밀밭 사이로 난 길이, 큰 구름 아래 먼 곳까지 이어집니다."],"audio":"audio/471bcc8fe657.mp3","times":[0.3,7.278,16.56,25.362],"dur":30.942},{"act":12,"id":"james-jgreco","img":"img/james-jgreco.webp","size":[1289,1600],"title":"성 소야고보","artist":"엘 그레코","year":"1610–1614년경","museum":"","credit":"El Greco, St. James the Less","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:El_Greco_-_St._James_the_Less_-_Google_Art_Project.jpg","verse":"야고보서 2장","lecture":"james","lectureTitle":"야고보서","youtube":"txlRXTx9Pr8","text":["마지막 책 요한계시록을 앞두고, 남은 편지들은 믿음과 소망과 사랑을 하나씩 짚습니다.","예수님의 동생 야고보가 말하는 것은 행함이 있는 참 믿음이고, 그 행함은 바로 사랑입니다.","주님 오실 날이 가까울수록 시련은 더 세지니, 지금이야말로 인내로 열매 맺는 믿음이 필요합니다.","그림 속 야고보는 두꺼운 책을 품에 안고, 다른 손을 펼쳐 내밀고 있습니다."],"audio":"audio/1ac2aec3c5df.mp3","times":[0.3,8.214,16.248,24.546],"dur":31.446},{"act":12,"id":"peter1-prison","img":"img/peter1-prison.webp","size":[1302,1600],"title":"감옥의 성 베드로","artist":"렘브란트 판레인","year":"1631","museum":"","credit":"Rembrandt, Saint Peter in Prison","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Rembrandt_van_Rijn_-_St._Peter_in_Prison_(The_Apostle_Peter_Kneeling)_-_Google_Art_Project.jpg","verse":"베드로전서 4:12","lecture":"peter1","lectureTitle":"베드로전서","youtube":"Unk4tWmbpZU","text":["베드로는 박해가 점점 다가오는 것을 느끼며, 소망이 든든해야 박해를 이길 수 있다는 마음으로 편지를 씁니다.","내세에 대한 확신이 없으면 순교할 수 없으니, 이제 갖춰야 할 믿음은 순교를 각오하는 믿음입니다.","베드로는 감옥 바닥에 무릎을 꿇고 두 손을 모았고, 곁에는 열쇠가 놓여 있습니다."],"audio":"audio/d4d6a2f1a3be.mp3","times":[0.3,9.51,17.616],"dur":24.9},{"act":12,"id":"peter2-poussin","img":"img/peter2-poussin.webp","size":[1600,1179],"title":"겨울 (대홍수)","artist":"니콜라 푸생","year":"","museum":"","credit":"Nicolas Poussin, Winter (The Deluge)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Nicolas_Poussin_-_L%27Hiver_ou_Le_D%C3%A9luge.jpg","verse":"베드로후서 3:9","lecture":"peter2","lectureTitle":"베드로후서","youtube":"LVPqDI6PfaY","text":["베드로후서는 거짓 선지자들을 따르지 말라며, 노아 때 악했던 옛 세상처럼 이미 하나님께 심판받은 이야기를 합니다.","말세에는 주께서 강림하신다는 약속이 어디 있느냐고 비웃는 자들이 나타납니다.","그러나 주의 약속은 더딘 것이 아니라, 한 명이라도 더 회개하고 돌아오기를 바라셔서 오래 참으시는 것입니다.","그림 속 번개 치는 하늘 아래, 사람들이 불어난 물을 피해 바위로 기어오릅니다."],"audio":"audio/4d3ebb1283ca.mp3","times":[0.3,9.798,17.088,26.13],"dur":33.006},{"act":12,"id":"john1-huguet","img":"img/john1-huguet.webp","size":[1514,1600],"title":"최후의 만찬","artist":"자우메 우게트","year":"","museum":"","credit":"Jaume Huguet, The Last Supper","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Jaume_Huguet_-_Last_Supper_-_Google_Art_ProjectFXD.jpg","verse":"요한일서 4:7","lecture":"john1","lectureTitle":"요한일서","youtube":"9_CeDkDpsDQ","text":["요한일서의 첫 번째 주제는, 하나님과의 관계 회복입니다.","창세기 3장에서 하나님과 사람 사이의 신뢰가 깨졌고, 4장에서는 친형제끼리 칼부림이 나서 사람 사이의 교제도 깨졌습니다.","그러다 예수 그리스도께서 화목제물로 오셨고, 서로 사랑하라는 새 계명을 주셨습니다.","예수님과 한 상에 둘러앉은 제자들처럼, 그 사랑은 말이 아니라 행함과 진실로 열매 맺어야 합니다."],"audio":"audio/42ea66ca97bc.mp3","times":[0.3,6.078,16.488,23.85],"dur":32.262},{"act":12,"id":"jude-turner","img":"img/jude-turner.webp","size":[1600,1276],"title":"해돋이, 마게이트의 민대구잡이","artist":"조지프 맬러드 윌리엄 터너","year":"","museum":"테이트 브리튼","credit":"J. M. W. Turner, Sunrise, Whiting Fishing at Margate (Tate Britain)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:(Barcelona)_Sunrise_-_Whiting_Fishing_at_Margate_-_William_Turner_Tate_Britain.jpg","verse":"유다서 1:21","lecture":"jude","lectureTitle":"유다서","youtube":"SCU4uTcv-wY","text":["유다서의 주제는, 가만히 들어온 이단을 분별하는 것입니다.","그런 때에 자신을 믿음 위에 세우고 성령으로 기도하며, 하나님의 사랑 안에서 자신을 지키라고 합니다.","그리고 영생에 이르도록, 우리 주 예수 그리스도의 긍휼을 기다리라고 합니다.","그림 속 바다 위로 해가 떠오르고, 하늘이 아침빛으로 물들어 갑니다."],"audio":"audio/64b3679dd370.mp3","times":[0.3,5.91,14.4,21.042],"dur":27.054},{"act":13,"id":"revelation-caroto","img":"img/revelation-caroto.webp","size":[1329,1600],"title":"밧모섬의 성 요한","artist":"조반니 프란체스코 카로토","year":"1528","museum":"","credit":"Giovanni Francesco Caroto, Saint John on Patmos","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Saint_John_at_Patmos_by_Caroto_(Prague).jpg","verse":"요한계시록 1장","lecture":"revelation","lectureTitle":"요한계시록","youtube":"EFYczOkETk8","text":["그렇게 주님 오실 날을 기다리던 교회에게, 마지막 책 요한계시록이 주어집니다.","도미티아누스 황제의 박해 때, 다른 사도들은 모두 순교하고 요한 사도만 남아 교회를 지키고 있었습니다.","성도들도 교역자들도 근심과 불안과 두려움에 휩싸여 있었고, 그래서 계시록의 첫 메시지는 이것입니다, 두려워하지 말라.","그림 속 요한은 밧모섬의 바위에 턱을 괴고 앉아, 깊은 생각에 잠겨 있습니다."],"audio":"audio/c41df26c1234.mp3","times":[0.3,7.23,16.08,26.754],"dur":33.678},{"act":13,"id":"revelation-sonofman","img":"img/revelation-sonofman.webp","size":[1124,1600],"title":"인자 같은 이와 일곱 교회","artist":"작자 미상 (파쿤두스 베아투스)","year":"1047","museum":"","credit":"Beatus of Facundus, f. 46","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:B_Facundus_46.jpg","verse":"요한계시록 1:17","lecture":"revelation","lectureTitle":"요한계시록","youtube":"EFYczOkETk8","text":["주의 날, 나팔 소리 같은 큰 음성에 몸을 돌리니, 일곱 금 촛대 사이에 인자 같은 이가 서 계십니다.","요한이 죽은 사람처럼 엎드러지자, 주님이 오른손을 얹고 말씀하십니다.","두려워 말라, 나는 처음이요 나중이니 곧 산 자라.","그림 속 주님은 엎드린 요한에게 손을 얹고 계시고, 아래쪽 일곱 아치에는 일곱 교회의 이름이 적혀 있습니다."],"audio":"audio/ab1f3a55c214.mp3","times":[0.3,9.15,15.816,21.258],"dur":30.006},{"act":13,"id":"revelation-vitale","img":"img/revelation-vitale.webp","size":[1600,1559],"title":"하나님의 어린양","artist":"작자 미상","year":"","museum":"라벤나 산비탈레 성당","credit":"Agnus Dei mosaic, San Vitale, Ravenna","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Agnus_dei_-_San_Vitale,_Ravenna.jpg","verse":"요한계시록 5장","lecture":"revelation","lectureTitle":"요한계시록","youtube":"EFYczOkETk8","text":["4장에서 요한은 하늘에 열린 문으로 올라가, 하늘의 예배를 봅니다.","보좌에 앉으신 이의 오른손에 일곱 인으로 봉한 책이 있는데, 누가 그 인을 떼기에 합당하냐는 외침이 울립니다.","그때 어린양이 나와서 그 책을 받으시니, 어린양은 예수님이십니다.","그림 속 흰 어린양은 별이 뜬 푸른 하늘 속, 둥근 화환 한가운데 서 있습니다."],"audio":"audio/21ee07ef1cf3.mp3","times":[0.3,6.39,15.528,21.954],"dur":28.878},{"act":13,"id":"revelation-horsemen","img":"img/revelation-horsemen.webp","size":[1115,1600],"title":"네 말 탄 자","artist":"작자 미상 (파쿤두스 베아투스)","year":"1047","museum":"","credit":"Beatus of Facundus, f. 135","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:B_Facundus_135.jpg","verse":"요한계시록 6장","lecture":"revelation","lectureTitle":"요한계시록","youtube":"EFYczOkETk8","text":["6장부터 어린양이 인을 하나씩 떼십니다.","흰 말은 이기고 또 이기려는 끝없는 전쟁, 붉은 말은 전쟁, 검은 말은 심한 기근, 청황색 말은 죽음입니다.","넷째 인 때에는 이 땅의 4분의 1이 죽는 일이 일어납니다.","그림 아래쪽, 검은 말을 탄 자가 손에 든 저울은 심한 기근을 나타내는 그림 언어입니다."],"audio":"audio/1d347acb8d05.mp3","times":[0.3,4.878,15.024,20.658],"dur":28.326},{"act":13,"id":"revelation-eruption","img":"img/revelation-eruption.webp","size":[1600,1136],"title":"분화하는 베수비오 화산","artist":"더비의 조지프 라이트","year":"1776년경","museum":"","credit":"Joseph Wright of Derby, Vesuvius in Eruption","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Joseph_Wright_of_Derby_-_Vesuvius_in_Eruption,_with_a_View_over_the_Islands_in_the_Bay_of_Naples_-_Google_Art_Project.jpg","verse":"요한계시록 6:12","lecture":"revelation","lectureTitle":"요한계시록","youtube":"EFYczOkETk8","text":["여섯째 인을 떼면 큰 지진이 나고, 해가 검어지고, 하늘의 별들이 땅에 떨어집니다.","하늘이 없어지고, 산과 섬이 옮겨질 만큼 큰 지진입니다.","그러자 사람들이 말합니다, 산아, 바위야, 우리를 가려 다오.","그림 속 산이 불을 뿜어 올리는 이때가, 마지막 회개의 기회입니다."],"audio":"audio/04554d7ca649.mp3","times":[0.3,8.07,14.016,20.682],"dur":26.526},{"act":13,"id":"revelation-homage","img":"img/revelation-homage.webp","size":[974,1176],"title":"어린양 앞의 큰 무리","artist":"작자 미상 (밤베르크 묵시록)","year":"1000년경","museum":"","credit":"Bamberg Apocalypse, f. 18v","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:BambergApocalypseFolio018vHomageToLamb.JPG","verse":"요한계시록 7장","lecture":"revelation","lectureTitle":"요한계시록","youtube":"EFYczOkETk8","text":["7장, 그때 회개한 사람들의 이마에 인을 칩니다.","유대인 열두 지파에서 만 이천 명씩 십사만 사천 명, 그리고 온 세계에서 기독교인들이 나옵니다.","그림 위쪽, 종려 가지를 든 무리가 바위 위에 선 어린양을 바라봅니다.","이 사람들은 모두, 어린양의 피로 씻은 사람들입니다."],"audio":"audio/f5ab7d410311.mp3","times":[0.3,5.646,14.304,20.97],"dur":26.214},{"act":13,"id":"revelation-littlebook","img":"img/revelation-littlebook.webp","size":[1131,1002],"title":"작은 책을 든 천사","artist":"작자 미상 (밤베르크 묵시록)","year":"1000년경","museum":"","credit":"Bamberg Apocalypse, f. 25v","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:BambergApocalypseFolio025vAngelWithLittleBook.JPG","verse":"요한계시록 10:7","lecture":"revelation","lectureTitle":"요한계시록","youtube":"EFYczOkETk8","text":["일곱째 인은 일곱 나팔을 가지고 나오고, 나팔을 불 때마다 나무와 바다와 민물과 하늘의 3분의 1이 상합니다.","10장, 한 발은 바다를, 한 발은 땅을 딛고 선 천사가 맹세합니다, 일곱째 천사가 나팔을 불 때 하나님의 비밀이 이루어지리라.","그 비밀은 마지막 나팔에 홀연히 다 변화하는 것, 곧 휴거와 예수님의 재림입니다.","그림 속 천사는 펼친 책을 들고, 요한 쪽으로 내밀고 있습니다."],"audio":"audio/130906a8cdf4.mp3","times":[0.3,9.606,20.52,28.194],"dur":34.326},{"act":13,"id":"revelation-dragon","img":"img/revelation-dragon.webp","size":[1256,1600],"title":"해를 입은 여자와 용","artist":"작자 미상 (파쿤두스 베아투스)","year":"1047","museum":"","credit":"Beatus of Facundus, f. 186v","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:B_Facundus_186v.jpg","verse":"요한계시록 12:1","lecture":"revelation","lectureTitle":"요한계시록","youtube":"EFYczOkETk8","text":["일곱째 나팔을 부는 순간 역사가 멈추고, 요한은 12장부터 14장까지 영적 세계의 시작부터 지금까지를 굵직하게 보여 줍니다.","12장, 해를 입은 한 여자가 머리에 열두 별의 면류관을 쓰고, 발아래에는 달이 있습니다.","이 여인은 마리아가 아니라 이스라엘 나라이고, 여인이 가진 남자아이가 예수님입니다.","그림 왼쪽 위의 여인을 향해, 머리가 일곱인 붉은 용이 목을 길게 뻗고 있습니다."],"audio":"audio/ae6bc2f63a5e.mp3","times":[0.3,11.142,19.368,27.018],"dur":34.206},{"act":13,"id":"revelation-zion","img":"img/revelation-zion.webp","size":[1184,1600],"title":"시온산의 어린양","artist":"작자 미상 (파쿤두스 베아투스)","year":"1047","museum":"","credit":"Beatus of Facundus, f. 205r","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Beatus-de-Facundus_,_page_f%C2%B0_205r_,_aka_page_410.jpg","verse":"요한계시록 14:12","lecture":"revelation","lectureTitle":"요한계시록","youtube":"EFYczOkETk8","text":["13장에서는 짐승들이 나와 성도들을 괴롭히고, 육백육십육 표를 받지 않으면 사고팔지 못하게 합니다.","14장은 마지막까지 참으라고 권하는 환상입니다.","그림 속 어린양은 시온산 꼭대기에 서 있고, 거룩한 사람들이 거문고를 들고 둘러서 있습니다.","아무리 힘들어도 표를 받지 말고 참으라, 성도의 인내가 여기 있습니다."],"audio":"audio/0015d87ccc52.mp3","times":[0.3,9.558,14.832,23.034],"dur":29.262},{"act":13,"id":"revelation-sunset","img":"img/revelation-sunset.webp","size":[1600,1256],"title":"바다","artist":"이반 아이바좁스키","year":"1864","museum":"","credit":"Ivan Aivazovsky, The Sea (1864)","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:1864_Aivazovsky_Meer_anagoria.JPG","verse":"요한계시록 15:3","lecture":"revelation","lectureTitle":"요한계시록","youtube":"EFYczOkETk8","text":["아득한 옛날부터 여기까지 왔는데, 그 순간 성도들은 눈 깜짝할 사이에 휴거되어 가 버립니다.","15장, 유리바다 건너편에서 변화된 성도들이 모세의 노래, 어린양의 노래를 부릅니다.","바로의 군대가 홍해에 잠겼을 때 부른 노래가 예표였고, 이제 실제로 이루어진 것입니다.","그림 속 바다는 낮게 뜬 해의 빛을 받아, 유리처럼 고요하게 빛납니다."],"audio":"audio/8f860f923be5.mp3","times":[0.3,8.646,16.776,24.642],"dur":31.134},{"act":13,"id":"revelation-hail","img":"img/revelation-hail.webp","size":[1600,1133],"title":"일곱째 대접","artist":"작자 미상 (앙제 묵시록 태피스트리)","year":"","museum":"","credit":"Apocalypse Tapestry, Angers (photo: Remi Jouan)","license":"CC BY-SA 3.0","page":"https://commons.wikimedia.org/wiki/File:Angers-_Apocalypse_(10).JPG","verse":"요한계시록 16장","lecture":"revelation","lectureTitle":"요한계시록","youtube":"EFYczOkETk8","text":["성도들이 유리바다를 건너간 뒤, 불신자들만 남은 땅에 진노의 일곱 대접이 쏟아집니다.","독한 종기, 피가 된 바다와 강물, 타는 태양과 흑암이 차례로 내리고, 일곱째 대접에는 지진과 우박으로 온 천지가 박살이 납니다.","그림 속 천사가 하늘에서 대접을 쏟자, 성의 지붕과 벽이 무너져 내립니다.","이렇게 되어도, 사람들은 회개하지 않습니다."],"audio":"audio/f9a902869800.mp3","times":[0.3,8.358,19.944,26.946],"dur":31.494},{"act":13,"id":"revelation-melozzo","img":"img/revelation-melozzo.webp","size":[1320,1600],"title":"악기를 연주하는 천사","artist":"멜로초 다 포를리","year":"","museum":"","credit":"Melozzo da Forlì, Angel Musician (photo: Richard Mortel from Riyadh, Saudi Arabia)","license":"CC BY 2.0","page":"https://commons.wikimedia.org/wiki/File:Melozzo_da_Forli,_Angel_Musician,_fresco_from_Santi_Apostoli_in_Rome,_1472-74;_Vatican_Museums_(2)_(48759136157).jpg","verse":"요한계시록 19장","lecture":"revelation","lectureTitle":"요한계시록","youtube":"EFYczOkETk8","text":["17장과 18장에서 음녀와 마지막 바벨론이 멸망하고, 19장에서 카메라는 다시 유리바다 건너편 성도들을 비춥니다.","시편 150편에서 마지막으로 울렸던 할렐루야가, 드디어 터져 나옵니다.","할렐루야가 울려 퍼지는 가운데 예수님이 내려오시고, 성도들은 공중에서 주님을 영접합니다.","그림 속 천사는 푸른 하늘을 배경으로, 금빛 머리카락을 늘어뜨린 채 악기를 켜고 있습니다."],"audio":"audio/166c46b4ae40.mp3","times":[0.3,10.542,17.208,25.194],"dur":33.078},{"act":13,"id":"revelation-newjer","img":"img/revelation-newjer.webp","size":[979,1234],"title":"새 예루살렘을 보여 주는 천사","artist":"작자 미상 (밤베르크 묵시록)","year":"1000년경","museum":"","credit":"Bamberg Apocalypse, f. 55r","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:BambergApocalypseFolio055rNew_Jerusalem.JPG","verse":"요한계시록 21:2","lecture":"revelation","lectureTitle":"요한계시록","youtube":"EFYczOkETk8","text":["천년왕국이 지나고 크고 흰 보좌의 심판까지 끝나면, 새 하늘과 새 땅이 열립니다.","천사가 한 가지만 더 보여 주겠다며, 요한을 데리고 갑니다.","어린양의 신부 새 예루살렘이, 신부가 신랑을 위해 단장한 것처럼 아름답게 위에서 내려옵니다.","그림 속 천사는 요한의 손을 잡아 이끌고, 둥근 성벽 한가운데에는 어린양이 서 있습니다."],"audio":"audio/42c126e29471.mp3","times":[0.3,7.974,13.896,22.242],"dur":30.006},{"act":13,"id":"revelation-city","img":"img/revelation-city.webp","size":[1351,1600],"title":"새 예루살렘","artist":"작자 미상 (파쿤두스 베아투스)","year":"1047","museum":"","credit":"Beatus of Facundus, f. 253v","license":"Public domain","page":"https://commons.wikimedia.org/wiki/File:B_Facundus_253v.jpg","verse":"요한계시록 22:2","lecture":"revelation","lectureTitle":"요한계시록","youtube":"EFYczOkETk8","text":["그림 속 새 예루살렘은 반듯한 네모 모양의 성으로, 열두 문에 둘러싸인 한가운데에 어린양이 서 있습니다.","성 안의 길은 유리 같은 정금이고, 그 성 안에 생명수가 흐릅니다.","강 양쪽에 생명수 나무가 있어 매월 다른 열매를 맺는데, 이것을 따 먹어야 진짜 영생하는 것입니다.","태초의 동산에서 시작된 이야기는, 이렇게 생명수 강가에서 끝을 맺습니다."],"audio":"audio/3ac99453dedc.mp3","times":[0.3,9.222,15.504,24.258],"dur":30.822}]};
